#!/usr/bin/env python3
"""Inventory the DART C++ declarations referenced by Gazebo C++ sources.

This lexical, best-effort inventory records uses it can resolve. Unresolved
receivers retain conservative declaration candidates and an explicit count.
Known limitations:
- Namespace using-directives and aliases are treated file-wide.
- Source fields are keyed by name across owners.
- Function-local type aliases are not collected.
- Function-local classes and their virtual overrides are not collected.
- DART headers are indexed globally; transitive include availability and per-source declaration visibility are not tracked.
- Destructor and managed-lifetime requirements are not recorded.
- Implicit and contextual conversion operators are not recorded.
- Structured-binding element types are not inferred.
- Preprocessor conditions are not generally evaluated.
- C++ template instantiation and overload resolution are not performed.
- Ignored in-tree build artifacts are scanned as Gazebo sources.
- Virtual destructor overrides are not recorded.
- Referenced macro parameters and replacement tokens are not recorded.
- Source-only inheritance chains beyond three hops can be missed.
- Used type-alias target definitions outside field layout dependencies are not recorded.
- Qualified member-function references without calls are not recorded.
- Dependent `receiver->template method<T>()` calls are not recognized.
- Base relationships of referenced DART types are not recorded.
- Trailing return types are not used to infer chained-call receivers.
- Availability of headers generated by CMake is not checked.

Operator syntax is associated with declarations for `->`, `[]` and `()` when
the receiver type is known. The Gazebo build and test lanes remain the
authoritative compatibility check.
Type lookup uses tracked scopes, from the innermost namespace or class,
including the class of an out-of-line member definition and the bases of
enclosing classes. A type alias is visible only in its file and in the files
that include it. Type aliases declared inside function bodies are not collected.

A construction lists the constructors of the type, its bases and owned
non-static members, including class template specializations. These are
conservative candidates; overload resolution is not performed. A Gazebo class
derived from a DART class constructs that base, so its base clause counts as a
construction and retains the base's pure-virtual declarations.
Brace constructions of classes without declared constructors also retain public
non-static fields in declaration order as `brace_member_declarations`. This is
lexical field evidence; it does not establish C++ aggregate eligibility.
Braced returns use their enclosing function's declared return type. Value-owned
tuple/pair elements retain construction dependencies, and constructions retain
constants named in default field initializers. Source helpers with deduced
returns infer receiver candidates from their own return expressions.
Indexed field and constant initializers and used function declarations retain
quoted literals as evidence; their contents remain excluded from C++ token
matching. Function bodies and comments remain excluded.
By-value types and sizeof/alignof operands retain ordered non-static field
declarations and value-owned subobjects as layout evidence. Concrete decltype
declarations and inferred free-function pointers preserve receiver shapes.
Referenced types retain normalized alignment specifiers and their type/constant
dependencies, and class annotations such as export macro spellings. Used
declarations retain constants named in parameter defaults, exception conditions,
bit-field widths and array bounds. Members retain declared access, and free
functions retain all indexed signature candidates. Conditional receivers keep
both operand candidates; sequence iterators preserve their element shapes.
These are lexical dependencies, without computing C++ layout or evaluating
constant expressions.

Preprocessor conditions are not evaluated, except that a literal `#if 0` or
`#if 1` drops the branches it rules out. Every other branch is scanned, so the
inventory also lists uses that only a branch inactive in a given build makes.
A use takes the types of every declaration that some build lets it see, so a
variable declared in a branch does not hide other declarations of it from uses
outside that branch. A type alias or Gazebo class defined differently in
alternative branches keeps one of its definitions.
"""

import argparse
import difflib
import json
import posixpath
import re
import subprocess
import sys
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_OUTPUT = ROOT / "tools/gazebo/compat/dart_api_inventory.json"
CPP_SUFFIXES = {
    ".h",
    ".hh",
    ".hpp",
    ".hxx",
    ".c",
    ".cc",
    ".cpp",
    ".cxx",
    ".ipp",
    ".tpp",
}
IDENTIFIER = re.compile(r"^[A-Za-z_]\w*$")
TOKEN = re.compile(r"[A-Za-z_]\w*|::|->|##|\.\.\.|&&|[^\s]")
IGNORED = re.compile(
    r'//[^\n]*|/\*[\s\S]*?\*/|(?:u8|u|U|L)?R"([^ ()\\\t\r\n]*)\([\s\S]*?\)\1"'
    r'|(?:u8|u|U|L)?"(?:\\[\s\S]|[^"\\])*"|(?:u|U|L)?\'(?:\\[\s\S]|[^\'\\])*\''
)
CONDITIONAL = re.compile(r"[ \t]*#[ \t]*(if|ifdef|ifndef|elif|else|endif)\b(.*)")
INCLUDE = re.compile(r'^[ \t]*#[ \t]*include[ \t]*[<"]([^>"\n]+)[>"]', re.MULTILINE)
THIRD_PARTY = re.compile(r"(?:bt|d|ai)[A-Z]")  # Bullet, ODE and Assimp types
BLOCK = 1 << 30  # lookup depth of a block scope, past any namespace or class
RAW_POINTER = "__raw_pointer__"
RAW_ARRAY = "__raw_array__"
ITERATOR = "__iterator__"
ELEMENT_CONTAINERS = {
    "std::vector",
    "std::array",
    "std::deque",
    "std::list",
    "std::forward_list",
    "std::set",
    "std::unordered_set",
    "std::multiset",
    "std::unordered_multiset",
}
SIZED_SEQUENCES = ELEMENT_CONTAINERS - {
    "std::array",
    "std::set",
    "std::unordered_set",
    "std::multiset",
    "std::unordered_multiset",
}
MAP_CONTAINERS = {
    "std::map",
    "std::multimap",
    "std::unordered_map",
    "std::unordered_multimap",
}
MAPPING = "__mapping__"
MULTIMAPPING = "__multimapping__"
OPTIONAL = "__optional__:"
ARRAY_IDENTITY = "__array_identity__:"  # internal: a declared std::array's type
OPTIONAL_ELEMENT = "__optional_element__:"  # a declared optional's element type
PRODUCTS = {"std::pair": "__pair__:", "std::tuple": "__tuple__:"}
# `position` is the iterator member of C++17 node_type insertion results.
PAIR_MEMBERS = {"first", "second", "position"}
SMART_POINTERS = {
    "std::shared_ptr": "__shared_ptr__:",
    "std::unique_ptr": "__unique_ptr__:",
    "std::weak_ptr": "__weak_ptr__:",
}
SOURCE_CLASS = "__source_class__:"
NON_DART_CALLABLE = "__non_dart_callable__"
CALLABLE = "__callable__:"
ASSOCIATED = "__associated__:"
REFERENCE = "__reference__"
INLINE_LAYOUT = "__inline_layout__:"
NO_INLINE_LAYOUT = "__no_inline_layout__"
DECLARED_TYPE = "__declared_type__"
NOT_DATA = {
    "(",
    ":",
    "~",
    "class",
    "enum",
    "friend",
    "namespace",
    "operator",
    "return",
    "static_assert",
    "struct",
    "template",
    "typedef",
    "union",
    "using",
}


def strip_comments_and_strings(text):
    """Keep byte offsets and line numbers while hiding comments and literals."""
    return IGNORED.sub(lambda match: re.sub(r"[^\n]", " ", match.group()), text)


def preprocess(text):
    """Blank the branches that a literal `#if 0` or `#if 1` rules out.

    Other conditions are not evaluated, so all their branches stay. Returns the
    text and, for each line, the (conditional, branch) pairs that enclose it.
    """
    frames = []  # [conditional, branch, active, decided]
    lines, branches = [], []
    dead = continued = False
    for line in text.split("\n"):
        match = None if continued else CONDITIONAL.match(line)
        if match and (match[1].startswith("if") or frames):
            keyword, condition = match[1], match[2].strip()
            if keyword.startswith("if"):
                frames.append([len(branches), -1, True, False])
            frame = frames[-1]
            dead = not all(outer[2] for outer in frames[:-1])
            if keyword == "endif":
                frames.pop()
            else:
                literal = condition if keyword in {"if", "elif"} else None
                literal = "1" if keyword == "else" else literal
                frame[1] += 1
                frame[2] = not frame[3] and literal != "0"
                frame[3] = frame[3] or literal == "1"
        elif not continued:
            dead = not all(frame[2] for frame in frames)
        continued = line.rstrip().endswith("\\")
        lines.append(" " * len(line) if dead else line)
        branches.append(tuple((frame[0], frame[1]) for frame in frames))
    return "\n".join(lines), branches


def compatible(first, second):
    """Whether lines in these conditional branches can compile together."""
    branches = dict(first)
    return all(branches.get(key, branch) == branch for key, branch in second)


def strip_directives(text):
    result = []
    continuation = False
    for line in text.splitlines(keepends=True):
        directive = continuation or line.lstrip().startswith("#")
        continuation = directive and line.rstrip().endswith("\\")
        result.append(re.sub(r"[^\n]", " ", line) if directive else line)
    return "".join(result)


def header_macros(text):
    macros = {}
    text = text.replace("\\\n", " ")
    for match in re.finditer(
        r"^[ \t]*#[ \t]*define[ \t]+(_?DART_\w+)(\(([^)]*)\))?[ \t]*(.*)$",
        text,
        re.MULTILINE,
    ):
        parameters = (
            None if match[2] is None else [p.strip() for p in match[3].split(",")]
        )
        macros[match[1]] = (parameters, TOKEN.findall(match[4]))
    return macros


def expand_macros(values, macros, active=()):
    """Expand DART declaration macros, including token-pasted accessor names."""
    result = []
    i = 0
    while i < len(values):
        name = values[i]
        if name not in macros or name in active or len(active) >= 16:
            result.append(name)
            i += 1
            continue
        parameters, body = macros[name]
        end = i + 1
        arguments = []
        if parameters is not None:
            if end == len(values) or values[end] != "(":
                result.append(name)
                i += 1
                continue
            end += 1
            depth = 1
            argument = []
            while end < len(values) and depth:
                token = values[end]
                depth += (token == "(") - (token == ")")
                if depth == 0 or (token == "," and depth == 1):
                    arguments.append(argument)
                    argument = []
                else:
                    argument.append(token)
                end += 1
            if depth or len(arguments) != len(parameters):
                result.append(name)
                i += 1
                continue
        substitutions = dict(zip(parameters or [], arguments))
        replacement = []
        for token in body:
            replacement.extend(substitutions.get(token, [token]))
        pasted = []
        j = 0
        while j < len(replacement):
            if replacement[j] == "##" and pasted and j + 1 < len(replacement):
                pasted[-1] += replacement[j + 1]
                j += 2
            else:
                pasted.append(replacement[j])
                j += 1
        result.extend(expand_macros(pasted, macros, active + (name,)))
        i = end
    return result


def annotation_macro(name, macros, active=()):
    """DART export/attribute macros, excluding declaration generators and types."""
    if name in active or len(active) >= 16:
        return False
    if name not in macros:
        return name.startswith("DART_") and name.endswith("_API")
    _, body = macros[name]
    if any(value in {";", "{", "}"} for value in body):
        return False
    return (
        not body
        and name.endswith(("_API", "_EXPORT", "_IMPORT"))
        or any(value in {"__attribute__", "__declspec"} for value in body)
        or any(
            annotation_macro(value, macros, active + (name,))
            for value in body
            if value in macros
        )
    )


def function_annotations(tokens, text, first, stop, macros):
    """Raw annotations in a declaration prefix/suffix, outside nested type expressions."""
    result, index = [], first
    while index < stop:
        value = tokens.values[index]
        attribute = value in {"__attribute__", "__declspec"} or tokens.values[
            index : index + 2
        ] == ["[", "["]
        if attribute or annotation_macro(value, macros):
            end = index + 1
            opening = index if value == "[" else end
            if opening in tokens.pairs and tokens.values[opening] in {"(", "["}:
                end = tokens.pairs[opening] + 1
            raw = text[
                tokens.offsets[index] : tokens.offsets[end - 1]
                + len(tokens.values[end - 1])
            ]
            result.append(
                " ".join(
                    match.group()
                    for match in re.finditer(IGNORED.pattern + "|" + TOKEN.pattern, raw)
                    if not match.group().startswith(("//", "/*"))
                )
            )
            index = end
        elif value in {"(", "[", "{"} and index in tokens.pairs:
            index = tokens.pairs[index] + 1
        elif value == "<":
            index = template_end(tokens.values, index)
        else:
            index += 1
    return result


def source_files(root):
    return sorted(
        path
        for path in root.rglob("*")
        if path.is_file()
        and ".git" not in path.parts
        and (path.suffix in CPP_SUFFIXES or path.name.endswith(".hpp.in"))
    )


@dataclass
class Tokens:
    text: str
    values: list = field(init=False)
    offsets: list = field(init=False)
    pairs: dict = field(init=False)
    enclosing: list = field(init=False)
    scopes: dict = field(default_factory=dict)
    bodies: dict = field(default_factory=dict)
    bindings: list = field(default_factory=list)
    branches: list = field(default_factory=list)
    aliases: dict = field(default_factory=dict)
    wrapped: set = field(default_factory=set)
    raw_pointers: set = field(default_factory=set)
    using: list = field(default_factory=list)
    template_headers: dict = field(default_factory=lambda: defaultdict(set))
    alias_templates: dict = field(default_factory=dict)
    alias_parameters: dict = field(default_factory=dict)
    alias_defaults: dict = field(default_factory=dict)
    alias_packs: dict = field(default_factory=dict)
    ambiguous: bool = False  # a whole-array copy decision awaits inferred types
    late: bool = False  # inference has finished
    enum_headers: dict = field(default_factory=lambda: defaultdict(set))
    union_headers: dict = field(default_factory=lambda: defaultdict(set))
    alignment_headers: dict = field(default_factory=lambda: defaultdict(set))
    annotation_headers: dict = field(default_factory=lambda: defaultdict(set))
    macros: set = field(default_factory=set)

    def __post_init__(self):
        matches = list(TOKEN.finditer(self.text))
        self.values = [match.group() for match in matches]
        self.offsets = [match.start() for match in matches]
        self.pairs = {}
        self.enclosing = []
        stack = []
        for i, value in enumerate(self.values):
            self.enclosing.append(stack[-1][1] if stack else None)
            if value in ("(", "{", "["):
                stack.append((value, i))
            elif value in (")", "}", "]") and stack:
                opening, index = stack[-1]
                if opening == {")": "(", "}": "{", "]": "["}[value]:
                    stack.pop()
                    self.pairs[index] = i
                    self.pairs[i] = index

    def line(self, index):
        return self.text.count("\n", 0, self.offsets[index]) + 1


def qualified(values):
    return "".join(values).lstrip(":")


# MSVC pointer-width modifiers change the field size, so they stay in storage.
POINTER_WIDTHS = {"__ptr32", "__ptr64"}
CALLING_CONVENTIONS = {
    "__cdecl",
    "__clrcall",
    "__fastcall",
    "__stdcall",
    "__thiscall",
    "__vectorcall",
    "_cdecl",
    "_fastcall",
    "_stdcall",
}


def outer_type_tokens(values):
    """Drop only leading cv/storage specifiers, preserving nested type tokens."""
    storage = {
        "const",
        "volatile",
        "extern",
        "static",
        "inline",
        "mutable",
        "thread_local",
        "constexpr",
    }
    start = 0
    while values[start : start + 1] and values[start] in storage:
        start += 1
    return values[start:]


def array_identity(values, api):
    """A declared std::array of DART-dependent elements: its exact type tokens
    and outer pointer depth. Only the qualifiers around the array are dropped."""
    values = outer_type_tokens(values)
    if values[:3] != ["std", "::", "array"] or values[3:4] != ["<"]:
        return None
    end = template_end(values, 3)
    if not set(values[end:]) <= {"*", "&", "&&", "const", "volatile"} or not any(
        api.owner(api.resolve(name, ())) for _, _, name in names_in(values[:end])
    ):
        return None
    return values[:end], values[end:].count("*")


def array_marker(identity):
    """The private receiver marker for an array identity."""
    return ARRAY_IDENTITY + f"{identity[1]}|" + " ".join(identity[0])


def parse_array_marker_key(marker):
    depth, _, spelling = marker.removeprefix(ARRAY_IDENTITY).partition("|")
    return spelling, int(depth)


def shift_array_depth(types, delta):
    """Move only private top-level array identities through a builtin unary op."""
    result = set()
    for value in types:
        if value.startswith(ARRAY_IDENTITY):
            spelling, depth = parse_array_marker_key(value)
            if depth + delta >= 0:
                result.add(array_marker((TOKEN.findall(spelling), depth + delta)))
        else:
            result.add(value)
    return result


def template_parameter_names(header):
    """Names of the type/non-type parameters a `template <...>` header declares."""
    return set(filter(None, template_parameter_list(header)))


def template_parameter_list(header):
    """Each parameter's name, or None when unnamed, in declaration order."""
    result = []
    for part in template_arguments(header, 1):
        before = len(result)
        default = next(
            (
                index
                for index, value in enumerate(part)
                if value == "=" and not in_template_argument(part, index)
            ),
            len(part),
        )
        part = part[:default]
        names = [value for value in part if IDENTIFIER.match(value)]
        if (
            names
            and part[-1] == names[-1]
            and part[-2:-1] != ["::"]
            and names[-1] not in {"class", "typename", "const", "volatile"}
        ):
            result.append(names[-1])
        elif grouped := next(  # `T (&A)[2]`, `T (*A)[2]`, `T (*A)()`
            (
                part[closing - 1]
                for opening, closing in Tokens(" ".join(part)).pairs.items()
                if opening < closing
                and part[opening] == "("
                and part[closing + 1 : closing + 2] in (["["], ["("])
                and not in_template_argument(part, opening)
                and IDENTIFIER.match(part[closing - 1])
                and part[closing - 1] not in {"const", "volatile"}
                and part[opening + 1 : closing - 1]
                and set(part[opening + 1 : closing - 1])
                <= {"*", "&", "&&", "const", "volatile"}
            ),
            None,
        ):
            result.append(grouped)
        elif (
            (member := data_member(part, None))
            and member["name"]
            and (member["array_dimensions"] or function_pointer_name(part))
        ):
            result.append(member["name"])  # grouped or array non-type parameter
        if len(result) == before:
            result.append(None)
    return result


def function_pointer_declarator(values):
    """A grouped callable's element type, name and surrounding array shape."""
    tokens = Tokens(" ".join(values))
    for opening, closing in tokens.pairs.items():
        if (
            opening >= closing
            or values[opening] != "("
            or in_template_argument(values, opening)
            or values[closing + 1 : closing + 2] != ["("]
        ):
            continue
        if tokens.enclosing[opening] is not None:
            # A callable that returns a callable, `T (*(*f)())()`: the inner
            # group is the stored declarator and the outer one its returned type.
            outer = tokens.enclosing[opening]
            if (
                values[outer] != "("
                or tokens.enclosing[outer] is not None
                or in_template_argument(values, outer)
                or values[tokens.pairs[outer] + 1 : tokens.pairs[outer] + 2] != ["("]
                or tokens.pairs.get(closing + 1) != tokens.pairs[outer] - 1
                or not values[outer + 1 : opening]
                or not set(values[outer + 1 : opening])
                <= {"*", "&", "&&", "const", "volatile"} | POINTER_WIDTHS
            ):
                continue
        name = opening + 1
        attributes = set()
        group, inside = closing, opening  # innermost redundant grouping
        while values[name : name + 1] == ["("] and tokens.pairs.get(name) == group - 1:
            attributes.add(name)
            inside = name
            name += 1
            group -= 1
        while values[name : name + 1] and values[name] in CALLING_CONVENTIONS:
            attributes.add(name)
            name += 1
        member_pointer = False
        if values[name : name + 1] not in (["*"], ["&"], ["&&"]):
            name = next(
                (
                    index + 1
                    for index in range(name + 1, group - 1)
                    if values[index : index + 2] == ["::", "*"]
                    and tokens.enclosing[index] == inside
                    and not in_template_argument(values, index)
                ),
                group,
            )
            member_pointer = name < group
        if name == group:
            continue
        widths = []
        while name < group:
            if values[name] in {"*", "&", "&&", "const", "volatile"} | POINTER_WIDTHS:
                if values[name] in POINTER_WIDTHS:
                    widths.append(name)
                name += 1
            elif values[name] in CALLING_CONVENTIONS:
                attributes.add(name)
                name += 1
            elif (
                values[name] in {"__attribute__", "__attribute", "alignas"}
                and values[name + 1 : name + 2] == ["("]
                and name + 1 in tokens.pairs
            ):
                stop = tokens.pairs[name + 1] + 1
                attributes.update(range(name, stop))
                name = stop
            elif (
                values[name : name + 2] == ["[", "["]
                and name in tokens.pairs
                and tokens.pairs.get(name + 1) == tokens.pairs[name] - 1
            ):
                stop = tokens.pairs[name] + 1
                attributes.update(range(name, stop))
                name = stop
            else:
                break
        element_end = name
        outer = []
        nested_end = None
        if values[name : name + 1] == ["("] and name in tokens.pairs:
            nested_end = tokens.pairs[name]
            name += 1
            while (
                name < nested_end
                and values[name]
                in {
                    "*",
                    "&",
                    "&&",
                    "const",
                    "volatile",
                }
                | POINTER_WIDTHS
            ):
                outer.append(values[name])
                name += 1
        name_index = name if name < group and IDENTIFIER.match(values[name]) else None
        suffix = name + 1 if name_index is not None else name
        dimensions = 0
        if nested_end is not None:
            bounds, suffix = array_bounds(tokens, suffix)
            dimensions += len(bounds)
            if suffix != nested_end:
                continue
            suffix += 1
        while True:
            suffix = declarator_attributes_end(tokens, suffix)
            if values[suffix : suffix + 1] != ["["] or suffix not in tokens.pairs:
                break
            dimensions += 1
            suffix = tokens.pairs[suffix] + 1
        if suffix == group:
            parameters_end = tokens.pairs.get(closing + 1, closing)
            trailing = parameters_end + 1
            if name_index is None:
                # Alias expansion can append array dimensions to a callable type.
                while (
                    values[trailing : trailing + 1] == ["["]
                    and trailing in tokens.pairs
                ):
                    dimensions += 1
                    trailing = tokens.pairs[trailing] + 1
                if trailing > parameters_end + 1:
                    outer.extend(values[trailing:])
            return {
                "name_index": name_index,
                "opening": opening,
                "inside": inside,
                "parameters_end": parameters_end,
                "return_tokens": [
                    value
                    for index, value in enumerate(values[:element_end])
                    if index not in attributes
                ]
                + (
                    values[closing : parameters_end + 1]
                    if trailing > parameters_end + 1
                    else values[closing:]
                ),
                "array_dimensions": dimensions,
                "member_pointer": member_pointer,
                "array_pointer": dimensions > 0 and "*" in outer,
                "array_reference": dimensions > 0
                and bool({"&", "&&"}.intersection(outer)),
                "element_widths": widths,
            }
    return None


def function_pointer_name(values):
    """The name in a plain grouped function-pointer/reference declarator."""
    pointer = function_pointer_declarator(values)
    if pointer and pointer["name_index"] is not None:
        return pointer["name_index"], pointer["parameters_end"]
    return None


def function_type_signature(values):
    """A known abstract function type's parameter span and declarator suffix."""
    if function_pointer_declarator(values):
        return None
    tokens = Tokens(" ".join(values))
    result = None
    for opening, closing in tokens.pairs.items():
        if (
            opening < closing
            and values[opening] == "("
            and opening
            and tokens.enclosing[opening] is None
            and not in_template_argument(values, opening)
            and values[opening - 1]
            not in {
                "decltype",
                "noexcept",
                "alignas",
                "__attribute__",
                "__attribute",
                "__declspec",
            }
        ):
            result = {
                "opening": opening,
                "parameters_end": closing,
                "return_tokens": values[:opening],
                "suffix": values[closing + 1 :],
            }
    return result


def real_function(item):
    """A parsed function with a real return type, not a constructor or type parse."""
    returns = item["return_tokens"]
    # A member named for its class is a constructor, even `explicit H(int)`.
    owner = (item.get("class") or "").split("::")[-1]
    if owner and item["name"].split("::")[-1] == owner:
        return False
    # A trailing tag keyword means the "name" is that tag's name: `struct T (v)`.
    return (
        bool(returns)
        and returns[-1] not in {"::", "struct", "class", "union", "enum"}
        # A trailing `~` is a destructor; an inner one is `decltype(~0)`.
        and returns[-1] != "~"
        and not any(value in {"typedef", "using"} for value in returns)
    )


def grouped_declarator_name(values):
    """A sole grouped name immediately after a declaration's type prefix."""
    tokens = Tokens(" ".join(values))
    qualifiers = {
        "const",
        "volatile",
        "typename",
        "class",
        "struct",
        "union",
        "typedef",
        "static",
        "extern",
        "inline",
        "virtual",
        "friend",
        "constexpr",
        "mutable",
        "thread_local",
    }
    builtins = {
        "void",
        "bool",
        "char",
        "signed",
        "unsigned",
        "short",
        "int",
        "long",
        "float",
        "double",
        "wchar_t",
        "char16_t",
        "char32_t",
    }
    start = 0
    while True:  # leading specifiers and attributes, as `alignas(16) T (name)`
        if values[start : start + 1] and values[start] in qualifiers | {"::"}:
            start += 1
        elif declarator_attributes_end(tokens, start) != start:
            start = declarator_attributes_end(tokens, start)
        else:
            break
    if values[start : start + 2] == ["decltype", "("] and start + 1 in tokens.pairs:
        end = tokens.pairs[start + 1] + 1
    elif values[start : start + 1] and values[start] in builtins:
        end = start
        while values[end : end + 1] and values[end] in builtins | qualifiers:
            end += 1
    else:
        name = next(names_in(values[start:]), None)
        if name is None or name[0]:
            return None
        end = template_end(values, start + name[1])
    while values[end : end + 1] and values[end] in {
        "const",
        "volatile",
        "*",
        "&",
        "&&",
    }:
        end += 1
    opening = declarator_attributes_end(tokens, end)
    closing = tokens.pairs.get(opening)
    if values[opening : opening + 1] != ["("] or closing is None:
        return None
    found = grouped_object(tokens, opening)
    return found[0] if found else None  # the name, with bounds `T ((name)[2])[3]`


def declaration(values, owner, macros=()):
    """Read a declaration prefix, before its semicolon or inline body."""
    square = brace = 0
    excluded_until = -1
    pointer = function_pointer_name(values)
    for opening, value in enumerate(values):
        square += (value == "[") - (value == "]")
        brace += (value == "{") - (value == "}")
        if square or brace or opening <= excluded_until or value != "(" or opening == 0:
            continue
        if in_template_argument(values, opening):
            continue
        if pointer and opening < pointer[0]:
            excluded_until = pointer[1]
            continue
        name_index = opening - 1
        name = values[name_index]
        if name in {
            "decltype",
            "noexcept",
            "alignas",
            "__attribute__",
            "__attribute",
            "__declspec",
        }:
            excluded_until = Tokens(" ".join(values)).pairs.get(opening, opening)
            continue
        for spelling in (
            ("operator", "->"),
            ("operator", "&"),
            ("operator", "[", "]"),
            ("operator", "(", ")"),
        ):
            if tuple(values[max(0, opening - len(spelling)) : opening]) == spelling:
                name_index = opening - len(spelling)
                name = "".join(spelling)
                break
        if (
            not IDENTIFIER.match(name)
            and not name.startswith("operator")
            or name in {"operator", "decltype", "noexcept", "alignas"}
        ):
            continue
        if name in macros:
            excluded_until = Tokens(" ".join(values)).pairs.get(opening, opening)
            continue
        # A grouped pointer declarator does not call its preceding return type.
        head = opening + 1
        head += values[head : head + 1] == ["::"]
        while head < len(values) and IDENTIFIER.match(values[head]):
            head = template_end(values, head + 1)
            if values[head : head + 2] == ["::", "*"]:
                break
            if values[head : head + 1] != ["::"]:
                break
            head += 1
        if values[opening + 1 : opening + 2] in (["*"], ["&"], ["&&"]) or values[
            head : head + 2
        ] == ["::", "*"]:
            continue
        depth = 1
        closing = opening + 1
        while closing < len(values) and depth:
            depth += (values[closing] == "(") - (values[closing] == ")")
            closing += 1
        if depth:
            continue
        prefix = values[:name_index]
        suffix = values[closing:]
        suffix_tokens = Tokens(" ".join(suffix))
        for index, token in enumerate(suffix):
            if token == ":" and suffix_tokens.enclosing[index] is None:
                values = values[: closing + index]
                suffix = values[closing:]
                break
        angle = 0
        assignment = False
        prefix_tokens = Tokens(" ".join(prefix))
        for index, token in enumerate(prefix):
            angle += (token == "<") - (token == ">")
            assignment |= token == "=" and angle == 0
            if token == ":" and angle == 0 and prefix_tokens.enclosing[index] is None:
                return None
        if assignment or "return" in prefix or "->" in prefix or "." in prefix:
            return None
        return {
            "class": owner,
            "name": name,
            "signature": " ".join(values),
            "const": "const" in suffix,
            "virtual": "virtual" in prefix or "override" in suffix,
            "override": "override" in suffix,
            "return_tokens": prefix,
            "name_index": name_index,
        }
    return None


def member_signature(item, resolve_type):
    """Parameter types and member cv/ref qualifiers, independent of specifiers."""
    if "static" in item["return_tokens"]:
        return None
    tokens = Tokens(item["signature"])
    values = tokens.values
    opening = len(item["return_tokens"]) + len(
        TOKEN.findall(item["name"].rsplit("::", 1)[-1])
    )
    closing = tokens.pairs.get(opening)
    if closing is None or values[opening] != "(":
        return None
    parameters, current, depth, default = [], [], 0, False
    for value in values[opening + 1 : closing] + [","]:
        if value == "," and depth == 0:
            parameters.append(current)
            current, default = [], False
            continue
        if value == "=" and depth == 0:
            default = True
        depth += (value in {"<", "(", "["}) - (value in {">", ")", "]"})
        if not default:
            current.append(value)
    normalized = []
    keywords = {
        "const",
        "volatile",
        "void",
        "bool",
        "char",
        "signed",
        "unsigned",
        "short",
        "int",
        "long",
        "float",
        "double",
        "wchar_t",
        "char16_t",
        "char32_t",
    }
    for parameter in parameters:
        if (
            len(parameter) > 1
            and IDENTIFIER.match(parameter[-1])
            and parameter[-1] not in keywords
            and parameter[-2] != "::"
            and any(value not in {"const", "volatile"} for value in parameter[:-1])
        ):
            parameter = parameter[:-1]
        top, angle = [], 0
        for index, value in enumerate(parameter):
            if angle == 0:
                top.append(index)
            angle += (value == "<") - (value == ">")
        # By-value parameters discard top-level cv qualifiers in C++ signatures.
        if not any(parameter[index] in {"&", "&&"} for index in top):
            pointer = max((i for i in top if parameter[i] == "*"), default=-1)
            parameter = [
                value
                for i, value in enumerate(parameter)
                if not (i in top and i > pointer and value in {"const", "volatile"})
            ]
        result, end = [], 0
        for start, stop, name in names_in(parameter):
            result.extend(parameter[end:start])
            resolved = resolve_type(name)
            result.extend([resolved] if resolved else parameter[start:stop])
            end = stop
        result.extend(parameter[end:])
        if result and result != ["void"]:
            normalized.append(tuple(result))
    suffix = []
    for value in values[closing + 1 :]:
        if value not in {"const", "volatile", "&", "&&"}:
            break
        suffix.append(value)
    return (
        tuple(normalized),
        "const" in suffix,
        "volatile" in suffix,
        tuple(value for value in suffix if value in {"&", "&&"}),
    )


def data_member(values, owner, layout_only=False, macros=None):
    """Read one data declarator, including array dimensions and bit-field width.

    Member and namespace declarations pass their `macros`: a sole grouped name
    then declares an object, as `T (name)[2]`, unless T is the owner's own
    constructor name or a macro. Parameters omit them, since there `T (name)` may
    spell an abstract function type."""
    declarator = values
    bit_width = None
    type_tokens = Tokens(" ".join(values))
    type_expressions = {
        position
        for index, value in enumerate(values)
        if value in {"decltype", "alignas"}
        and values[index + 1 : index + 2] == ["("]
        and index + 1 in type_tokens.pairs
        for position in range(index + 1, type_tokens.pairs[index + 1] + 1)
    }
    annotations = {
        position
        for index in range(len(values))
        for position in range(index, declarator_attributes_end(type_tokens, index))
    }
    type_expressions.update(annotations)
    for start, end, name in names_in(values):
        if name == "std::function":
            type_expressions.update(range(end + 1, template_end(values, end)))
    type_expressions.update(  # function types spelled inside template arguments
        position
        for opening, closing in type_tokens.pairs.items()
        if opening < closing
        and values[opening] == "("
        and in_template_argument(values, opening)
        for position in range(opening, closing + 1)
    )
    angle = 0
    for end, token in enumerate(values):
        if end in type_expressions:
            continue
        angle += (token == "<") - (token == ">")
        if (
            token in {"=", "{", ":"}
            and angle == 0
            and type_tokens.enclosing[end] is None
        ):
            declarator = values[:end]
            if token == ":":
                bit_width = values[end + 1 :]
            break
    name = None if macros is None else grouped_declarator_name(declarator)
    if name is not None and declarator[name - 1] == "(":
        grouped = Tokens(" ".join(declarator))
        opening = name
        while declarator[opening - 1] == "(":
            opening -= 1
        _, end, _, parens = grouped_object(grouped, opening)
        spelled = [
            (stop, value)
            for start, stop, value in names_in(declarator[:opening])
            if start not in annotations and not in_template_argument(declarator, start)
        ]
        stop, spelled = spelled[-1] if spelled else (0, "")
        parts = spelled.split("::")
        constructor = template_end(declarator, stop) == opening and (
            parts[-1] == (owner or "").rsplit("::", 1)[-1] or parts[-2:-1] == parts[-1:]
        )
        if not constructor and spelled not in macros and end == len(declarator):
            member = data_member(
                [value for index, value in enumerate(declarator) if index not in parens]
                + values[len(declarator) :],
                owner,
                layout_only,
            )
            return member and {
                **member,
                "name_index": member["name_index"] + name - opening,
                "signature": " ".join(values),
            }
    shift = 0
    tokens = Tokens(" ".join(declarator))
    pointer_shape = function_pointer_declarator(declarator)
    grouped_pointer = function_pointer_name(declarator)
    if grouped_pointer:
        type_expressions.update(
            index for index, value in enumerate(declarator) if value == "("
        )
    end = len(declarator)
    while end and end - 1 in annotations:
        end -= 1
    dimensions = 0
    while end and declarator[end - 1] == "]" and end - 1 in tokens.pairs:
        end = tokens.pairs[end - 1]
        dimensions += 1
    if grouped_pointer:
        dimensions += pointer_shape["array_dimensions"]
    if (
        dimensions
        and not grouped_pointer
        and end > 2
        and declarator[end - 3 : end - 2] == ["("]
        and declarator[end - 1] == ")"
        and IDENTIFIER.match(declarator[end - 2])
    ):
        # A redundant parenthesized name before its array dimensions: `T (b)[2]`.
        declarator = declarator[: end - 3] + declarator[end - 2 :]
        end -= 2
        shift = 1
    unnamed = (
        bit_width is not None
        and end
        and (
            end == 1
            or end - 1 in type_expressions
            or declarator[end - 1]
            in {
                "bool",
                "char",
                "char16_t",
                "char32_t",
                "wchar_t",
                "short",
                "int",
                "long",
                "signed",
                "unsigned",
                "const",
                "volatile",
            }
            or end > 1
            and declarator[end - 2] == "::"
            or not any(
                value not in {"const", "volatile"} for value in declarator[: end - 1]
            )
        )
    )
    if (
        not unnamed
        and not grouped_pointer
        and (len(declarator[:end]) < 2 or not IDENTIFIER.match(declarator[end - 1]))
        or not NOT_DATA.isdisjoint(
            token
            for index, token in enumerate(declarator[:end])
            if index not in type_expressions
        )
        or unnamed
        and (not layout_only or owner is None)
    ):
        return None
    name_index = grouped_pointer[0] if grouped_pointer else end if unnamed else end - 1
    top, angle = [], 0  # the type's tokens outside template arguments
    for index, token in enumerate(declarator[:name_index]):
        if index in type_expressions:
            continue
        if angle == 0:
            top.append(token)
        angle += (token == "<") - (token == ">")
    pointer = max((k for k, t in enumerate(top) if t in {"*", "&", "&&"}), default=-1)
    return {
        "class": owner,
        "name": "" if unnamed else declarator[name_index],
        "name_index": name_index + shift,
        **({"layout_only": True} if unnamed else {}),
        "static": "static" in top,
        "return_tokens": (
            pointer_shape["return_tokens"]
            if grouped_pointer
            else declarator[:name_index]
        ),
        "array_dimensions": dimensions,
        **(
            {
                key: pointer_shape[key]
                for key in ("array_pointer", "array_reference")
                if pointer_shape[key]
            }
            if grouped_pointer
            else {}
        ),
        **({"bit_width_tokens": bit_width} if bit_width is not None else {}),
        "signature": " ".join(values),
        "const": "constexpr" in top or "const" in top[pointer + 1 :],
        "virtual": False,
    }


def declarators(values, owner, macros=()):
    """Split grouped declarators, retaining the shared type and token positions."""
    tokens = Tokens(" ".join(values))
    parts, start, i, angle, initializer = [], 0, 0, 0, False
    while i <= len(values):
        if i == len(values) or values[i] == "," and angle == 0:
            parts.append((values[start:i], start))
            start = i + 1
            initializer = False
        elif values[i] in {"(", "[", "{"} and i in tokens.pairs:
            i = tokens.pairs[i]
        elif values[i] == ":" and angle == 0 and not initializer:
            if declaration(values[start:i], owner, macros):
                return [(values, 0)]
            initializer = True
        else:
            if values[i] == "<":
                closing = template_end(values, i) - 1
                if not initializer or (
                    i
                    and IDENTIFIER.match(values[i - 1])
                    and values[closing] == ">"
                    and "=" not in values[i + 1 : closing]
                ):
                    angle += 1
            elif values[i] == ">" and angle:
                angle -= 1
            elif values[i] == "=" and not angle:
                initializer = True
        i += 1
    first = declaration(parts[0][0], owner, macros) or data_member(parts[0][0], owner)
    grouped_name = grouped_declarator_name(parts[0][0])
    if not first and grouped_name is None:
        # An unnamed leading bit-field still supplies the group's type.
        colon = next(
            (
                i
                for i, value in enumerate(parts[0][0])
                if value == ":" and tokens.enclosing[i] is None
            ),
            None,
        )
        if colon is None or not data_member(
            parts[0][0][:colon] + ["__bit_field__"], owner
        ):
            return [(values, 0)]
        shared = parts[0][0][:colon]
    else:
        first_values = parts[0][0]
        pointer = function_pointer_name(first_values)
        shared_end = (
            function_pointer_declarator(first_values)["opening"]
            if pointer
            else grouped_name if grouped_name is not None else first["name_index"]
        )
        while tokens.enclosing[shared_end] is not None:
            shared_end = tokens.enclosing[shared_end]
        shared = first_values[:shared_end]
    shared_tokens = Tokens(" ".join(shared))
    angle = 0
    for i, token in enumerate(shared):
        if (
            angle == 0
            and shared_tokens.enclosing[i] is None
            and token in {"*", "&", "&&"}
        ):
            shared = shared[:i]
            break
        angle += (token == "<") - (token == ">")
    return [parts[0]] + [
        (shared + part, offset - len(shared)) for part, offset in parts[1:]
    ]


def data_declarations(values, owner, layout_only=False, macros=None):
    return [
        {**member, "name_index": member["name_index"] + offset}
        for part, offset in declarators(values, owner)
        if (member := data_member(part, owner, layout_only, macros))
    ]


def function_declarations(values, owner, macros=()):
    return [
        {**method, "name_index": method["name_index"] + offset}
        for part, offset in declarators(values, owner, macros)
        if (method := declaration(part, owner, macros))
    ]


def qualifier_path(values, end=None):
    """The `A::B::` qualifier that ends a declaration prefix, as ("A", "B")."""
    path = []
    end = len(values) if end is None else end
    end -= values[end - 1 : end] == ["~"]
    while end > 1 and values[end - 1] == "::":
        k = end - 2
        if values[k] == ">":  # the template arguments of `A<T>::`
            depth = 1
            while k > 0 and depth:
                k -= 1
                depth += (values[k] == ">") - (values[k] == "<")
            k -= 1
        if k < 0 or not IDENTIFIER.match(values[k]):
            break
        path.insert(0, values[k])
        end = k
    return tuple(path)


def member_initializer(tokens, segment, index):
    """Whether the `{` at `index` braces `m{...}` after a constructor's `(...) :`."""
    values = tokens.values
    if not (IDENTIFIER.match(values[index - 1]) or values[index - 1] == ">"):
        return False
    i, parameters = segment, False
    while i < index:  # a top-level colon after the parameter list
        if values[i] == "(" and i in tokens.pairs:
            i, parameters = tokens.pairs[i] + 1, True
            continue
        if values[i] == ":" and parameters:
            return True
        i += 1
    return False


def scopes(tokens, annotation_text=None):
    """Collect namespace/class spans and direct member declaration prefixes.

    Members of every access are returned with their `access`; out-of-line member
    definitions get their class's scope for their parameters and bodies.
    """
    values = tokens.values
    classes = []
    functions = []
    aliases = []
    fields = []

    def quoted_literals(start, stop):
        return [
            match.group()
            for match in IGNORED.finditer(annotation_text[start:stop])
            if not match.group().startswith(("//", "/*"))
        ]

    def annotation(start, stop):
        if annotation_text is None:
            return " ".join(values[start:stop])
        raw = annotation_text[
            tokens.offsets[start] : tokens.offsets[stop - 1] + len(values[stop - 1])
        ]
        raw = IGNORED.sub(
            lambda match: (
                " " if match.group().startswith(("//", "/*")) else match.group()
            ),
            raw,
        )
        return " ".join(re.findall(r'"(?:\\.|[^"\\])*"|' + TOKEN.pattern, raw))

    def enumerators(start, stop, owner, header, enum_type=None):
        result = []
        begin = p = start
        while p <= stop:
            if p < stop and values[p] in {"(", "[", "{"}:
                p = tokens.pairs.get(p, p) + 1
                continue
            if p == stop or values[p] == ",":
                if begin < p and IDENTIFIER.match(values[begin]):
                    member = {
                        "class": owner,
                        "name": values[begin],
                        "signature": " ".join(values[begin:p]),
                        "static": True,
                        "const": True,
                        "virtual": False,
                        "enum_declaration": header,
                        **({"enum_type": enum_type} if enum_type else {}),
                    }
                    initializer = begin + 1
                    while (
                        initializer < p
                        and values[initializer] == "["
                        and initializer in tokens.pairs
                    ):
                        initializer = tokens.pairs[initializer] + 1
                    if initializer < p and values[initializer] == "=":
                        member["constant_dependency_tokens"] = values[
                            initializer + 1 : p
                        ]
                        if annotation_text is not None:
                            literals = quoted_literals(
                                tokens.offsets[initializer] + 1, tokens.offsets[p]
                            )
                            if literals:
                                member["initializer_literals"] = literals
                    elif result:
                        member["constant_dependency_tokens"] = [result[-1]["name"]]
                    result.append(member)
                begin = p + 1
            p += 1
        return result

    def walk(
        start,
        end,
        namespace=(),
        owner=None,
        access="public",
        linkage_literals=(),
        union_header=None,
        templates=(),
    ):
        here = tuple(owner.split("::")) if owner else namespace
        i = start
        segment = start
        while i < end:
            tokens.scopes[i] = here
            value = values[i]
            if (
                value in {"public", "protected", "private"}
                and i + 1 < end
                and values[i + 1] == ":"
            ):
                access = value
                i += 2
                segment = i
                continue
            if value == "namespace":
                j = i + 1
                while j < end and (IDENTIFIER.match(values[j]) or values[j] == "::"):
                    j += 1
                if j < end and values[j] == "{" and j in tokens.pairs:
                    names = tuple(v for v in values[i + 1 : j] if v != "::")
                    tokens.bodies[j] = namespace + names
                    walk(
                        j + 1,
                        tokens.pairs[j],
                        namespace + names,
                        linkage_literals=linkage_literals,
                    )
                    i = tokens.pairs[j] + 1
                    segment = i
                    continue
            if (
                value == "extern"
                and values[i + 1 : i + 2] == ["{"]
                and i + 1 in tokens.pairs
            ):
                opening = i + 1
                literals = (
                    quoted_literals(tokens.offsets[i], tokens.offsets[opening])
                    if annotation_text is not None
                    else ()
                )
                walk(
                    opening + 1,
                    tokens.pairs[opening],
                    namespace,
                    owner,
                    access,
                    literals,
                )
                i = tokens.pairs[opening] + 1
                segment = i
                continue
            if value in {"class", "struct", "union", "enum"} and i + 1 < end:
                j = i + 1
                alignments = []
                annotations = []
                scoped_enum = value == "enum" and values[j] in {"class", "struct"}
                if scoped_enum:
                    j += 1
                while j < end:
                    if (
                        values[j] == "alignas"
                        and j + 1 in tokens.pairs
                        and values[j + 1] == "("
                    ):
                        stop = tokens.pairs[j + 1] + 1
                        alignments.append(" ".join(values[j:stop]))
                        j = stop
                        continue
                    if values[j] in {"[", "("} and j in tokens.pairs:
                        stop = tokens.pairs[j] + 1
                        annotations.append(annotation(j, stop))
                        j = stop
                    elif j + 1 < end and (
                        values[j] in {"alignas", "__attribute__", "__declspec"}
                        or (values[j].startswith("DART_") or values[j].isupper())
                        and (
                            values[j + 1] == "("
                            or IDENTIFIER.match(values[j + 1])
                            and values[j + 1] != "final"
                        )
                    ):
                        annotations.append(annotation(j, j + 1))
                        j += 1
                    else:
                        break
                if (
                    value == "enum"
                    and not scoped_enum
                    and values[j : j + 1] in (["{"], [":"])
                ):
                    k = j
                    while k < end and values[k] not in {"{", ";"}:
                        k += 1
                    if k < end and values[k] == "{" and k in tokens.pairs:
                        fields.extend(
                            {**member, "access": access}
                            for member in enumerators(
                                k + 1,
                                tokens.pairs[k],
                                owner or "::".join(namespace),
                                " ".join(values[i:k]),
                            )
                        )
                        i = tokens.pairs[k] + 1
                        segment = i
                        continue
                if (
                    value == "union"
                    and j < end
                    and values[j] == "{"
                    and j in tokens.pairs
                ):
                    header = " ".join(values[i : tokens.pairs[j] + 1])
                    walk(
                        j + 1,
                        tokens.pairs[j],
                        namespace,
                        owner,
                        access,
                        templates=templates,
                        union_header=header,
                    )
                    i = tokens.pairs[j] + 1
                    segment = i
                    continue
                if j < end and IDENTIFIER.match(values[j]):
                    name = values[j]
                    k = template_end(values, j + 1)  # a specialization's arguments
                    final = k < end and values[k] == "final"
                    if final:
                        k += 1
                    if k < end and values[k] in {"{", ":", ";"}:
                        parent_start = k + 1
                        while k < end and values[k] not in {"{", ";"}:
                            k += 1
                        full_name = "::".join(
                            (owner or "::".join(namespace), name)
                        ).strip(":")
                        tokens.alignment_headers[full_name].update(alignments)
                        if annotations:
                            tokens.annotation_headers[full_name].add(
                                " ".join(annotations)
                            )
                        if value == "enum":
                            tokens.enum_headers[full_name].add(" ".join(values[i:k]))
                        if value == "union":
                            tokens.union_headers[full_name].add(" ".join(values[i:k]))
                        class_header = None
                        if values[segment : segment + 2] == ["template", "<"]:
                            stop, angle = segment + 1, 0
                            while stop < i:
                                if (
                                    values[stop] in {"(", "[", "{"}
                                    and stop in tokens.pairs
                                ):
                                    stop = tokens.pairs[stop] + 1
                                    continue
                                angle += (values[stop] == "<") - (values[stop] == ">")
                                stop += 1
                                if angle == 0:
                                    break
                            if angle == 0:
                                class_header = " ".join(
                                    values[segment:stop]
                                    + values[i : template_end(values, j + 1)]
                                )
                                tokens.template_headers[full_name].add(class_header)
                        if k < end and values[k] == "{" and k in tokens.pairs:
                            tokens.bodies[k] = tuple(full_name.split("::"))
                            parents = []
                            angle = 0
                            for p in range(parent_start, k + 1):
                                current = values[p] if p < k else ","
                                angle += (current == "<") - (current == ">")
                                if current == "," and angle == 0:
                                    parents.append(" ".join(values[parent_start:p]))
                                    parent_start = p + 1
                            entry = {
                                "name": full_name,
                                "kind": value,
                                "final": final,
                                "bases": parents,
                                "members": [],
                                "index": i,
                                "body": k,
                                "end": tokens.pairs[k],
                            }
                            classes.append(entry)
                            if value == "enum":
                                members = enumerators(
                                    k + 1,
                                    tokens.pairs[k],
                                    full_name,
                                    " ".join(values[i:k]),
                                    full_name,
                                )
                                fields.extend(members)
                                if not scoped_enum:
                                    fields.extend(
                                        {
                                            **member,
                                            "class": owner or "::".join(namespace),
                                        }
                                        for member in members
                                    )
                            else:
                                before = len(functions)
                                walk(
                                    k + 1,
                                    tokens.pairs[k],
                                    namespace,
                                    full_name,
                                    "private" if value == "class" else "public",
                                    linkage_literals=linkage_literals,
                                    templates=(
                                        (*templates, class_header)
                                        if class_header
                                        else templates
                                    ),
                                    union_header=(
                                        " ".join(values[i:k])
                                        if value == "union"
                                        else None
                                    ),
                                )
                                entry["members"] = [
                                    m
                                    for m in functions[before:]
                                    if m["class"] == full_name
                                ]
                            i = tokens.pairs[k] + 1
                            if value == "union" and values[i : i + 1] != [";"]:
                                stop = statement_end(tokens, i)
                                type_tokens = values[
                                    segment : entry["index"]
                                ] + TOKEN.findall(full_name)
                                members = data_declarations(
                                    type_tokens + values[i:stop],
                                    owner or "::".join(namespace),
                                    layout_only=bool(owner),
                                    macros=tokens.macros,
                                )
                                for position, member in enumerate(members):
                                    if annotation_text is not None:
                                        first = (
                                            i + member["name_index"] - len(type_tokens)
                                        )
                                        last = (
                                            i
                                            + members[position + 1]["name_index"]
                                            - len(type_tokens)
                                            if position + 1 < len(members)
                                            else stop
                                        )
                                        literals = quoted_literals(
                                            tokens.offsets[first] + len(values[first]),
                                            tokens.offsets[last],
                                        )
                                        if literals:
                                            member["initializer_literals"] = literals
                                        if owner is None:
                                            declaration_literals = list(
                                                linkage_literals
                                            ) + quoted_literals(
                                                tokens.offsets[segment],
                                                tokens.offsets[entry["index"]],
                                            )
                                            if declaration_literals:
                                                member["declaration_literals"] = (
                                                    declaration_literals
                                                )
                                    fields.append(
                                        {
                                            **member,
                                            "access": access,
                                            **(
                                                {"enclosing_templates": templates}
                                                if owner
                                                else {}
                                            ),
                                            **(
                                                {"union_declaration": union_header}
                                                if union_header
                                                else {}
                                            ),
                                        }
                                    )
                                i = stop
                            segment = i
                            continue
                        if k < end and values[k] == ";":
                            aliases.append((full_name, [full_name], i))
            initializer = value == "{" and (
                member_initializer(tokens, segment, i)
                or bool(
                    data_declarations(values[segment:i], owner or "::".join(namespace))
                )
            )
            if (value == "(" or initializer) and i in tokens.pairs:
                for p in range(i, tokens.pairs[i] + 1):
                    tokens.scopes[p] = here
                i = tokens.pairs[i] + 1
                continue
            if value in {";", "{"}:
                prefix = values[segment:i]
                methods = function_declarations(prefix, owner, tokens.macros)
                inside, scope = i, here
                prefix_literals = (
                    quoted_literals(
                        tokens.offsets[segment],
                        tokens.offsets[segment + methods[0]["name_index"]],
                    )
                    if annotation_text is not None and methods
                    else []
                )
                for method in methods:
                    method["index"] = segment
                    method["name_index"] += segment
                    method["access"] = access
                    if owner:
                        # Only this definition's own class templates apply.
                        method["enclosing_templates"] = templates
                    if annotation_text is not None:
                        declaration_end = (
                            method["name_index"]
                            + len(TOKEN.findall(method["signature"]))
                            - len(method["return_tokens"])
                        )
                        literals = prefix_literals + quoted_literals(
                            tokens.offsets[method["name_index"]],
                            tokens.offsets[declaration_end],
                        )
                        if literals:
                            method["declaration_literals"] = literals
                    if value == "{" and i in tokens.pairs:
                        method["body"] = i
                    path = qualifier_path(method["return_tokens"])
                    if "friend" in method["return_tokens"]:
                        method["class"] = None
                        method["declaration_scope"] = here
                    if method["class"] is None:
                        if linkage_literals:
                            method["declaration_literals"] = list(
                                linkage_literals
                            ) + method.get("declaration_literals", [])
                        method["name"] = "::".join(namespace + path + (method["name"],))
                        opening = method["name_index"] + 1
                        if (
                            annotation_text is not None
                            and "body" not in method
                            and values[opening : opening + 1] == ["("]
                            and opening in tokens.pairs
                        ):
                            literals = quoted_literals(
                                tokens.offsets[opening] + 1,
                                tokens.offsets[tokens.pairs[opening]],
                            )
                            if literals:
                                method["constant_initializer_literals"] = literals
                        if path and value == "{" and i in tokens.pairs:
                            # An out-of-line definition looks names up in A::B,
                            # which scan_sources resolves to the declared class.
                            inside, scope = method["name_index"] + 1, namespace + path
                            method["definition"] = (
                                namespace,
                                path,
                                inside,
                                tokens.pairs[i],
                            )
                    functions.append(method)
                members = data_declarations(
                    prefix,
                    owner or "::".join(namespace),
                    layout_only=bool(owner),
                    macros=tokens.macros,
                )
                for position, member in enumerate(members):
                    if annotation_text is not None:
                        first = segment + member["name_index"]
                        last = (
                            segment + members[position + 1]["name_index"]
                            if position + 1 < len(members)
                            else i
                        )
                        literals = quoted_literals(
                            tokens.offsets[first] + len(values[first]),
                            tokens.offsets[last],
                        )
                        if literals:
                            member["initializer_literals"] = literals
                        if owner is None:
                            declaration_literals = list(linkage_literals)
                            if "extern" in prefix:
                                declaration_literals += quoted_literals(
                                    tokens.offsets[segment], tokens.offsets[first]
                                )
                            if declaration_literals:
                                member["declaration_literals"] = declaration_literals
                    fields.append(
                        {
                            **member,
                            "access": access,
                            **({"enclosing_templates": templates} if owner else {}),
                            **(
                                {"union_declaration": union_header}
                                if union_header
                                else {}
                            ),
                        }
                    )
                if (
                    prefix
                    and "using" in prefix
                    and "=" in prefix[prefix.index("using") :]
                ):
                    using = prefix.index("using")
                    equals = prefix.index("=", using)  # not a template default's `=`
                    alias_name = "::".join(
                        (owner or "::".join(namespace), prefix[using + 1])
                    ).strip(":")
                    # Attributes on the alias name, like a typedef's, qualify its target.
                    aliases.append(
                        (
                            alias_name,
                            prefix[equals + 1 :] + prefix[using + 2 : equals],
                            segment,
                        )
                    )
                    # Only the enclosing class templates' parameters shadow its target.
                    tokens.alias_templates[alias_name] = templates
                    if prefix[:2] == ["template", "<"]:  # the alias's own parameters
                        header = prefix[:using]
                        tokens.alias_parameters[alias_name] = template_parameter_list(
                            header
                        )
                        tokens.alias_packs[alias_name] = {
                            parameter
                            for parameter, part in zip(
                                tokens.alias_parameters[alias_name],
                                template_arguments(header, 1),
                            )
                            if parameter and part[-2:] == ["...", parameter]
                        }
                        tokens.alias_defaults[alias_name] = [
                            part[
                                next(
                                    (
                                        index + 1
                                        for index, value in enumerate(part)
                                        if value == "="
                                        and not in_template_argument(part, index)
                                    ),
                                    len(part),
                                ) :
                            ]
                            for part in template_arguments(header, 1)
                        ]
                elif prefix and prefix[0] == "typedef" and len(prefix) > 2:
                    for target, _ in declarators(prefix[1:], owner):
                        member = data_member(target, owner) or declaration(
                            target, owner
                        )
                        grouped_name = grouped_declarator_name(target)
                        name_index = (
                            grouped_name
                            if grouped_name is not None
                            else member["name_index"] if member else len(target) - 1
                        )
                        removed = {name_index}
                        grouped = Tokens(" ".join(target))
                        if grouped_name is not None:
                            left = name_index
                            while target[left - 1 : left] == ["("]:
                                left -= 1
                            removed |= grouped_object(grouped, left)[3]
                        alias_name = "::".join(
                            (owner or "::".join(namespace), target[name_index])
                        ).strip(":")
                        aliases.append(
                            (
                                alias_name,
                                [
                                    value
                                    for index, value in enumerate(target)
                                    if index not in removed
                                ],
                                segment,
                            )
                        )
                        tokens.alias_templates[alias_name] = templates
                if value == "{" and i in tokens.pairs:
                    # shortcut: local classes are omitted; add lexical identities when local adapters need inventory coverage.
                    for p in range(inside, tokens.pairs[i] + 1):
                        tokens.scopes[p] = scope
                    i = tokens.pairs[i] + 1
                else:
                    i += 1
                segment = i
                continue
            i += 1

    walk(0, len(values))
    return classes, functions, aliases, fields


@dataclass
class ApiIndex:
    types: set = field(default_factory=set)
    type_templates: dict = field(default_factory=lambda: defaultdict(set))
    type_enums: dict = field(default_factory=lambda: defaultdict(set))
    type_unions: dict = field(default_factory=lambda: defaultdict(set))
    type_alignments: dict = field(default_factory=lambda: defaultdict(set))
    type_annotations: dict = field(default_factory=lambda: defaultdict(set))
    classes: dict = field(default_factory=dict)
    members: dict = field(default_factory=lambda: defaultdict(list))
    constructors: dict = field(default_factory=dict)
    declares_constructor: set = field(default_factory=set)
    data_members: dict = field(default_factory=lambda: defaultdict(list))
    brace_fields: dict = field(default_factory=lambda: defaultdict(list))
    variables: dict = field(default_factory=lambda: defaultdict(list))
    free_functions: dict = field(default_factory=lambda: defaultdict(list))
    aliases: dict = field(default_factory=dict)
    alias_arguments: dict = field(default_factory=dict)
    alias_templates: dict = field(default_factory=dict)
    alias_parameters: dict = field(default_factory=dict)
    alias_defaults: dict = field(default_factory=dict)
    alias_packs: dict = field(default_factory=dict)
    alias_literals: dict = field(default_factory=dict)
    macros: set = field(default_factory=set)
    headers: set = field(default_factory=set)
    dependencies: dict = field(default_factory=dict)
    standard_pointers: set = field(default_factory=set)
    optional_arguments: dict = field(default_factory=dict)
    smart_arguments: dict = field(default_factory=dict)
    wrappers: set = field(default_factory=set)
    raw_pointers: set = field(default_factory=set)

    def spellings(self, name, scope=(), imports=()):
        """Qualified spellings of `name`, from the innermost scope outward."""
        name = re.sub(r"\s+", "", name).lstrip(":")
        return [
            *("::".join(scope[:size] + (name,)) for size in range(len(scope), -1, -1)),
            *(namespace + "::" + name for namespace in imports),
        ]

    def find(self, name, scope=(), imports=(), aliases=None):
        """The type that `name` names in `scope`, and the alias it names."""
        for candidate in self.spellings(name, scope, imports):
            if aliases and candidate in aliases:
                return aliases[candidate], candidate
            if candidate in self.types:
                return candidate, None
        return None, None

    def resolve(self, name, scope=(), imports=(), aliases=None):
        return self.find(name, scope, imports, aliases)[0]

    def owner(self, name):
        seen = set()
        while name in self.aliases and name not in seen:
            seen.add(name)
            name = self.aliases[name]
        if name in self.classes:
            return name
        return None

    def ordinary(self, candidate, seen=()):
        """The declaring spelling of a real indexed ordinary non-type declaration
        that `candidate` names, through bases unless the class declares the name."""
        scope, _, leaf = candidate.rpartition("::")
        methods = [
            *(d for d in self.members.get(leaf, ()) if d["class"] == scope),
            # Full raw class metadata keeps private names, which still hide types.
            *(
                d
                for d in self.classes.get(scope, {}).get("methods", ())
                if d.get("name") == leaf
            ),
        ]
        values = [
            *self.variables.get(candidate, ()),
            *(d for d in self.data_members.get(leaf, ()) if d["class"] == scope),
            *(
                d
                for d in self.classes.get(scope, {}).get("fields", ())
                if d.get("name") == leaf
            ),
        ]
        if (
            any(real_function(item) for item in self.free_functions.get(candidate, ()))
            or any(real_function(item) for item in methods)
            or any(item.get("return_tokens") for item in values)
        ):
            return candidate
        # An own type, including the injected class name, hides base names.
        if (
            candidate in self.types
            or leaf == scope.rpartition("::")[2]
            or scope in seen
        ):
            return None
        for base in self.classes.get(scope, {}).get("bases", ()):
            owner = self.owner(base)
            if owner and (found := self.ordinary(owner + "::" + leaf, (*seen, scope))):
                return found
        return None

    def value_heads(self, values, scope):
        """`values` with each call head that lookup in `scope` finds as an indexed
        function or value before a type qualified as that declaration, so alias
        expansion keeps it a value."""
        result, previous = [], 0
        for start, end, spelling in names_in(values):
            result.extend(values[previous:start])
            previous = end
            if (
                values[end : end + 1] == ["("]
                and values[start - 1 : start] not in (["::"], ["."], ["->"])
                and self.resolve(spelling, scope)
            ):
                for candidate in self.spellings(spelling, scope):
                    if found := self.ordinary(candidate):
                        result.extend(TOKEN.findall(found))
                        break
                    if candidate in self.types:
                        result.extend(values[start:end])
                        break
            else:
                result.extend(values[start:end])
        return result + values[previous:]

    def constructible(self, name):
        """The class that `name` constructs, unless an alias only wraps it."""
        seen = set()
        while name in self.aliases and name not in seen:
            if name in self.wrappers:
                return None
            seen.add(name)
            name = self.aliases[name]
        return name if name in self.constructors else None

    def construction_dependencies(self, name):
        """Class subobjects constructed as part of a value of `name`.

        Bases and owned fields are constructed even when their containing
        constructor is explicitly declared or defaulted.
        """
        pending, seen = [name], set()
        while pending:
            current = pending.pop(0)
            if current in seen:
                continue
            seen.add(current)
            cls = self.classes.get(current, {})
            pending += [base for base in map(self.owner, cls.get("bases", ())) if base]
            owners, bases = [current], list(cls.get("bases", ()))
            while bases:
                owner = self.owner(bases.pop(0))
                if owner and owner not in owners:
                    owners.append(owner)
                    bases.extend(self.classes[owner].get("bases", ()))
            allocator_fields = {}
            for owner in owners:
                for field in self.classes.get(owner, {}).get("fields", ()):
                    allocator_fields.setdefault(field["name"], field)
            allocators = set()
            for name, field in allocator_fields.items():
                prefix = construction_aliases(
                    self.field_template_mask(field, field.get("return_tokens", [])),
                    self,
                    tuple(field["class"].split("::")),
                )
                if (
                    name
                    and not raw_pointer(prefix)
                    and any(
                        spelling == "std::allocator"
                        and not in_template_argument(prefix, start)
                        for start, _, spelling in names_in(prefix)
                    )
                ):
                    allocators.update(
                        {name, field["class"] + "::" + name, "this->" + name}
                    )
            for member in cls.get("fields", ()):
                if member.get("static") or not member.get("return_tokens"):
                    continue
                prefix = construction_aliases(
                    self.field_template_mask(member, member["return_tokens"]),
                    self,
                    tuple(current.split("::")),
                )
                if function_type_signature(prefix):
                    continue
                values = self.value_heads(
                    self.field_template_mask(
                        member, TOKEN.findall(member["signature"])
                    ),
                    tuple(current.split("::")),
                )
                expanded = construction_aliases(
                    values, self, tuple(current.split("::"))
                )
                if function_pointer_declarator(expanded):
                    continue
                if any(
                    name in SIZED_SEQUENCES | {"std::variant"}
                    and not in_template_argument(expanded, start)
                    for start, _, name in names_in(expanded)
                ):
                    values = expanded
                tokens = Tokens(" ".join(values) + " ;")
                for start, end, spelling in names_in(tokens.values):
                    resolved = next(
                        (
                            candidate
                            for owner in owners
                            if (candidate := owner + "::" + spelling) in self.types
                        ),
                        None,
                    ) or self.resolve(spelling, tuple(current.split("::")))
                    dependency = self.constructible(resolved)
                    if dependency and constructs(
                        tokens, start, end, set(), [], allocators
                    ):
                        pending.append(dependency)
        return sorted(seen)

    def constructor_declarations(self, name):
        return [
            declaration
            for owner in self.construction_dependencies(name)
            for declaration in self.constructors.get(owner, ())
        ]

    def layout_owners(self, values, scope=(), references=False, depth=0):
        """Known inline value owners, without computing object layout."""
        if depth > 8:
            return []
        if references:
            values = [
                value
                for index, value in enumerate(values)
                if value not in {"&", "&&"}
                or index == 0
                or in_template_argument(values, index)
            ]
        if not value_argument(values):
            return []
        for start, end, spelling in names_in(values):
            if in_template_argument(values, start):
                continue
            if spelling == "decltype" and values[end : end + 1] == ["("]:
                tokens = Tokens(" ".join(values))
                closing = tokens.pairs.get(end)
                expression = values[end + 1 : closing] if closing is not None else []
                expression_tokens = Tokens(" ".join(expression))
                call = expression_tokens.pairs.get(len(expression) - 1)
                if (
                    call is not None
                    and expression[-1] == ")"
                    and all(
                        IDENTIFIER.match(value) or value == "::"
                        for value in expression[:call]
                    )
                ):
                    return [
                        owner
                        for declaration in self.decltype_declarations(
                            values[start : closing + 1], scope
                        )
                        for owner in self.layout_owners(
                            return_type_tokens(declaration),
                            declaration.get("declaration_scope")
                            or tuple(
                                (
                                    declaration["class"]
                                    or declaration["name"].rpartition("::")[0]
                                ).split("::")
                            ),
                            depth=depth + 1,
                        )
                    ]
                return []
            arguments = layout_arguments(values, end, spelling)
            if arguments is not None:
                return [
                    owner
                    for argument in arguments
                    for owner in self.layout_owners(argument, scope, depth=depth + 1)
                ]
            resolved = self.layout_type(spelling, scope)
            if resolved in self.alias_arguments:
                # A class-local alias of an enclosing template parameter is dependent.
                argument, where, shadowed, _ = self.alias_target(
                    resolved,
                    values,
                    end,
                    lambda actual: self.masked_aliases(actual, scope, set()),
                )
                argument = [
                    (
                        "__template_parameter"
                        if value in shadowed
                        and (not index or argument[index - 1] != "::")
                        else value
                    )
                    for index, value in enumerate(argument)
                ]
                return self.layout_owners(argument, where, references, depth + 1)
            if resolved in self.classes:
                return [resolved]
        return []

    def layout_type(self, spelling, scope):
        return self.resolve(spelling, scope) or next(
            (
                candidate
                for base in sorted(self.ancestors("::".join(scope)))
                if (candidate := base + "::" + spelling) in self.types
            ),
            None,
        )

    def decltype_declarations(self, values, scope):
        """Indexed callees named by a field's balanced decltype expressions."""
        tokens = Tokens(" ".join(values))
        result, seen = [], set()
        for index, value in enumerate(values):
            opening = index + 1
            if (
                value != "decltype"
                or values[opening : opening + 1] != ["("]
                or opening not in tokens.pairs
            ):
                continue
            expression = values[opening + 1 : tokens.pairs[opening]]
            for start, end, spelling in names_in(expression):
                if expression[
                    template_end(expression, end) : template_end(expression, end) + 1
                ] != ["("]:
                    continue
                if (
                    start
                    and expression[start - 1] in {".", "->"}
                    and expression[:start] != ["this", "->"]
                ):
                    continue
                for candidate in self.spellings(spelling, scope):
                    owner, _, member = candidate.rpartition("::")
                    pending, owners = [self.owner(owner)], []
                    while pending:
                        current = pending.pop(0)
                        if current and current not in owners:
                            owners.append(current)
                            pending.extend(
                                self.owner(base)
                                for base in self.classes[current].get("bases", ())
                            )
                    declarations = [
                        item
                        for cls in owners
                        for item in self.classes[cls].get("methods", ())
                        if item["name"] == member
                    ]
                    declarations += self.free_functions.get(candidate, [])
                    if declarations:
                        for item in declarations:
                            key = item["class"], item["signature"]
                            if key not in seen:
                                seen.add(key)
                                result.append(item)
                        break
        return result

    def storage_alignment_spans(self, values, nested=False):
        """Balanced alignment spellings on a physical field declaration.

        ``nested`` also enumerates spans inside groups, such as a callback's
        pointer declarator; callers must filter them to retained storage tokens.
        """
        tokens = Tokens(" ".join(values))
        result = []
        for index, value in enumerate(values):
            if tokens.enclosing[index] is not None and not nested:
                continue
            if index + 1 in tokens.pairs and (
                value == "alignas"
                or value in {"__attribute__", "__attribute", "__declspec"}
                and {"aligned", "__aligned__", "align"}.intersection(
                    values[index + 2 : tokens.pairs[index + 1]]
                )
            ):
                result.append((index, tokens.pairs[index + 1] + 1))
            elif values[index : index + 2] == ["[", "["] and index in tokens.pairs:
                last = tokens.pairs[index] + 1
                if any(
                    values[start : start + 3] == ["gnu", "::", "aligned"]
                    for start in range(index + 2, last - 2)
                ):
                    result.append((index, last))
        return result

    def layout_storage_declarator(self, member, scope):
        """Physical callable-storage fragments, including genuine alias targets."""
        bounds, alignments, bases = [], [], set()
        member_shadowed = self.declaration_template_names(
            member, TOKEN.findall(member["signature"])
        )

        def dependencies(values, where, retained, shadowed):
            tokens = Tokens(" ".join(values))
            for opening, closing in tokens.pairs.items():
                if (
                    opening < closing
                    and values[opening] == "["
                    and values[opening - 1 : opening] != ["["]
                    and values[opening + 1 : opening + 2] != ["["]
                    and {opening, closing}.issubset(retained)
                ):
                    bounds.extend(
                        self.constant_dependencies(
                            self.masked_aliases(
                                values[opening + 1 : closing], where, shadowed
                            ),
                            where,
                        )
                    )
            for first, last in self.storage_alignment_spans(values, nested=True):
                if set(range(first, last)).issubset(retained):
                    alignments.append(
                        {
                            "class": "::".join(scope),
                            "signature": " ".join(values[first:last]),
                        }
                    )
                    alignments.extend(
                        self.constant_dependencies(
                            self.masked_aliases(
                                values[first + 2 : last - 1], where, shadowed
                            ),
                            where,
                        )
                    )

        def project(values, where, seen=(), shadowed=frozenset(), lexical=False):
            tokens = Tokens(" ".join(values))
            retained = {
                index
                for first, last in self.storage_alignment_spans(values)
                for index in range(first, last)
            }
            if pointer := function_pointer_declarator(values):
                opening = pointer["opening"]
                retained.update(range(opening, tokens.pairs[opening] + 1))
                if pointer["array_pointer"] or pointer["array_reference"]:
                    # The referred-to array's extents and element pointer width
                    # are not part of the pointer.
                    retained.difference_update(pointer["element_widths"])
                    for first, last in tokens.pairs.items():
                        if (
                            values[first] == "["
                            and values[first + 1 : first + 2] != ["["]
                            and tokens.enclosing[first] == pointer["inside"]
                        ):
                            retained.difference_update(range(first, last + 1))
                if not lexical:
                    dependencies(values, where, retained, shadowed)
                if pointer["member_pointer"] and not lexical:
                    # MSVC sizes a member pointer by its owner's inheritance model.
                    group = values[opening + 1 : tokens.pairs[opening]]
                    star = next(
                        (
                            index
                            for index in range(len(group) - 1)
                            if group[index : index + 2] == ["::", "*"]
                        ),
                        0,
                    )
                    for start, _, spelling in names_in(group[:star]):
                        if spelling.split("::")[0] in shadowed and (
                            not start or group[start - 1] != "::"
                        ):
                            continue
                        pending = [self.owner(self.resolve(spelling, where))]
                        while pending:
                            current = pending.pop()
                            cls = self.classes.get(current)
                            if cls and current not in bases:
                                bases.add(current)
                                alignments.extend(
                                    {"class": current, "signature": f": {raw}"}
                                    for raw in cls["base_clauses"]
                                )
                                pending.extend(map(self.owner, cls["bases"]))
                return [
                    value for index, value in enumerate(values) if index in retained
                ]
            if function := function_type_signature(values):
                index = function["parameters_end"] + 1
                while index < len(values):
                    if values[index] == "->":
                        break
                    if values[index] == "noexcept":
                        index = tokens.pairs.get(index + 1, index) + 1
                    else:
                        retained.add(index)
                        index += 1
                if not lexical:
                    dependencies(values, where, retained, shadowed)
                return [
                    value for index, value in enumerate(values) if index in retained
                ]
            semantic = [
                (
                    "__template_parameter"
                    if value in shadowed and (not index or values[index - 1] != "::")
                    else value
                )
                for index, value in enumerate(values)
            ]
            expanded = construction_aliases(semantic, self, where)
            callable_storage = bool(
                function_pointer_declarator(expanded)
                or function_type_signature(expanded)
            )
            result = []
            # An outer pointer or reference owns its storage; the referred-to
            # alias's width, extents and alignment are not part of it.
            indirect = any(
                value in {"*", "&", "&&"}
                and tokens.enclosing[index] is None
                and not in_template_argument(values, index)
                for index, value in enumerate(values)
            )
            for start, end, spelling in names_in(values):
                resolved = self.layout_type(spelling, where)
                if spelling.split("::")[0] in shadowed and (
                    not start or values[start - 1] != "::"
                ):
                    continue
                if (
                    not indirect
                    and not in_template_argument(values, start)
                    and resolved in self.alias_arguments
                    and resolved not in seen
                    and len(seen) < 8
                ):
                    if lexical:
                        argument, declaration_scope = self.alias_arguments[resolved]
                        masked = set()
                    else:
                        argument, declaration_scope, masked, _ = self.alias_target(
                            resolved,
                            values,
                            end,
                            lambda actual: self.masked_aliases(actual, where, shadowed),
                        )
                    storage = project(
                        argument, declaration_scope, (*seen, resolved), masked, lexical
                    )
                    if storage and not lexical and "__template_parameter" in storage:
                        # Unknown actuals affect lookup only. Public evidence keeps
                        # the genuine alias fragment beside its used alias-id.
                        argument, declaration_scope = self.alias_arguments[resolved]
                        storage = project(
                            argument, declaration_scope, (*seen, resolved), lexical=True
                        )
                    if storage is not None:
                        callable_storage = True
                        result.extend(storage)
            if not callable_storage:
                return None
            if not lexical:
                dependencies(values, where, set(range(len(values))), shadowed)
            return result + values

        values = TOKEN.findall(member["signature"])
        if function_pointer_declarator(values):
            storage = project(values, scope, shadowed=member_shadowed)
        else:
            storage = project(member["return_tokens"], scope, shadowed=member_shadowed)
            if storage is not None:
                if {"*", "&", "&&"}.isdisjoint(storage):
                    storage = []
                else:
                    tokens = Tokens(" ".join(values))
                    end = next(
                        (
                            index
                            for index in range(member["name_index"] + 1, len(values))
                            if values[index] in {"=", "{"}
                            and tokens.enclosing[index] is None
                        ),
                        len(values),
                    )
                    storage += values[member["name_index"] : end]
                    dependencies(
                        values,
                        scope,
                        set(range(member["name_index"], end)),
                        member_shadowed,
                    )
        if storage is None:
            return None
        return {
            "storage_declarator": " ".join(storage),
            "storage_array_bound_declarations": list(
                {json.dumps(item, sort_keys=True): item for item in bounds}.values()
            ),
            "storage_alignment_declarations": list(
                {json.dumps(item, sort_keys=True): item for item in alignments}.values()
            ),
        }

    def layout_declarations(self, name):
        """Non-static declarations in base/field order, including inline subobjects."""
        result, seen = [], set()

        def visit(owner):
            if owner in seen or owner not in self.classes:
                return
            seen.add(owner)
            cls = self.classes[owner]
            for base in cls.get("bases", ()):
                visit(self.owner(base))
            for member in cls.get("fields", ()):
                if member.get("static") or not member.get("return_tokens"):
                    continue
                semantic = self.field_template_mask(member, member["return_tokens"])
                prefix = construction_aliases(semantic, self, tuple(owner.split("::")))
                function = function_type_signature(prefix)
                if function and {"*", "&", "&&"}.isdisjoint(function["suffix"]):
                    continue
                storage = self.layout_storage_declarator(
                    member, tuple(owner.split("::"))
                )
                if storage is not None and not storage["storage_declarator"]:
                    continue
                if storage is not None:
                    member = {
                        **member,
                        **storage,
                        "return_tokens": [],
                    }
                else:
                    member = {**member, "return_tokens": semantic}
                result.append(member)
                for child in self.layout_owners(
                    member["return_tokens"], tuple(owner.split("::"))
                ):
                    visit(child)

        visit(self.owner(name))
        return result

    def layout_type_declarations(self, values, scope, depth=0, include_wrapped=False):
        """Indexed alias/enum evidence for a field's inline storage type."""
        aliases, enums, constants = [], [], []
        if depth > 8 or not include_wrapped and not value_argument(values):
            return aliases, enums, constants
        for start, end, spelling in names_in(values):
            if in_template_argument(values, start):
                continue
            arguments = layout_arguments(values, end, spelling)
            if arguments is not None:
                if spelling.lstrip(":") == "std::array":
                    for extent in template_arguments(values, end)[1:]:
                        constants.extend(self.constant_dependencies(extent, scope))
                for argument in arguments:
                    child_aliases, child_enums, child_constants = (
                        self.layout_type_declarations(
                            argument, scope, depth + 1, include_wrapped
                        )
                    )
                    aliases.extend(child_aliases)
                    enums.extend(child_enums)
                    constants.extend(child_constants)
                break
            resolved = self.layout_type(spelling, scope)
            if resolved in self.alias_arguments:
                argument, where = self.alias_arguments[resolved]
                if include_wrapped or value_argument(argument):
                    declaration = {
                        "class": resolved,
                        "signature": "using " + resolved + " = " + " ".join(argument),
                    }
                    if self.alias_literals.get(resolved):
                        declaration["declaration_literals"] = self.alias_literals[
                            resolved
                        ]
                    aliases.append(declaration)
                    child_aliases, child_enums, child_constants = (
                        self.layout_type_declarations(
                            argument, where, depth + 1, include_wrapped
                        )
                    )
                    aliases.extend(child_aliases)
                    enums.extend(child_enums)
                    constants.extend(child_constants)
                break
            enums.extend(
                {"class": resolved, "signature": signature}
                for signature in sorted(self.type_enums.get(resolved, ()))
            )
            constants.extend(self.constant_dependencies(TOKEN.findall(spelling), scope))
        return aliases, enums, constants

    def callable_alias_declarations(self, values, scope):
        """Alias declarations of each callable type named anywhere in `values`.

        Unlike a field's inline storage, a used declaration's call signature
        depends on the aliased callable even inside a product or container.
        """
        aliases, enums, constants = [], [], []
        for start, end, spelling in names_in(values):
            resolved = self.layout_type(spelling, scope)
            if resolved not in self.alias_arguments:
                continue
            argument, where = self.alias_arguments[resolved]
            expanded = construction_aliases(argument, self, where)
            if (
                function_pointer_declarator(expanded)
                or function_type_signature(expanded)
                or any(
                    name == "std::function" and not in_template_argument(expanded, at)
                    for at, _, name in names_in(expanded)
                )
            ):
                child = self.layout_type_declarations(
                    values[start:end], scope, include_wrapped=True
                )
                aliases.extend(child[0])
                enums.extend(child[1])
                constants.extend(child[2])
        return aliases, enums, constants

    def construction_initializer_declarations(self, name):
        """Default field initializers and constants of constructed subobjects."""
        result = []
        for owner in self.construction_dependencies(name):
            for member in self.classes.get(owner, {}).get("fields", ()):
                if member.get("static") or not member.get("return_tokens"):
                    continue
                tokens = Tokens(member["signature"])
                opening = array_end(tokens, len(member["return_tokens"]) + 1)
                if tokens.values[opening : opening + 1] in (["="], ["{"]):
                    result.append(public_declaration(member))
                    result.extend(
                        self.constant_dependencies(
                            tokens.values[len(member["return_tokens"]) + 1 :],
                            tuple(owner.split("::")),
                        )
                    )
        return sorted(
            {json.dumps(d, sort_keys=True): d for d in result}.values(),
            key=lambda d: (d["class"], d["signature"]),
        )

    def ancestors(self, name):
        result = set()
        seen = set()
        pending = [name]
        while pending:
            current = pending.pop()
            if not current or current in seen:
                continue
            seen.add(current)
            pending.extend(self.dependencies.get(current, ()))
            if current in self.aliases:
                pending.append(self.aliases[current])
            if current in self.classes:
                result.add(current)
                pending.extend(self.classes[current]["bases"])
        return result

    def constant_declarations(self, name, scope):
        """Indexed constants visible in a declaration's class/namespace scope."""
        spellings = (
            [name.lstrip(":")] if name.startswith("::") else self.spellings(name, scope)
        )
        for candidate in spellings:
            direct = self.variables.get(candidate, ())
            if direct:
                return [d for d in direct if d.get("const")]
            owner, _, member = candidate.rpartition("::")
            pending, seen = [self.owner(owner)], set()
            while pending:
                current = pending.pop(0)
                if not current or current in seen:
                    continue
                seen.add(current)
                cls = self.classes[current]
                found = [d for d in cls.get("fields", ()) if d["name"] == member]
                if found:
                    return [d for d in found if d.get("const")]
                pending.extend(map(self.owner, cls.get("bases", ())))
        return []

    def constant_dependencies(self, values, scope):
        """Retain lexical constant references, their array bounds and initializers."""
        result, pending, seen = [], [(values, scope)], set()
        while pending:
            expression, where = pending.pop(0)
            for start, _, name in names_in(expression):
                if start and expression[start - 1] in {".", "->"}:
                    continue
                if start and expression[start - 1] == "::":
                    name = "::" + name
                for item in self.constant_declarations(name, where):
                    key = (item["class"], item["signature"])
                    if key in seen:
                        continue
                    seen.add(key)
                    result.append(public_declaration(item))
                    if item.get("constant_dependency_tokens"):
                        pending.append(
                            (
                                item["constant_dependency_tokens"],
                                tuple(item["class"].split("::")),
                            )
                        )
                    tokens = TOKEN.findall(item["signature"])
                    initializer = tokens[len(item.get("return_tokens", ())) + 1 :]
                    if initializer and initializer[0] in {"=", "{", "(", "["}:
                        pending.append(
                            (
                                initializer[1:],
                                tuple(item["class"].split("::")),
                            )
                        )
        return sorted(result, key=lambda d: (d["class"], d["signature"]))

    def prvalue_default(self, prefix, expression, scope):
        """Whether a default is a direct call returning the parameter class by value."""
        # shortcut: resolve indexed direct calls only; extend for other default forms.
        names = list(names_in(expression))
        if not value_argument(prefix) or not names or names[0][0]:
            return False
        opening = template_end(expression, names[0][1])
        if (
            expression[opening : opening + 1] != ["("]
            or Tokens(" ".join(expression)).pairs.get(opening) != len(expression) - 1
            or self.resolve(names[0][2], scope)
        ):
            return False
        parameter = {
            self.owner(self.resolve(n, scope))
            for _, _, n in names_in(prefix)
            if n not in {"const", "volatile"}
        }
        # Argument calls do not determine the outer call's return type.
        declarations = self.decltype_declarations(
            ["decltype", "(", *expression[:opening], "(", ")", ")"], scope
        )

        def returned(item):
            where = tuple(
                (item["class"] or item["name"].rpartition("::")[0]).split("::")
            )
            values = construction_aliases(return_type_tokens(item), self, where)
            return (
                value_argument(values)
                and {
                    self.owner(self.resolve(n, where))
                    for _, _, n in names_in(values)
                    if n not in {"const", "volatile"}
                }
                == parameter
            )

        return (
            None not in parameter
            and bool(declarations)
            and all(map(returned, declarations))
        )

    def layout_operand_owners(self, operand, scope):
        """Value owners of a direct call operand, after its dereferences."""
        # shortcut: direct indexed call operands; extend for other default expressions.
        depth = 0
        while operand:
            tokens = Tokens(" ".join(operand))
            if operand[0] == "(" and tokens.pairs.get(0) == len(operand) - 1:
                operand = operand[1:-1]
            elif operand[0] == "*":
                depth, operand = depth + 1, operand[1:]
            elif operand[-1] == "]" and any(
                closing == len(operand) - 1 and opening
                for opening, closing in tokens.pairs.items()
            ):
                depth += 1
                operand = operand[
                    : next(o for o, c in tokens.pairs.items() if c == len(operand) - 1)
                ]
            else:
                break
        base = 2 if operand[:2] == ["this", "->"] else 0
        names = list(names_in(operand[base:]))
        if not names or names[0][0]:
            return []
        opening = base + template_end(operand[base:], names[0][1])
        if (
            operand[opening : opening + 1] != ["("]
            or Tokens(" ".join(operand)).pairs.get(opening) != len(operand) - 1
        ):
            return []
        result = []
        # Argument calls do not determine the outer call's return type.
        for declaration in self.decltype_declarations(
            ["decltype", "(", *operand[:opening], "(", ")", ")"], scope
        ):
            where = declaration.get("declaration_scope") or tuple(
                (declaration["class"] or declaration["name"].rpartition("::")[0]).split(
                    "::"
                )
            )
            returned = self.masked_aliases(
                return_type_tokens(declaration),
                where,
                self.declaration_template_names(
                    declaration, TOKEN.findall(declaration["signature"])
                ),
            )
            for _ in range(depth):
                while returned[-1:] in (["const"], ["volatile"], ["&"], ["&&"]):
                    returned = returned[:-1]
                if returned[-1:] == ["*"]:
                    returned = returned[:-1]
                else:
                    break
            else:
                result.extend(self.layout_owners(returned, where, references=True))
        return result

    def declaration_template_names(self, item, values):
        """Template parameters of a declaration's own and enclosing templates."""
        headers = [values] if values[:2] == ["template", "<"] else []
        # Enclosing class templates contribute parameters absent from the member.
        owner = (item.get("class") or "").split("::")
        if "enclosing_templates" in item:
            headers.extend(map(TOKEN.findall, item["enclosing_templates"]))
        else:
            for depth in range(1, len(owner) + 1):
                headers.extend(
                    TOKEN.findall(declaration)
                    for declaration in self.type_templates.get(
                        "::".join(owner[:depth]), ()
                    )
                )
        return set().union(*map(template_parameter_names, headers))

    def field_template_mask(self, field, values):
        """`values` with the field's own template parameter names masked."""
        shadowed = self.declaration_template_names(
            field, TOKEN.findall(field["signature"])
        )
        return [
            (
                "__template_parameter"
                if value in shadowed and (not index or values[index - 1] != "::")
                else value
            )
            for index, value in enumerate(values)
        ]

    def alias_target(self, name, values, end, normalize):
        """Substitute an alias-id's actuals/defaults, masking unresolved parameters."""
        arguments, where = self.alias_arguments[name]
        shadowed = set().union(
            *(
                template_parameter_names(TOKEN.findall(header))
                for header in self.alias_templates.get(name, ())
            )
        )
        parameters = self.alias_parameters.get(name, ())
        mapping, packs, after = {}, {}, end

        def substitute(tokens):
            result, index = [], 0
            while index < len(tokens):
                value = tokens[index]
                if (
                    packs
                    and value == "<"
                    and (closing := template_end(tokens, index)) > index
                    and tokens[closing - 1] == ">"
                ):
                    parts = []
                    for part in template_arguments(tokens, index):
                        if len(part) == 2 and part[1] == "..." and part[0] in packs:
                            # A direct pack-name argument is a list splice. Compound
                            # patterns remain masked; no template instantiation here.
                            parts.extend(packs[part[0]])
                        else:
                            parts.append(substitute(part))
                    result.append("<")
                    for position, part in enumerate(parts):
                        if position:
                            result.append(",")
                        result.extend(part)
                    result.append(">")
                    index = closing
                    continue
                if value in mapping and (
                    not index or tokens[index - 1] not in {"::", "."}
                ):
                    result.extend(mapping[value])
                else:
                    result.append(value)
                index += 1
            return result

        if parameters and values[end : end + 1] == ["<"]:
            after = template_end(values, end)
            actuals = template_arguments(values, end)
            defaults = self.alias_defaults.get(name, ())
            for index, parameter in enumerate(parameters):
                if not parameter:
                    continue
                if parameter in self.alias_packs.get(name, ()):
                    packs[parameter] = [
                        normalize(actual) for actual in actuals[index:] if actual
                    ]
                    continue
                actual = actuals[index] if index < len(actuals) else []
                default = defaults[index] if index < len(defaults) else []
                if actual:
                    mapping[parameter] = normalize(actual)
                elif default:
                    # Defaults see their declaration scope and earlier actuals.
                    mapping[parameter] = self.masked_aliases(
                        substitute(default),
                        where,
                        shadowed
                        | (set(filter(None, parameters[:index])) - set(mapping)),
                    )
        shadowed |= set(filter(None, parameters)) - set(mapping)
        return substitute(arguments), where, shadowed, after

    def masked_aliases(self, values, scope, shadowed, depth=0):
        """Expand aliases, masking each declaration's own template parameters."""
        if depth > 8:
            return values
        result, previous = [], 0
        for start, end, spelling in names_in(values):
            if start < previous:  # inside an alias-id's substituted arguments
                continue
            result.extend(values[previous:start])
            name = self.resolve(spelling, scope) or spelling
            if spelling.split("::")[0] in shadowed and (
                not start or values[start - 1] != "::"
            ):
                result.append("__template_parameter")
            elif name in self.alias_arguments:
                arguments, where, masked, end = self.alias_target(
                    name,
                    values,
                    end,
                    lambda actual: self.masked_aliases(
                        actual, scope, shadowed, depth + 1
                    ),
                )
                result.extend(self.masked_aliases(arguments, where, masked, depth + 1))
            else:
                result.extend(TOKEN.findall(name))
            previous = end
        return result + values[previous:]

    def declared_expression_type(self, clause, scope, depth=0):
        """An indexed global, static field or call's std::array identity."""
        if depth > 4:
            return None
        while clause[:1] == ["("] and clause[-1:] == [")"]:
            clause = clause[1:-1]
        if clause[:4] == ["std", "::", "move", "("] and clause[-1:] == [")"]:
            clause = clause[4:-1]
        if clause[:1] in (["*"], ["&"]):
            identity, pointers = self.declared_expression_type(
                clause[1:], scope, depth + 1
            ) or (None, 0)
            if not identity:
                return None
            if clause[0] == "&":  # builtin address-of adds one pointer level
                return identity, pointers + 1
            return (identity, pointers - 1) if pointers else None
        call = clause[-1:] == [")"]
        opening = None
        if call:
            pairs = Tokens(" ".join(clause)).pairs
            opening = next(
                (o for o, c in pairs.items() if o < c and c == len(clause) - 1), None
            )
        name = clause[:opening] if call and opening else clause
        if not name or not all(IDENTIFIER.match(v) or v == "::" for v in name):
            return None
        for candidate in self.spellings("".join(name), scope):
            owner, _, member = candidate.rpartition("::")
            item = next(
                iter(
                    (self.free_functions if call else self.variables).get(candidate)
                    or [
                        field
                        for field in self.classes.get(owner, {}).get("fields", ())
                        if field["name"] == member and field.get("static") and not call
                    ]
                ),
                None,
            )
            if item:
                declared, where = outer_declaration_type(
                    return_type_tokens(item), self, tuple(candidate.split("::")[:-1])
                )
                declared = outer_type_tokens(declared)
                if declared[:2] == ["decltype", "("]:
                    # An outer concrete decltype: the operand's known shape, plus
                    # the declarator's own stars, counted once.
                    closing = Tokens(" ".join(declared)).pairs.get(1)
                    inner = (
                        self.declared_expression_type(
                            declared[2:closing], where, depth + 1
                        )
                        if closing
                        else None
                    )
                    rest = declared[closing + 1 :] if closing else []
                    if not inner or not set(rest) <= {
                        "*",
                        "&",
                        "&&",
                        "const",
                        "volatile",
                    }:
                        return None
                    identity = inner[0], inner[1] + rest.count("*")
                else:
                    identity = array_identity(declared, self)
                if identity:
                    return (
                        identity[0],
                        identity[1]
                        + item.get("array_dimensions", 0)
                        + int(item.get("array_pointer", False)),
                    )
                return None
        return None

    def default_argument_declarations(self, item, seen=()):
        """Constants and constructed class dependencies in parameter defaults."""
        key = item.get("class"), item.get("signature")
        if key in seen or len(seen) > 8:
            return []
        seen = (*seen, key)
        if "return_tokens" not in item:
            return []
        tokens = Tokens(item["signature"])
        values = tokens.values
        opening = len(item["return_tokens"]) + len(
            TOKEN.findall(item["name"].rsplit("::", 1)[-1])
        )
        closing = tokens.pairs.get(opening)
        if closing is None or values[opening] != "(":
            return []
        scope = item.get("declaration_scope") or tuple(
            (item["class"] or item["name"].rpartition("::")[0]).split("::")
        )
        result, constants = [], []
        shadowed = self.declaration_template_names(item, values)
        for first, last in construction_arguments(tokens, opening):
            default = next(
                (
                    index
                    for index in range(first, last + 1)
                    if values[index] == "="
                    and tokens.enclosing[index] == opening
                    and not in_template_argument(values[first:index], index - first)
                ),
                None,
            )
            if default is None:
                continue
            expression = values[default + 1 : last + 1]
            constants.extend(self.constant_dependencies(expression, scope))
            parameter = [  # an elaborated type specifier names the same class
                value
                for index, value in enumerate(values[first:default])
                if value not in {"class", "struct", "union"}
                or not IDENTIFIER.match(values[first + index + 1])
            ]
            member = data_member(parameter, None)
            if not member:
                # Grouped object names must not receive function-parameter adjustment.
                grouped = Tokens(" ".join(parameter))
                for start, stop in grouped.pairs.items():
                    if (
                        start >= stop
                        or parameter[start] != "("
                        or grouped.enclosing[start] is not None
                        or in_template_argument(parameter, start)
                    ):
                        continue
                    inner = parameter[start + 1 : stop]
                    while inner[:1] == ["("]:
                        nested = Tokens(" ".join(inner))
                        if nested.pairs.get(0) != len(inner) - 1:
                            break
                        inner = inner[1:-1]
                    flattened = parameter[:start] + inner + parameter[stop + 1 :]
                    candidate = data_member(flattened, None)
                    if (
                        candidate
                        and start <= candidate["name_index"] < start + len(inner)
                        and candidate["name"]
                        not in {
                            "void",
                            "bool",
                            "char",
                            "signed",
                            "unsigned",
                            "short",
                            "int",
                            "long",
                            "float",
                            "double",
                            "wchar_t",
                            "char16_t",
                            "char32_t",
                            "const",
                            "volatile",
                        }
                        and (
                            inner == [candidate["name"]]
                            and self.resolve(candidate["name"], scope) not in self.types
                            or any(value in {"*", "&", "&&", "["} for value in inner)
                        )
                    ):
                        parameter, member = flattened, candidate
                        break
            prefix = member["return_tokens"] if member else parameter
            if not member:
                function = declaration(parameter, None)
                if (
                    function
                    and function["return_tokens"]
                    and function["return_tokens"][-1] != "::"
                    and any(
                        value not in {"const", "volatile"}
                        for value in function["return_tokens"]
                    )
                ):
                    name_index = function["name_index"]
                    prefix = parameter[:name_index] + parameter[name_index + 1 :]
            if member:
                suffix = declarator_attributes_end(
                    Tokens(" ".join(parameter)),
                    member["name_index"]
                    + 1
                    + (
                        parameter[member["name_index"] + 1 : member["name_index"] + 2]
                        == [")"]
                    ),
                )
                if parameter[suffix : suffix + 1] == ["["] and parameter[
                    suffix : suffix + 2
                ] != ["[", "["]:
                    prefix = [*prefix, "*"]
            prefix, expression = (
                [
                    (
                        "__template_parameter"
                        if value in shadowed and (not index or part[index - 1] != "::")
                        else value
                    )
                    for index, value in enumerate(part)
                ]
                for part in (prefix, expression)
            )
            operands = Tokens(" ".join(expression))
            for index, value in enumerate(expression):
                span = (
                    layout_operator_operand(operands, index)
                    if value in {"sizeof", "alignof"}
                    else None
                )
                if span is None:
                    continue
                operand = expression[span[0] : span[1]]
                if operands.values[index + 1] == "(" and not any(
                    token in {"(", "{", ".", "->", "?", "=", "+", "-", "/", "%", "!"}
                    and not in_template_argument(operand, position)
                    for position, token in enumerate(operand)
                ):
                    for owner in self.layout_owners(operand, scope, references=True):
                        result.extend(self.layout_evidence(owner))
                else:
                    for owner in self.layout_operand_owners(operand, scope):
                        result.extend(self.layout_evidence(owner))
            prefix, expression = (
                self.masked_aliases(part, scope, shadowed)
                for part in (prefix, self.value_heads(expression, scope))
            )
            function = function_type_signature(prefix)
            if function and not {"*", "&", "&&"}.intersection(function["suffix"]):
                function_opening = function["opening"]
                prefix = (
                    prefix[:function_opening]
                    + ["(", "*", ")"]
                    + prefix[function_opening:]
                )
            if expression[:1] == ["{"]:
                prefix = [
                    value
                    for index, value in enumerate(prefix)
                    if value not in {"&", "&&"} or in_template_argument(prefix, index)
                ]
            if prefix[:3] == ["std", "::", "array"] and expression[:1] == ["{"]:
                sole = Tokens(" ".join(expression))
                clauses = construction_arguments(sole, 0)
                if len(clauses) == 1 and expression[clauses[0][0]] != "{":
                    first, last = clauses[0]
                    declared = self.declared_expression_type(
                        expression[first : last + 1], scope
                    )
                    target = array_identity(prefix, self)
                    if (
                        declared
                        and target
                        and not declared[1]
                        and declared[0] == target[0]
                    ):  # one whole array of the parameter's own type is a copy
                        expression = (
                            expression[:first]
                            + ["__array_value"]
                            + expression[last + 1 :]
                        )
            initialized = Tokens(
                " ".join(prefix + ["__default_value", "="] + expression + [";"])
            )
            elided = self.prvalue_default(prefix, expression, scope)
            for start, end, spelling in names_in(initialized.values):
                if start < len(prefix) and not value_argument(prefix):
                    continue
                resolved = self.resolve(spelling, scope)
                constructed = self.constructible(resolved)
                if not constructed or not constructs(
                    initialized, start, end, set(), []
                ):
                    continue
                parameter_value = elided and start < len(prefix)
                if not parameter_value:
                    result.extend(
                        self.construction_initializer_declarations(constructed)
                    )
                for owner in self.construction_dependencies(constructed):
                    result.extend(self.layout_evidence(owner))
                    for constructor in (
                        () if parameter_value else self.constructors.get(owner, ())
                    ):
                        result.append(
                            {
                                **public_declaration(constructor),
                                "access": constructor["access"],
                            }
                        )
                        result.extend(
                            self.default_argument_declarations(constructor, seen)
                        )
                        result.extend(
                            self.exception_specification_declarations(constructor)
                        )
        constants.sort(
            key=lambda declaration: (declaration["class"], declaration["signature"])
        )
        return list(
            {
                json.dumps(declaration, sort_keys=True): declaration
                for declaration in [*constants, *result]
            }.values()
        )

    def layout_evidence(self, owner):
        """Alignment, annotation and ordered-field evidence for a value of `owner`."""
        result = [
            *self.alignment_declarations(owner),
            *(
                {"class": owner, "signature": annotation}
                for annotation in sorted(self.type_annotations.get(owner, ()))
            ),
        ]
        for field in self.layout_declarations(owner):
            result.append({**public_declaration(field), "access": field["access"]})
            aliases, enums, field_constants = self.layout_type_declarations(
                self.field_template_mask(field, field["return_tokens"]),
                tuple(field["class"].split("::")),
            )
            result.extend([*aliases, *enums, *field_constants])
            if "storage_array_bound_declarations" in field:
                result.extend(field["storage_array_bound_declarations"])
                result.extend(field["storage_alignment_declarations"])
            else:
                result.extend(
                    self.constant_dependencies(
                        self.field_template_mask(
                            field, TOKEN.findall(field["signature"])
                        ),
                        tuple(field["class"].split("::")),
                    )
                )
        return result

    def alignment_declarations(self, name):
        """Alignment spellings and their owned-type/constant dependencies."""
        result, pending, seen = [], [name], set()
        while pending:
            current = pending.pop(0)
            if not current or current in seen:
                continue
            seen.add(current)
            if current in self.aliases:
                pending.append(self.aliases[current])
            pending.extend(
                self.construction_dependencies(self.owner(current) or current)
            )
            scope = tuple(current.split("::")[:-1])
            alignments = [
                (signature, scope, None)
                for signature in sorted(self.type_alignments.get(current, ()))
            ]
            for member in self.classes.get(current, {}).get("fields", ()):
                if member.get("static"):
                    continue
                storage = self.layout_storage_declarator(
                    member, tuple(current.split("::"))
                )
                if storage and storage["storage_declarator"]:
                    result.extend(storage["storage_alignment_declarations"])
                tokens = Tokens(member["signature"])
                alignments.extend(
                    (
                        " ".join(tokens.values[index:last]),
                        tuple(current.split("::")),
                        member,
                    )
                    for index, last in self.storage_alignment_spans(tokens.values)
                )
            for signature, scope, member in alignments:
                result.append({"class": current, "signature": signature})
                expression = TOKEN.findall(signature)[2:-1]
                if member:  # a field's own template names never reach lookup
                    expression = self.field_template_mask(member, expression)
                result.extend(self.constant_dependencies(expression, scope))
                for _, end, spelling in names_in(expression):
                    resolved = self.resolve(spelling, scope)
                    after = template_end(expression, end)
                    while expression[after : after + 1] in (["const"], ["volatile"]):
                        after += 1
                    if resolved not in self.raw_pointers and expression[
                        after : after + 1
                    ] != ["*"]:
                        pending.append(self.owner(resolved))
        return sorted(
            {json.dumps(d, sort_keys=True): d for d in result}.values(),
            key=lambda d: (d["class"], d["signature"]),
        )

    def exception_specification_declarations(self, item):
        """Constant evidence from balanced noexcept conditions of a declaration."""
        if "return_tokens" not in item:
            return []
        tokens = Tokens(item["signature"])
        opening = len(item["return_tokens"]) + len(
            TOKEN.findall(item["name"].rsplit("::", 1)[-1])
        )
        if opening not in tokens.pairs or tokens.values[opening] != "(":
            return []
        expression = []
        for index, value in enumerate(tokens.values):
            opening = index + 1
            if (
                value == "noexcept"
                and tokens.values[opening : opening + 1] == ["("]
                and opening in tokens.pairs
            ):
                expression.extend(tokens.values[opening + 1 : tokens.pairs[opening]])
        scope = item.get("declaration_scope") or tuple(
            (item["class"] or item["name"].rpartition("::")[0]).split("::")
        )
        return self.constant_dependencies(expression, scope)


def names_in(values):
    i = 0
    while i < len(values):
        if IDENTIFIER.match(values[i]):
            end = i + 1
            while (
                end + 1 < len(values)
                and values[end] == "::"
                and IDENTIFIER.match(values[end + 1])
                and values[i]
                not in {
                    "const",
                    "volatile",
                    "typename",
                    "return",
                    "class",
                    "struct",
                    "union",
                    "static",
                    "virtual",
                    "public",
                    "protected",
                    "private",
                    "using",
                    "namespace",
                    "typedef",
                    "new",
                    "delete",
                }
            ):
                end += 2
            yield i, end, qualified(values[i:end])
            i = end
        else:
            i += 1


def wraps(values, direct):
    """Whether an alias definition is a pointer, reference or non-DART template."""
    named = [v for _, _, v in names_in(values) if v not in {"const", "typename"}]
    return not named or not direct(named[0]) or not {"*", "&", "&&"}.isdisjoint(values)


def raw_pointer(values):
    """Whether the declarator is a pointer, excluding template arguments."""
    depth = 0
    for value in values:
        if value == "*" and depth == 0:
            return True
        depth += (value in {"<", "(", "["}) - (value in {">", ")", "]"})
    return False


def raw_reference(values):
    """Whether a declaration itself is a reference, outside nested types."""
    depth = 0
    for value in values:
        if value in {"&", "&&"} and depth == 0:
            return True
        depth += (value in {"<", "(", "["}) - (value in {">", ")", "]"})
    return False


def expression_alias(api, name, depth=0):
    """An API alias whose bounded expansion contains a decltype expression."""
    if depth > 8 or name not in api.alias_arguments:
        return False
    values, scope = api.alias_arguments[name]
    return "decltype" in values or any(
        expression_alias(api, api.resolve(value, scope), depth + 1)
        for start, _, value in names_in(values)
        if not in_template_argument(values, start)
    )


def element_alias(api, name, depth=0, containers=ELEMENT_CONTAINERS):
    """An API alias for one of the known standard element containers."""
    if depth > 8 or name not in api.alias_arguments:
        return False
    values, scope = api.alias_arguments[name]
    return any(
        value in containers
        or element_alias(api, api.resolve(value, scope), depth + 1, containers)
        for start, _, value in names_in(values)
        if not in_template_argument(values, start)
    )


def base_name(raw):
    """The class named in a base clause entry such as `public virtual A<B>`."""
    raw = re.sub(r"\b(public|protected|private|virtual)\b", "", raw)
    return re.sub(r"\s+", "", raw).split("<")[0]


def expand(name, namespace_aliases):
    """Replace a namespace alias at the head of a qualified name."""
    head, _, tail = name.partition("::")
    if head not in namespace_aliases:
        return name
    return namespace_aliases[head] + ("::" + tail if tail else "")


def layout_operator_operand(tokens, index):
    values = tokens.values
    first = index + 1
    if values[first : first + 1] == ["("] and first in tokens.pairs:
        return first + 1, tokens.pairs[first]
    if values[index] not in {"sizeof", "&"}:
        return None
    end = first
    while values[end : end + 1] in (["*"], ["&"], ["+"], ["-"], ["!"], ["~"]):
        end += 1
    if values[end : end + 1] == ["::"]:
        end += 1
    if end >= len(values):
        return None
    if values[end] == "(" and end in tokens.pairs:
        end = tokens.pairs[end] + 1
    else:
        end += 1
    while end < len(values):
        if values[end] in {"::", ".", "->"} and end + 1 < len(values):
            end += 2
        elif values[end] in {"(", "["} and end in tokens.pairs:
            end = tokens.pairs[end] + 1
        elif values[end] == "<":
            closing = template_end(values, end)
            if values[closing - 1 : closing] != [">"] or values[
                closing : closing + 1
            ] not in (["("], ["::"]):
                break
            end = closing
        else:
            break
    return first, end


def template_end(values, index):
    """Skip the template argument list, if any, that starts at `index`."""
    if index < len(values) and values[index] == "<":
        depth, group = 1, 0
        index += 1
        while index < len(values) and depth:
            group += (values[index] in {"(", "["}) - (values[index] in {")", "]"})
            if not group:
                depth += (values[index] == "<") - (values[index] == ">")
            index += 1
    return index


def variable_after_type(values, end, grouped=False):
    j = template_end(values, end)
    while j < len(values):
        if values[j] in {"const", "volatile", "*", "&", "&&", ">"}:
            j += 1
        elif values[j] in {
            "__attribute__",
            "__attribute",
            "__declspec",
            "alignas",
        } or values[j : j + 2] == ["[", "["]:
            after = declarator_attributes_end(Tokens(" ".join(values)), j)
            if after == j:
                break
            j = after
        else:
            break
    if grouped and values[j : j + 1] == ["("]:
        found = grouped_object(Tokens(" ".join(values)), j)
        if found and values[found[1] : found[1] + 1] in [[";"], ["="], [","], ["{"]]:
            return found[0]  # a parenthesized object/array declarator
    while j + 2 < len(values) and IDENTIFIER.match(values[j]) and values[j + 1] == "::":
        j += 2  # the `Class::` of an out-of-line static member definition
    if (
        j + 1 < len(values)
        and IDENTIFIER.match(values[j])
        and values[j + 1]
        in {
            ";",
            "=",
            ",",
            ")",
            "(",
            "{",
            "[",
            "__attribute__",
            "__attribute",
            "__declspec",
            "alignas",
        }
    ):
        return j
    return None


def declarator_attributes_end(tokens, index):
    """Skip balanced standard and compiler declarator attributes."""
    values = tokens.values
    while index < len(values):
        if values[index] in {"__attribute__", "__attribute", "__declspec", "alignas"}:
            opening = index + 1
            bracket = "("
        elif values[index : index + 2] == ["[", "["]:
            opening = index
            bracket = "["
        else:
            break
        if values[opening : opening + 1] != [bracket] or opening not in tokens.pairs:
            break
        index = tokens.pairs[opening] + 1
    return index


def grouped_object(tokens, opening):
    """A balanced `(name)[2]`-style object declarator at `opening`.

    Returns the name index, the index after the outermost group and its trailing
    bounds, every bound's `[` and the group parentheses; `None` otherwise. Bounds
    and attributes may follow each closing group, as `((name)[2])[3]`."""
    values = tokens.values
    closing = tokens.pairs.get(opening)
    if values[opening : opening + 1] != ["("] or closing is None:
        return None
    if values[opening + 1 : opening + 2] == ["("]:
        inner = grouped_object(tokens, opening + 1)
        if inner is None:
            return None
        name, after, bounds, parens = inner
    elif IDENTIFIER.match(values[opening + 1]):
        name = opening + 1
        bounds, after = array_bounds(tokens, name + 1)
        parens = set()
    else:
        return None
    if after != closing:
        return None
    more, end = array_bounds(tokens, closing + 1)
    return name, end, bounds + more, parens | {opening, closing}


def array_bounds(tokens, index):
    """Balanced array bounds' `[` indices, and the index after their attributes."""
    bounds = []
    while True:
        index = declarator_attributes_end(tokens, index)
        if tokens.values[index : index + 1] != ["["] or index not in tokens.pairs:
            return bounds, index
        bounds.append(index)
        index = tokens.pairs[index] + 1


def array_end(tokens, index):
    """Skip balanced array dimensions and following declarator attributes."""
    return array_bounds(tokens, index)[1]


def literal_extent(tokens, bound):
    """A literal array bound's value; names and expressions stay unknown."""
    return extent_value(tokens.values[bound + 1 : tokens.pairs[bound]])


def extent_value(inner):
    """The value of literal extent tokens, if they are only a literal."""
    while inner[:1] == ["("] and inner[-1:] == [")"]:
        inner = inner[1:-1]
    match = re.fullmatch(
        r"(0[xX][0-9a-fA-F]+|0[bB][01]+|[0-9]+)[uUlL]*", "".join(inner)
    )
    if not match:
        return None
    number = match.group(1)
    try:
        return int(number, 8 if re.fullmatch(r"0[0-9]+", number) else 0)
    except ValueError:
        return None


def enclosing_template(values, start):
    """The `<` of the innermost template argument list that contains `start`."""
    return next(
        (
            index
            for index in range(start - 1, -1, -1)
            if values[index] == "<" and template_end(values, index) > start
        ),
        None,
    )


def array_types(tokens, index, types):
    """Retain each declared array dimension around the element's type markers.

    A grouped name's bounds count inside and after its own `(`, as `T ((a)[2])[3]`.
    """
    groups = 0
    while index > groups and tokens.values[index - groups - 1] == "(":
        groups += 1
    index += 1
    while True:
        bounds, index = array_bounds(tokens, index)
        for _ in bounds:
            types = {"__element__:" + value for value in types} | {RAW_ARRAY}
        if not groups or tokens.values[index : index + 1] != [")"]:
            return types
        groups -= 1
        index += 1


def in_template_argument(values, start):
    angle = group = 0
    for index in range(start - 1, -1, -1):
        if values[index] in {";", "{", "}"}:
            break
        if values[index] in {")", "]"}:
            group += 1
        elif group and values[index] in {"(", "["}:
            group -= 1
        elif not group:
            angle += (values[index] == "<") - (values[index] == ">")
    return angle > 0


def in_place_initializer(tokens, end, exact=False):
    """Whether a value initializer starts with the std::in_place object.

    `exact` also requires that no arguments follow it.
    """
    values = tokens.values
    variable = variable_after_type(values, end)
    opening = (
        array_end(tokens, variable + 1)
        if variable is not None
        else template_end(values, end)
    )
    if opening not in tokens.pairs or values[opening] not in {"(", "{"}:
        return False
    arguments = values[opening + 1 : tokens.pairs[opening]]
    if arguments[:1] == ["::"]:
        arguments = arguments[1:]
    return arguments[:3] == ["std", "::", "in_place"] and (
        len(arguments) == 3 or not exact and arguments[3] == ","
    )


def default_value_initializer(tokens, end, grouped=False, array=None):
    """An absent or empty initializer selects a variant's first alternative.

    An array also defaults its elements that a brace list omits or spells `{}`.
    Without evaluating bounds, only a literal bound can prove every element
    supplied; a rank above one, a named or runtime bound and an inferred `new`
    bound stay conservative.
    """
    values = tokens.values
    variable = variable_after_type(values, end, grouped)
    bounds = []
    opening = variable + 1 if variable is not None else template_end(values, end)
    if variable is not None and values[variable - 1] == "(":
        group = variable - 1
        while values[group - 1 : group] == ["("]:
            group -= 1
        _, opening, bounds, _ = grouped_object(tokens, group)  # past every group
    while values[opening : opening + 1] in ([">"], ["const"], ["volatile"]):
        opening += 1
    more, opening = array_bounds(tokens, opening)
    bounds += more
    if values[opening : opening + 1] == ["="]:
        opening += 1
    closing = tokens.pairs.get(opening)
    if values[opening : opening + 1] in ([";"], [","], [")"]):
        return True
    if (
        values[opening : opening + 1] == ["{"]
        and closing is not None
        and array is not None
        and not bounds
    ):
        # A std::array owns this list: `{a, b}` or `{{a, b}}` supply its elements.
        extent, nested, target = array
        clauses = construction_arguments(tokens, opening)
        if (
            len(clauses) == 1
            and values[clauses[0][0]] == "{"
            and tokens.pairs.get(clauses[0][0]) == clauses[0][1]
        ):
            clauses = construction_arguments(tokens, clauses[0][0])
        elif len(clauses) == 1 and (
            values[clauses[0][0] : clauses[0][1] + 1] == ["__array_value"]
            or getattr(tokens, "array_copy", lambda *_: False)(*clauses[0], target)
        ):
            return False  # one whole array is a copy, not a single element
        if not clauses:
            return extent != 0
        return (
            extent is None
            or nested
            or len(clauses) < extent
            or any(values[first : last + 1] == ["{", "}"] for first, last in clauses)
        )
    if values[opening : opening + 1] == ["{"] and closing is not None and bounds:
        clauses = construction_arguments(tokens, opening)
        extent = literal_extent(tokens, bounds[0])
        if not clauses:  # a literal zero bound has no elements to default
            return extent != 0
        if len(bounds) > 1 or any(
            values[first : last + 1] == ["{", "}"] for first, last in clauses
        ):
            return True
        if extent is None:  # `T values[] = {...}` is fully supplied
            return variable is None or tokens.pairs[bounds[0]] != bounds[0] + 1
        return len(clauses) < extent
    return (
        (
            values[opening : opening + 1] == ["{"]
            or variable is None
            and values[opening : opening + 1] == ["("]
        )
        and closing == opening + 1
        # `T value({})` copy-list-initializes from an empty list.
        or values[opening : opening + 3] == ["(", "{", "}"]
        and closing == opening + 3
    )


def defaulted_variant(tokens, opening, allocators=()):
    """Whether the context default-initializes the variant spelled at `opening`.

    A variant nested in a wrapper is defaulted by that wrapper's initializer:
    a sized sequence's count, an `in_place` without arguments, or the enclosing
    aggregate's own default initialization, not by the outermost declaration's.
    """
    values = tokens.values
    parent = enclosing_template(values, opening - 3)
    if parent is None:
        return default_value_initializer(tokens, opening)
    kind = qualified(values[max(0, parent - 3) : parent])
    if kind in SIZED_SEQUENCES:
        return sequence_count_initializer(tokens, parent, allocators)
    if kind == "std::optional":
        return in_place_initializer(tokens, parent, exact=True)
    if kind == "std::array" and enclosing_template(values, parent - 3) is None:
        element, *extent = template_arguments(values, parent)
        return default_value_initializer(
            tokens,
            parent,
            array=(
                extent_value(extent[0]) if extent else None,
                any(name == "std::array" for _, _, name in names_in(element)),
                values[parent - 3 : template_end(values, parent)],
            ),
        )
    if kind in {"std::tuple", "std::pair", "std::array"}:
        return defaulted_variant(tokens, parent, allocators)
    if values[parent - 1] == "allocate_shared":
        after = template_end(values, parent)
        arguments = construction_arguments(tokens, after)
        if (
            values[after : after + 1] == ["("]
            and len(arguments) == 1
            and allocator_argument(tokens, arguments[0], allocators)
        ):
            return True
    return default_value_initializer(tokens, opening)


def value_argument(argument):
    """Whether a template type argument owns a value, rather than a pointer/reference."""
    if raw_pointer(argument):
        return False
    tokens = Tokens(" ".join(argument))
    for index, value in enumerate(argument):
        if value not in {"*", "&", "&&"} or in_template_argument(argument, index):
            continue
        enclosing = tokens.enclosing[index]
        while enclosing is not None and argument[enclosing] != "[":
            enclosing = tokens.enclosing[enclosing]
        if enclosing is None:
            return False
    return True


def template_arguments(values, end):
    """Split a balanced template argument list without splitting nested groups."""
    closing = template_end(values, end) - 1
    tokens = Tokens(" ".join(values))
    parts, first, index = [], end + 1, end + 1
    while index <= closing:
        if index == closing or values[index] == ",":
            parts.append(values[first:index])
            first = index + 1
        elif values[index] in {"(", "[", "{"} and index in tokens.pairs:
            index = tokens.pairs[index]
        elif values[index] == "<":
            index = template_end(values, index) - 1
        index += 1
    return parts


def layout_arguments(values, end, name):
    """Type arguments stored inline by the supported standard value wrappers."""
    if name.lstrip(":") not in {
        "std::array",
        "std::tuple",
        "std::pair",
        "std::optional",
        "std::variant",
    } or values[end : end + 1] != ["<"]:
        return None
    parts = template_arguments(values, end)
    if name.lstrip(":") == "std::array":
        extent = parts[1] if len(parts) > 1 else []
        while extent[:1] == ["("] and extent[-1:] == [")"]:
            extent = extent[1:-1]
        if re.fullmatch(r"(?:0+|0[xX]0+|0[bB]0+)[uUlL]*", "".join(extent)):
            return []
        return parts[:1]
    return parts[:1] if name.lstrip(":") == "std::optional" else parts


def construction_arguments(tokens, opening):
    """Argument spans outside balanced expressions and template argument lists."""
    values = tokens.values
    closing = tokens.pairs.get(opening)
    if closing is None:
        return []
    result, first, index = [], opening + 1, opening + 1
    while index <= closing:
        if index == closing or values[index] == ",":
            if first < index:
                result.append((first, index - 1))
            first = index + 1
        elif values[index] in {"(", "[", "{"} and index in tokens.pairs:
            index = tokens.pairs[index]
        elif values[index] == "<":
            after = template_end(values, index)
            if after <= closing and values[after - 1] == ">":
                index = after - 1
        index += 1
    return result


def allocator_argument(tokens, argument, allocators=()):
    """Whether a construction argument span is a known allocator object."""
    values = tokens.values
    first, last = argument
    while values[first] == "(" and tokens.pairs.get(first) == last:
        first, last = first + 1, last - 1
    return (
        values[first : first + 3] == ["std", "::", "allocator"]
        or qualified(values[first : last + 1]) in allocators
    )


def explicit_typed_prvalue(tokens, first, last):
    """The `Type{...}` or `Type(...)` opening spanning exactly first..last."""
    values = tokens.values
    while values[first] == "(" and tokens.pairs.get(first) == last:
        first, last = first + 1, last - 1
    if first >= last:
        return None
    return next(
        (
            (first, opening)
            for opening in range(first + 1, last)
            if values[opening] in {"(", "{"} and tokens.pairs.get(opening) == last
        ),
        None,
    )


def without_redundant_global(values):
    """Drop a `::` that starts the type or a template argument (after any cv)."""
    result = []
    for value in values:
        index = len(result)
        while index and result[index - 1] in {"const", "volatile"}:
            index -= 1
        if value == "::" and (not index or result[index - 1] in {"<", ","}):
            continue
        result.append(value)
    return result


def known_sequence_copy_or_element(tokens, end, opening, argument):
    """An explicit typed prvalue that is the sequence itself (a copy or move)
    or, inside braces, its element (an initializer list) is never a count."""
    head = explicit_typed_prvalue(tokens, *argument)
    if head is None:
        return False
    values = tokens.values
    typed = without_redundant_global(values[head[0] : head[1]])
    return typed == without_redundant_global(
        values[end - 3 : template_end(values, end)]
    ) or (
        values[opening] == "{"
        and typed == without_redundant_global(first_template_argument(values, end))
    )


def sequence_count_initializer(tokens, end, allocators=()):
    """A count, optionally with a known allocator, default-constructs elements."""
    values = tokens.values
    if in_template_argument(values, end - 1):
        # Only the sole template argument of make_shared/make_unique is counted.
        parent = enclosing_template(values, end - 3)
        if (
            parent is None
            or values[parent - 1] not in {"make_shared", "make_unique"}
            or parent + 1 != end - 3
            or values[template_end(values, end) : template_end(values, end) + 1]
            != [">"]
        ):
            return False
        opening = template_end(values, parent)
    else:
        variable = variable_after_type(values, end)
        opening = (
            array_end(tokens, variable + 1)
            if variable is not None
            else template_end(values, end)
        )
    if values[opening : opening + 1] == ["="]:
        opening += 1
    closing = tokens.pairs.get(opening)
    if closing is None or values[opening] not in {"(", "{"}:
        return False
    arguments = construction_arguments(tokens, opening)
    if len(arguments) == 1 and known_sequence_copy_or_element(
        tokens, end, opening, arguments[0]
    ):
        return False
    return (
        len(arguments) == 1
        and not allocator_argument(tokens, arguments[0], allocators)
        or len(arguments) == 2
        and allocator_argument(tokens, arguments[1], allocators)
    )


def outer_declaration_type(values, api, scope=(), depth=0):
    """Normalize an outer alias with its declarator and defining expression scope."""
    if not values or depth > 8:  # an enumerator has no type to normalize
        return values, scope
    tokens = Tokens(" ".join(values))
    for start, end, spelling in names_in(values):
        if tokens.enclosing[start] is not None or in_template_argument(values, start):
            continue
        name = api.resolve(spelling, scope)
        if name not in api.alias_arguments:
            continue
        arguments, where, masked, after = api.alias_target(
            name,
            values,
            end,
            lambda actual: construction_aliases(actual, api, scope, depth + 1),
        )
        arguments = [
            (
                "__template_parameter"
                if value in masked and (not index or arguments[index - 1] != "::")
                else value
            )
            for index, value in enumerate(arguments)
        ]
        return outer_declaration_type(
            values[:start] + arguments + values[after:], api, where, depth + 1
        )
    return construction_aliases(values, api, scope), scope


def construction_aliases(values, api, scope=(), depth=0):
    """Expand bounded API type aliases in their declaring context."""
    if depth > 8:
        return values
    result, previous = [], 0
    for start, end, spelling in names_in(values):
        if start < previous:  # inside an alias-id's substituted arguments
            continue
        result.extend(values[previous:start])
        name = api.resolve(spelling, scope) or spelling
        if name in api.alias_arguments:
            # Explicit arguments are normalized here; the target is expanded in
            # its own declaration scope with unsupplied parameters masked.
            arguments, where, masked, end = api.alias_target(
                name,
                values,
                end,
                lambda actual: construction_aliases(actual, api, scope, depth + 1),
            )
            arguments = [
                (
                    "__template_parameter"
                    if value in masked and (not index or arguments[index - 1] != "::")
                    else value
                )
                for index, value in enumerate(arguments)
            ]
            result.extend(construction_aliases(arguments, api, where, depth + 1))
        else:
            result.extend(TOKEN.findall(name))
        previous = end
    return result + values[previous:]


def construction_type_span(values, start, end):
    """The outer type around a name nested in template arguments."""
    while in_template_argument(values, start):
        opening = next(
            (
                index
                for index in range(start - 1, -1, -1)
                if values[index] == "<" and template_end(values, index) > end
            ),
            None,
        )
        if opening is None or opening == 0:
            break
        end = opening
        start = opening - 1 - 2 * len(qualifier_path(values, opening - 1))
    return start, end


def constructs(tokens, start, end, declarations, heads, allocators=(), declarator=None):
    """Whether the type named by values[start:end] is constructed there."""
    values = tokens.values
    lead = start - (start > 0 and values[start - 1] == "::")  # `::dart::...`
    before = values[lead - 1] if lead else None
    after = template_end(values, end)
    for head, body in heads:
        if head < start < body:  # a base's constructors run for the class's
            if not in_template_argument(values[head:start], start - head):
                return before in {
                    ":",
                    ",",
                    "public",
                    "protected",
                    "private",
                    "virtual",
                } and values[after : after + 1] in (["{"], [","])
            break  # an owning array argument can depend on its constructors, too
    if before in {".", "->", "~", "operator"}:
        return False
    element = lead
    while element and values[element - 1] in {
        "const",
        "volatile",
        "class",
        "struct",
        "union",
        "typename",
    }:
        element -= 1
    if (
        element > 1
        and values[element - 1] == "<"
        and values[element - 2] == "static_cast"
    ):
        argument = first_template_argument(values, element - 1)
        closing = template_end(values, element - 1)
        return value_argument(argument) and values[closing : closing + 1] == ["("]
    if (
        element > 1
        and values[element - 1] == "<"
        and values[element - 2]
        in {
            "make_shared",
            "make_unique",
            "allocate_shared",
            "make_optional",
            "make_from_tuple",
        }
    ):
        argument = first_template_argument(values, element - 1)
        if not value_argument(argument):
            return False
        closing = template_end(values, element - 1)
        return values[closing : closing + 1] == ["("]
    if before == "using":  # inherited constructors
        return values[end : end + 2] == ["::", values[end - 1]]
    if in_template_argument(values, start):
        opening = next(
            (
                index
                for index in range(element - 1, -1, -1)
                if values[index] == "<" and template_end(values, index) > start
            ),
            None,
        )
        if opening is not None and values[max(0, opening - 3) : opening] in (
            ["std", "::", "tuple"],
            ["std", "::", "pair"],
        ):
            first, last = opening + 1, template_end(values, opening) - 1
            for index in range(first, last):
                if (
                    values[index] == ","
                    and tokens.enclosing[index] == tokens.enclosing[opening]
                    and not in_template_argument(values[first:index], index - first)
                ):
                    if index > start:
                        last = index
                        break
                    first = index + 1
            return value_argument(values[first:last]) and constructs(
                tokens, opening - 3, opening, declarations, heads, allocators
            )
        if opening is not None and values[max(0, opening - 3) : opening] == [
            "std",
            "::",
            "variant",
        ]:
            argument = first_template_argument(values, opening)
            return (
                start < opening + 1 + len(argument)
                and value_argument(argument)
                and defaulted_variant(tokens, opening, allocators)
                and constructs(
                    tokens, opening - 3, opening, declarations, heads, allocators
                )
            )
        if (
            opening is not None
            and qualified(values[max(0, opening - 3) : opening]) in SIZED_SEQUENCES
        ):
            return (
                value_argument(first_template_argument(values, opening))
                and sequence_count_initializer(tokens, opening, allocators)
                and constructs(
                    tokens, opening - 3, opening, declarations, heads, allocators
                )
            )
        if values[max(0, element - 4) : element] == ["std", "::", "optional", "<"]:
            closing = template_end(values, element - 1)
            return (
                values[after:closing] == [">"]
                and in_place_initializer(tokens, element - 1)
                and constructs(
                    tokens, element - 4, element - 1, declarations, heads, allocators
                )
            )
        if values[max(0, element - 4) : element] == ["std", "::", "array", "<"]:
            closing = template_end(values, element - 1) - 1
            while values[after : after + 1] in (["const"], ["volatile"]):
                after += 1
            extent = values[after + 1 : closing]
            while extent[:1] == ["("] and extent[-1:] == [")"]:
                extent = extent[1:-1]
            if (
                values[after : after + 1] == [","]
                and extent
                and not re.fullmatch(r"(?:0+|0[xX]0+|0[bB]0+)[uUlL]*", "".join(extent))
            ):
                return constructs(
                    tokens, element - 4, element - 1, declarations, heads, allocators
                )
        return False
    variable = (
        declarator["name_index"]
        if declarator is not None
        else variable_after_type(values, end)
    )
    statement = lead  # the specifiers of the declaration that the type starts
    while statement and values[statement - 1] not in {
        ";",
        "{",
        "}",
        ":",
        "(",
        ",",
        "=",
    }:
        statement -= 1
    specifiers = set(values[statement:lead])
    initialized = array_end(tokens, variable + 1) if variable is not None else 0
    defined = variable is not None and values[initialized : initialized + 1] in (
        ["="],
        ["{"],
        ["("],
    )
    if (
        specifiers & {"typedef", "friend"}
        or ("extern" in specifiers and not defined)
        or (  # an in-class declaration, defined out of line
            "static" in specifiers
            and not specifiers & {"inline", "constexpr"}
            and any(tokens.enclosing[start] == body for _, body in heads)
        )
    ):
        return False
    if before == "new" or (
        before == ")"
        and lead - 1 in tokens.pairs
        and tokens.pairs[lead - 1] > 0
        and values[tokens.pairs[lead - 1] - 1] == "new"
    ):
        while values[after : after + 1] in (["const"], ["volatile"]):
            after += 1
        return values[after : after + 1] not in (["*"], ["&"], ["&&"])
    group = tokens.pairs.get(after) if values[after : after + 1] == ["("] else None
    if group is not None and values[group + 1 : group + 2] == ["("]:
        inner = values[after + 1 : group]
        if inner[:1] in (["*"], ["&"], ["&&"]) or ["::", "*"] in [
            inner[index : index + 2] for index in range(len(inner))
        ]:
            return False  # `T (*callback)()` declares a callable, not a `T`
    if values[after : after + 1] in (["("], ["{"]):
        return True
    opening = tokens.enclosing[start]  # parameters are not constructions
    return (
        variable is not None
        and variable not in declarations
        and (
            opening is None
            or values[opening] != "("
            or values[opening - 1] in {"if", "for", "while", "switch", "constexpr"}
        )
        and (
            value_argument(declarator["return_tokens"])
            if declarator is not None
            else {"*", "&", "&&"}.isdisjoint(values[after:variable])
        )
    )


def return_type_tokens(item, trailing=False):
    """The return type before an out-of-line member's qualified name."""
    values = item.get("return_tokens", ())
    if trailing and "auto" in values:
        signature = Tokens(item.get("signature", ""))
        for index, value in enumerate(signature.values):
            if (
                value == "->"
                and signature.values[index - 1 : index] != ["operator"]
                and signature.enclosing[index] is None
                and not in_template_argument(signature.values, index)
            ):
                return signature.values[index + 1 :]
    end = len(values)
    for _ in qualifier_path(values):
        end -= 2
        if values[end] == ">":
            angle = 1
            while end > 0 and angle:
                end -= 1
                angle += (values[end] == ">") - (values[end] == "<")
            end -= 1
    prefix = Tokens(" ".join(values[:end]))
    if not any(
        value == "(" and index not in prefix.pairs
        for index, value in enumerate(prefix.values)
    ):
        return values[:end]
    signature = Tokens(item.get("signature", ""))
    opening = len(values) + len(TOKEN.findall(item.get("name", "").split("::")[-1]))
    closing = signature.pairs.get(opening)
    if closing is not None:
        after = closing + 1
        if signature.values[after : after + 1] == ["noexcept"]:
            after += 1
            if (
                signature.values[after : after + 1] == ["("]
                and after in signature.pairs
            ):
                after = signature.pairs[after] + 1
        returned = [*values[:end], *signature.values[after:]]
        if function_pointer_declarator(returned):
            return returned
    return values[:end]


def return_expressions(tokens, function):
    """Return-expression spans in a function, excluding nested callable bodies."""
    body = function.get("body")
    if body not in tokens.pairs:
        return
    values = tokens.values
    index, stop = body + 1, tokens.pairs[body]
    while index < stop:
        value = values[index]
        if value == "return":
            first = last = index + 1
            while last < stop and values[last] != ";":
                if values[last] in {"(", "[", "{"} and last in tokens.pairs:
                    last = tokens.pairs[last] + 1
                else:
                    last += 1
            if first < last:
                yield first, last - 1
            index = last + 1
            continue
        if value in {"class", "struct", "union", "["}:
            after = tokens.pairs.get(index, index) + 1
            if value != "[" or values[after : after + 1] in (
                ["("],
                ["{"],
                ["mutable"],
                ["noexcept"],
                ["->"],
                ["["],
            ):
                while after < stop and values[after] not in {"{", ";", "="}:
                    if values[after] in {"(", "["} and after in tokens.pairs:
                        after = tokens.pairs[after] + 1
                    else:
                        after += 1
                if values[after : after + 1] == ["{"] and after in tokens.pairs:
                    index = tokens.pairs[after] + 1
                    continue
        if value in {"(", "["} and index in tokens.pairs:
            index = tokens.pairs[index] + 1
        else:
            index += 1


def using_declarations(tokens):
    """(name, target, scope, start, stop, depth) for each using import.

    A declaration is visible at tokens start..stop within `scope` and declares
    the name at `depth`, the length of its namespace or class scope, or past
    `BLOCK` in a block. A namespace directive has no single imported name.
    """
    values = tokens.values
    result = []
    for i in range(len(values) - 1):
        if values[i] != "using" or values[i + 1] == "typename":
            continue
        directive = values[i + 1] == "namespace"
        start = i + 1 + directive
        j = start
        while j < len(values) and (IDENTIFIER.match(values[j]) or values[j] == "::"):
            j += 1
        if values[j : j + 1] != [";"] or (not directive and "::" not in values[i:j]):
            continue
        name = None if directive else values[j - 1]
        target = qualified(values[start:j])
        scope = tokens.scopes.get(i, ())
        opening = tokens.enclosing[i]
        if opening is None or opening in tokens.bodies:
            result.append((name, target, scope, i, len(values), len(scope)))
        elif values[opening] == "{":  # an inner block lies deeper than outer ones
            stop = tokens.pairs.get(opening, len(values))
            result.append((name, target, scope, i, stop, BLOCK + opening))
    return result


def elements(types):
    """Element types of the DART containers among `types`."""
    return {
        t.removeprefix("__element__:") for t in types if t.startswith("__element__:")
    }


def first_template_argument(values, start):
    if start >= len(values) or values[start] != "<":
        return []
    depth = 1
    end = start + 1
    while end < len(values):
        token = values[end]
        if depth == 1 and token in {",", ">"}:
            break
        depth += (token == "<") - (token == ">")
        end += 1
    return values[start + 1 : end]


def container_elements(argument, api, resolve_type, pointer_type=None):
    """DART element markers, including the element's raw-pointer identity."""
    result = set()
    pointer = raw_pointer(argument)
    for _, _, value in names_in(argument):
        resolved = resolve_type(value)
        if api.owner(resolved):
            result.add("__element__:" + resolved)
            pointer |= resolved in api.raw_pointers or bool(
                pointer_type and pointer_type(value)
            )
    if result and pointer:
        result.add("__element__:" + RAW_POINTER)
    return result


def statement_end(tokens, start):
    """The end of a compound, control, or expression statement."""
    values = tokens.values
    if values[start : start + 1] == ["{"] and start in tokens.pairs:
        return tokens.pairs[start]
    opening = start + 1
    if values[opening : opening + 1] == ["constexpr"]:
        opening += 1
    if (
        values[start : start + 1] in (["if"], ["for"], ["while"], ["switch"])
        and values[opening : opening + 1] == ["("]
        and opening in tokens.pairs
    ):
        end = statement_end(tokens, tokens.pairs[opening] + 1)
        if values[start] == "if" and values[end + 1 : end + 2] == ["else"]:
            end = statement_end(tokens, end + 2)
        return end
    index = start
    while index < len(values) and values[index] != ";":
        if values[index] in {"(", "[", "{"} and index in tokens.pairs:
            index = tokens.pairs[index]
        index += 1
    return index


def bind_variable(tokens, index, types, span=None):
    """Explicit declarations shadow same-named fields and other functions."""
    values = tokens.values
    start, end = 0, len(values)
    for opening, closing in tokens.pairs.items():
        if opening >= closing or not opening < index < closing:
            continue
        if values[opening] == "{" and closing - opening < end - start:
            start, end = opening, closing
        elif (
            values[opening] == "("
            and opening
            and (
                IDENTIFIER.match(values[opening - 1])
                or values[opening - 1] == "]"
                and opening - 1 in tokens.pairs
            )
        ):
            control = opening - 1 - (values[opening - 1] == "constexpr")
            if control >= 0 and values[control] in {"if", "while", "for", "switch"}:
                stop = statement_end(tokens, control)
                if stop - opening < end - start:
                    start, end = opening, stop
                continue
            body = closing + 1
            while body < len(values) and values[body] in {
                "const",
                "override",
                "final",
                "noexcept",
                "mutable",
            }:
                body += 1
                if body < len(values) and values[body] == "(" and body in tokens.pairs:
                    body = tokens.pairs[body] + 1
            if body < len(values) and values[body] == "->":
                body += 1
                while body < len(values) and values[body] not in {"{", ";", "="}:
                    if values[body] in {"(", "["} and body in tokens.pairs:
                        body = tokens.pairs[body] + 1
                    else:
                        body += 1
            if body < len(values) and values[body] == "{" and body in tokens.pairs:
                if tokens.pairs[body] - opening < end - start:
                    start, end = opening, tokens.pairs[body]
    if span is not None:
        start, end = span
    tokens.bindings.append((start, end, index, values[index], types))


def variable_types(tokens, index, fields):
    if index and tokens.values[index - 1] in {"->", "."}:
        return set(fields.get(tokens.values[index], ()))
    branches = tokens.branches
    bindings = sorted(
        (
            b
            for b in tokens.bindings
            if b[0] <= index <= b[1]
            and b[2] <= index
            and b[3] == tokens.values[index]
            and compatible(branches[b[2]], branches[index])
        ),
        key=lambda b: (b[1] - b[0], -b[2]),
    )
    types = set()
    for b in bindings:  # innermost first
        types |= b[4]
        # A declaration that only some builds compile hides the others in those
        # builds alone: alternatives and outer declarations stay visible.
        if set(branches[b[2]]) <= set(branches[index]):
            return types
    return types | set(fields.get(tokens.values[index], ()))


def is_field(tokens, index, classes):
    start = tokens.bindings[-1][0]
    return any(start == cls["body"] for cls in classes) and not any(
        opening < index < closing
        and tokens.values[opening] == "("
        and set(tokens.values[opening:index]) != {"("}  # the name's own group
        for opening, closing in tokens.pairs.items()
        if opening < closing
    )


def declaration_statement_end(tokens, start):
    """The `;` ending a statement-level or control-init declaration at `start`."""
    values = tokens.values
    lead = start
    while lead:
        previous = values[lead - 1]
        opening = None
        if previous in {"]", ")"}:  # rare: find the group this closes
            opening = next(
                (o for o, c in tokens.pairs.items() if c == lead - 1 and o < c), None
            )
        if previous in {
            "const",
            "volatile",
            "::",
            "static",
            "thread_local",
            "inline",
            "constexpr",
            "extern",
        }:
            lead -= 1
        elif (  # a balanced `[[...]]`, `__attribute__((...))` or `alignas(...)`
            previous == "]"
            and opening is not None
            and values[opening + 1 : opening + 2] == ["["]
            and tokens.pairs.get(opening + 1) == lead - 2
        ):
            lead = opening
        elif (
            previous == ")"
            and opening
            and values[opening - 1]
            in {"__attribute__", "__attribute", "__declspec", "alignas"}
        ):
            lead = opening - 1
        else:
            break
    enclosing = tokens.enclosing[start]
    control = (  # `for (`, `if (` or `switch (` init-statement
        enclosing is not None
        and values[enclosing] == "("
        and lead == enclosing + 1
        and values[enclosing - 1 - (values[enclosing - 1 : enclosing] == ["constexpr"])]
        in {"for", "if", "switch"}
    )
    if not control and (
        (lead and values[lead - 1] not in {";", "{", "}"})
        or (enclosing is not None and values[enclosing] == "(")
    ):
        return None  # not a statement-level declaration; parameters stay separate
    stop = statement_end(tokens, start)
    if values[stop : stop + 1] != [";"] or (control and stop > tokens.pairs[enclosing]):
        return None  # a range-for has no init-statement `;` inside its parentheses
    return stop


def bound_variable_after_type(tokens, start, end, known_type=True):
    """The variable after a type, including a sole grouped name in a declaration.

    `T(x);` only declares x when T is a type, so a grouped name needs known type
    evidence; a qualified spelling alone may be a function call."""
    variable = variable_after_type(tokens.values, end)
    if variable is None and known_type and declaration_statement_end(tokens, start):
        variable = variable_after_type(tokens.values, end, grouped=True)
    return variable


def type_prefix(values, start, name):
    """The type tokens from `start` to a declared name, without its grouping `(`."""
    while name > start and values[name - 1] == "(":
        name -= 1
    return values[start:name]


def later_declarators(tokens, start):
    """Name index and type tokens of each declarator after a declaration's first."""
    values = tokens.values
    stop = declaration_statement_end(tokens, start)
    if stop is None:
        return []
    result = []
    for part, offset in declarators(values[start:stop], None)[1:]:
        item = data_member(part, None)
        if item:
            result.append((start + offset + item["name_index"], item["return_tokens"]))
        elif (name := grouped_declarator_name(part)) is not None:
            result.append((start + offset + name, type_prefix(part, 0, name)))
    return result


def index_api(header_root):
    api = ApiIndex()
    pending_aliases = []
    macros = {}
    headers = []
    declaration_macros = set()
    for path in source_files(Path(header_root)):
        if path.suffix not in {
            ".h",
            ".hh",
            ".hpp",
            ".hxx",
            ".ipp",
            ".tpp",
        } and not path.name.endswith(".hpp.in"):
            continue
        text = path.read_text(encoding="utf-8")
        api.headers.add(
            "dart/" + path.relative_to(header_root).as_posix().removesuffix(".in")
        )
        clean = preprocess(strip_comments_and_strings(text))[0]
        declaration_macros.update(
            re.findall(r"^\s*#\s*define\s+(\w+)", clean, re.MULTILINE)
        )
        api.macros.update(
            re.findall(r"^\s*#\s*define\s+(DART_\w+)", clean, re.MULTILINE)
        )
        macros.update(header_macros(clean))
        headers.append((strip_directives(clean), text))
    for clean, text in headers:
        # Collect annotations before expansion can erase platform-specific export spellings.
        raw_tokens = Tokens(clean)
        raw_tokens.macros = {
            name
            for name, (parameters, _) in macros.items()
            if parameters is not None and annotation_macro(name, macros)
        }
        _, raw_functions, raw_aliases, raw_fields = scopes(
            raw_tokens, annotation_text=text
        )
        raw_annotations = defaultdict(set)
        raw_literals = defaultdict(list)
        raw_declaration_literals = defaultdict(list)
        raw_function_annotations = defaultdict(list)
        grouped_functions = defaultdict(list)
        for function in raw_functions:
            grouped_functions[function["index"]].append(function)
        for name, _, start in raw_aliases:
            stop = statement_end(raw_tokens, start)
            literals = [
                match.group()
                for match in IGNORED.finditer(
                    text[raw_tokens.offsets[start] : raw_tokens.offsets[stop]]
                )
                if not match.group().startswith(("//", "/*"))
            ]
            if literals:
                name = qualified(expand_macros(TOKEN.findall(name), macros))
                api.alias_literals[name] = literals
        for member in raw_fields:
            owner = qualified(expand_macros(TOKEN.findall(member["class"]), macros))
            name = qualified(expand_macros(TOKEN.findall(member["name"]), macros))
            signature = " ".join(
                expand_macros(TOKEN.findall(member["signature"]), macros)
            )
            raw_literals[owner, name, signature].extend(
                member.get("initializer_literals", ())
            )
            raw_declaration_literals[owner, name, signature].extend(
                member.get("declaration_literals", ())
            )
        for function in raw_functions:
            owner, name = function["class"], function["name"]
            if owner is None:
                owner, _, name = name.rpartition("::")
            owner = qualified(expand_macros(TOKEN.findall(owner), macros))
            name = qualified(expand_macros(TOKEN.findall(name), macros))
            signature = " ".join(
                expand_macros(TOKEN.findall(function["signature"]), macros)
            )
            raw_literals[owner, name, signature].extend(
                function.get("constant_initializer_literals", ())
            )
            raw_declaration_literals[owner, name, signature].extend(
                function.get("declaration_literals", ())
            )
            group = grouped_functions[function["index"]]
            annotations = function_annotations(
                raw_tokens, text, function["index"], group[0]["name_index"], macros
            )
            position = group.index(function)
            if position:
                previous = group[position - 1]
                first = (
                    previous["name_index"]
                    + len(TOKEN.findall(previous["signature"]))
                    - len(previous["return_tokens"])
                    + 1
                )
                annotations.extend(
                    function_annotations(
                        raw_tokens, text, first, function["name_index"], macros
                    )
                )
            opening = function["name_index"] + len(
                TOKEN.findall(function["name"].rsplit("::", 1)[-1])
            )
            closing = raw_tokens.pairs.get(opening)
            stop = (
                function["name_index"]
                + len(TOKEN.findall(function["signature"]))
                - len(function["return_tokens"])
            )
            if closing is not None:
                annotations.extend(
                    function_annotations(raw_tokens, text, closing + 1, stop, macros)
                )
            raw_function_annotations[owner, name, signature].extend(annotations)
        for name, declarations in raw_tokens.annotation_headers.items():
            expanded_name = qualified(expand_macros(TOKEN.findall(name), macros))
            raw_annotations[expanded_name].update(declarations)
            if expanded_name.startswith("dart::"):
                api.type_annotations[expanded_name].update(declarations)
        tokens = Tokens(" ".join(expand_macros(TOKEN.findall(clean), macros)))
        tokens.macros = declaration_macros
        classes, functions, aliases, fields = scopes(tokens)
        for function in functions:
            owner, name = function["class"], function["name"]
            if owner is None:
                owner, _, name = name.rpartition("::")
                literals = raw_literals.get((owner, name, function["signature"]))
                if literals:
                    function["constant_initializer_literals"] = literals
            defaults = raw_declaration_literals.get(
                (owner, name, function["signature"])
            )
            if defaults:
                function["declaration_literals"] = defaults
            annotations = raw_function_annotations.get(
                (owner, name, function["signature"])
            )
            if annotations:
                function["declaration_annotations"] = list(dict.fromkeys(annotations))
        for member in fields:
            literals = raw_literals.get(
                (member["class"], member["name"], member["signature"])
            )
            if literals:
                member["initializer_literals"] = literals
            declaration_literals = raw_declaration_literals.get(
                (member["class"], member["name"], member["signature"])
            )
            if declaration_literals:
                member["declaration_literals"] = declaration_literals
        for name, declarations in tokens.template_headers.items():
            if name.startswith("dart::"):
                api.type_templates[name].update(declarations)
        for name, headers in tokens.alias_templates.items():
            if name.startswith("dart::"):
                api.alias_templates[name] = headers
        for name, parameters in tokens.alias_parameters.items():
            if name.startswith("dart::"):
                api.alias_parameters[name] = parameters
                api.alias_defaults[name] = tokens.alias_defaults.get(name, ())
                api.alias_packs[name] = tokens.alias_packs.get(name, set())
        for name, declarations in tokens.enum_headers.items():
            if name.startswith("dart::"):
                api.type_enums[name].update(declarations)
        for name, declarations in tokens.union_headers.items():
            if name.startswith("dart::"):
                api.type_unions[name].update(declarations)
        for name, declarations in tokens.alignment_headers.items():
            if name.startswith("dart::"):
                api.type_alignments[name].update(declarations)
        for name, declarations in tokens.annotation_headers.items():
            if name.startswith("dart::") and name not in raw_annotations:
                api.type_annotations[name].update(declarations)
        for cls in classes:
            if cls["name"].startswith("dart::"):
                api.types.add(cls["name"])
                # Specializations and alternative definitions share one entry.
                entry = api.classes.setdefault(
                    cls["name"],
                    {
                        "bases_raw": [],
                        "base_clauses": [],
                        "bases": [],
                        "final": False,
                        "fields": [],
                        "methods": [],
                        "pure_virtuals": [],
                    },
                )
                entry["bases_raw"] += cls["bases"]
                entry["methods"] += cls["members"]
                for index in range(cls["body"] + 1, cls["end"]):
                    if (
                        tokens.values[index] != "using"
                        or tokens.enclosing[index] != cls["body"]
                    ):
                        continue
                    target = tokens.values[index + 1 : statement_end(tokens, index)]
                    if target and target[0] == "typename":
                        target = target[1:]
                    if (
                        "=" not in target
                        and "::" in target
                        and IDENTIFIER.match(target[-1])
                    ):
                        entry.setdefault("using", {}).setdefault(target[-1], []).append(
                            qualified(target)
                        )
                entry["final"] |= cls["final"]
                entry["pure_virtuals"] += [
                    method
                    for method in cls["members"]
                    if re.search(r"=\s*0$", method["signature"])
                ]
                if cls["kind"] != "enum":
                    api.constructors.setdefault(cls["name"], [])
        for name, values, _ in aliases:
            if name.startswith("dart::"):
                api.types.add(name)
                pending_aliases.append((name, values))
                if values != [name]:
                    api.alias_arguments[name] = (values, tuple(name.split("::")[:-1]))
                optional = next(
                    (
                        end
                        for start, end, value in names_in(values)
                        if value == "std::optional"
                        and not in_template_argument(values, start)
                    ),
                    None,
                )
                if optional is not None:
                    api.optional_arguments[name] = (
                        first_template_argument(values, optional),
                        tuple(name.split("::")[:-1]),
                    )
                smart = next(
                    (
                        (end, value)
                        for start, end, value in names_in(values)
                        if value in SMART_POINTERS
                        and not in_template_argument(values, start)
                    ),
                    None,
                )
                if smart:
                    end, kind = smart
                    api.smart_arguments[name] = (
                        kind,
                        first_template_argument(values, end),
                        tuple(name.split("::")[:-1]),
                    )
                if any(
                    value in {"std::shared_ptr", "std::unique_ptr", "std::weak_ptr"}
                    for _, _, value in names_in(values)
                ):
                    api.standard_pointers.add(name)
        for function in functions:
            owner = function["class"]
            public = function["access"] != "private"
            if owner and owner.startswith("dart::"):
                if function["name"] != owner.split("::")[-1]:
                    if public or function["virtual"]:
                        api.members[function["name"]].append(function)
                elif "~" not in function["return_tokens"]:
                    api.declares_constructor.add(owner)
                    api.constructors.setdefault(owner, []).append(function)
                # shortcut: destructor requirements are omitted; use compiler lanes until lifetime modeling is needed.
            elif (
                owner is None
                and function["name"].startswith("dart::")
                and function["return_tokens"][-1:] != ["::"]  # not Class::member
            ):
                api.free_functions[function["name"]].append(function)
        for member in fields:
            if member["class"] == "dart" or member["class"].startswith("dart::"):
                if member["class"] in api.classes:
                    api.classes[member["class"]]["fields"].append(member)
                    if member.get("layout_only"):
                        continue
                    if member.get("access") != "private":
                        api.data_members[member["name"]].append(member)
                    if member.get("access") == "public" and not member.get("static"):
                        api.brace_fields[member["class"]].append(member)
                else:
                    api.variables[member["class"] + "::" + member["name"]].append(
                        member
                    )
    for name, values in pending_aliases:
        scope = tuple(name.split("::")[:-1])
        own = set(filter(None, api.alias_parameters.get(name, ())))
        for _, _, value in names_in(values):
            resolved = api.resolve(value, scope)
            if value in own:
                continue  # an alias template's own parameter, not the class
            if resolved and resolved != name:
                # A callable alias names a function type, not its return class.
                if not (
                    function_pointer_declarator(values)
                    or function_type_signature(values)
                ):
                    api.aliases.setdefault(name, resolved)
                api.dependencies.setdefault(name, set()).add(resolved)
        if wraps(values, lambda value: api.resolve(value, scope)):
            api.wrappers.add(name)
        if raw_pointer(values):
            api.raw_pointers.add(name)
    pending = set(api.aliases)
    while pending:
        raw = {name for name in pending if api.aliases[name] in api.raw_pointers}
        standard = {
            name for name in pending if api.aliases[name] in api.standard_pointers
        }
        optional = {
            name: api.optional_arguments[api.aliases[name]]
            for name in pending
            if api.aliases[name] in api.optional_arguments
        }
        smart = {
            name: api.smart_arguments[api.aliases[name]]
            for name in pending
            if api.aliases[name] in api.smart_arguments
        }
        found = raw | standard | set(optional) | set(smart)
        api.raw_pointers.update(raw)
        api.standard_pointers.update(standard)
        api.optional_arguments.update(optional)
        api.smart_arguments.update(smart)
        pending -= found
        if not found:
            break
    for name, cls in api.classes.items():
        scope = tuple(name.split("::")[:-1])
        cls["base_clauses"] = list(cls["bases_raw"])
        for raw in cls.pop("bases_raw"):
            for _, _, value in names_in(TOKEN.findall(raw)):
                resolved = api.resolve(value, scope)
                if resolved and resolved != name:
                    cls["bases"].append(resolved)
    api.free_functions = {  # a same-name type keeps only genuine function evidence
        name: [
            item
            for item in declarations
            if name not in api.types or real_function(item)
        ]
        for name, declarations in api.free_functions.items()
    }
    api.free_functions = {
        name: declarations
        for name, declarations in api.free_functions.items()
        if declarations
    }
    changed = True
    while changed:
        changed = False
        for name, declarations in list(api.free_functions.items()):
            for item in declarations[:]:
                if "body" in item:
                    continue
                tokens = Tokens(item["signature"])
                opening = len(item["return_tokens"]) + 1
                closing = tokens.pairs.get(opening)
                if closing is None:
                    continue
                expression = tokens.values[opening + 1 : closing]
                quoted = item.get("constant_initializer_literals", ())
                scope = tuple(name.split("::")[:-1])
                literals = {"true", "false", "nullptr"}
                references = [
                    spelling
                    for start, _, spelling in names_in(expression)
                    if spelling not in literals
                    and not (start and expression[start - 1].isdigit())
                ]
                if (
                    not expression
                    and not quoted
                    or any(value in {",", "="} for value in expression)
                    or not (
                        references
                        or quoted
                        or any(
                            value.isdigit() or value in literals for value in expression
                        )
                    )
                    or not all(
                        api.constant_declarations(value, scope) for value in references
                    )
                ):
                    continue
                member = data_member(
                    item["return_tokens"]
                    + [name.rsplit("::", 1)[-1], "="]
                    + expression,
                    "::".join(scope),
                )
                if member and member["const"]:
                    member["signature"] = item["signature"]
                    if quoted:
                        member["initializer_literals"] = quoted
                    api.variables[name].append(member)
                    declarations.remove(item)
                    changed = True
            if not declarations:
                del api.free_functions[name]
    return api


def classify_member(name, declarations):
    if declarations and all(item["const"] for item in declarations):
        return "accessor"
    getter = re.match(r"^(get|is|has|num)(?:[A-Z_]|$)", name)
    effect = re.search(
        r"(?:Create|Reset|Clear|Remove|Add|Update|Set|Release|Claim|Erase)", name
    )
    return "accessor" if getter and not effect else "mutation"


def public_declaration(declaration):
    if "storage_declarator" in declaration:
        return {
            "class": declaration["class"],
            "storage_declarator": declaration["storage_declarator"],
        }
    return {
        key: declaration[key]
        for key in (
            "class",
            "signature",
            "const",
            "virtual",
            "enum_type",
            "enum_declaration",
            "initializer_literals",
            "declaration_literals",
            "declaration_annotations",
            "union_declaration",
        )
        if key in declaration
    }


def scan_sources(api, source_root):
    source_root = Path(source_root)
    files = []
    includes = {}
    targets = defaultdict(dict)
    fields = defaultdict(set)
    typed_variables = defaultdict(dict)
    namespace_callables = defaultdict(lambda: defaultdict(dict))
    local_bases = {}
    source_returns = defaultdict(list)
    source_fields = defaultdict(lambda: defaultdict(list))
    source_functions = defaultdict(lambda: defaultdict(list))
    alias_declarations = defaultdict(dict)
    source_macros = set()
    referenced = set()
    tables = {
        section: {}
        for section in (
            "types",
            "headers",
            "members",
            "constructors",
            "data_members",
            "variables",
            "free_functions",
            "macros",
            "overrides",
        )
    }

    def used_declaration(item, layout=False):
        """A used declaration; `layout` marks inline-storage evidence only."""
        result = public_declaration(item)
        if item.get("class") in api.classes and "access" in item:
            result["access"] = item["access"]
        if "storage_declarator" not in item:
            defaults = api.default_argument_declarations(item)
            if defaults:
                result["default_argument_declarations"] = defaults
            exceptions = api.exception_specification_declarations(item)
            if exceptions:
                result["exception_specification_declarations"] = exceptions
        scope = tuple((item["class"] or item["name"].rpartition("::")[0]).split("::"))
        width_tokens = item.get("bit_width_tokens", ())
        if layout:
            width_tokens = api.field_template_mask(item, width_tokens)
        width = api.constant_dependencies(width_tokens, scope)
        if width:
            result["bit_width_declarations"] = width
        tokens = Tokens(item.get("storage_declarator", item["signature"]))
        bounds = [
            value
            for opening, closing in tokens.pairs.items()
            if tokens.values[opening] == "["
            and tokens.values[opening - 1 : opening] != ["["]
            and tokens.values[opening + 1 : opening + 2] != ["["]
            for value in tokens.values[opening + 1 : closing]
        ]
        extent = (
            item["storage_array_bound_declarations"]
            if "storage_array_bound_declarations" in item
            else api.constant_dependencies(
                api.field_template_mask(item, bounds) if layout else bounds, scope
            )
        )
        if extent:
            result["array_bound_declarations"] = extent
        if not item.get("storage_declarator"):
            prefix = item.get("return_tokens", [])
            expanded = construction_aliases(prefix, api, scope)
            if function_pointer_declarator(expanded) or function_type_signature(
                expanded
            ):
                aliases, enums, constants = api.layout_type_declarations(
                    prefix, scope, include_wrapped=True
                )
                if aliases:
                    result["type_alias_declarations"] = aliases
                if enums:
                    result["enum_declarations"] = enums
                if constants:
                    result["constant_declarations"] = constants
            elif not layout:
                aliases, enums, constants = api.callable_alias_declarations(
                    prefix, scope
                )
                for key, found in (
                    ("type_alias_declarations", aliases),
                    ("enum_declarations", enums),
                    ("constant_declarations", constants),
                ):
                    if found:
                        result[key] = list(
                            {json.dumps(d, sort_keys=True): d for d in found}.values()
                        )
        return result

    def add(section, name, path, line, **metadata):
        if section == "free_functions":
            metadata["declarations"] = [
                used_declaration(item) for item in api.free_functions.get(name, ())
            ]
            defaults = [
                dependency
                for item in api.free_functions.get(name, ())
                for dependency in api.default_argument_declarations(item)
            ]
            if defaults:
                metadata["default_argument_declarations"] = sorted(
                    {json.dumps(d, sort_keys=True): d for d in defaults}.values(),
                    key=lambda d: (
                        d["class"],
                        d.get("signature", d.get("storage_declarator", "")),
                    ),
                )
            exceptions = [
                dependency
                for item in api.free_functions.get(name, ())
                for dependency in api.exception_specification_declarations(item)
            ]
            if exceptions:
                metadata["exception_specification_declarations"] = sorted(
                    {json.dumps(d, sort_keys=True): d for d in exceptions}.values(),
                    key=lambda d: (d["class"], d["signature"]),
                )
        row = tables[section].setdefault(
            name, {"name": name, "count": 0, "examples": set(), **metadata}
        )
        row["count"] += 1
        row["examples"].add(f"{path}:{line}")
        return row

    def record_constructor(name, constructed, path, tokens, index, braced=False):
        row = add("constructors", name, path, tokens.line(index), declarations=[])
        row["declarations"].extend(
            {**used_declaration(d), "access": d["access"]}
            for d in api.constructor_declarations(constructed)
        )
        pure_virtuals = [
            used_declaration(method)
            for owner in api.construction_dependencies(constructed)
            for method in api.classes.get(owner, {}).get("pure_virtuals", ())
        ]
        if pure_virtuals:
            row.setdefault("pure_virtual_declarations", []).extend(pure_virtuals)
        initializers = api.construction_initializer_declarations(constructed)
        if initializers:
            row.setdefault("default_member_initializer_declarations", []).extend(
                initializers
            )
        if braced and constructed not in api.declares_constructor:
            members = api.brace_fields.get(constructed, ())
            if members:
                row["brace_member_declarations"] = [
                    {"name": member["name"], **used_declaration(member)}
                    for member in members
                ]

    for path in source_files(source_root):
        relative = path.relative_to(source_root).as_posix()
        text = path.read_text(encoding="utf-8")
        clean, branches = preprocess(strip_comments_and_strings(text))
        includes[relative] = [
            match[1]
            for match in INCLUDE.finditer(text)
            if "include" in clean[match.start() : match.start(1)]
        ]
        for match in INCLUDE.finditer(text):
            if (
                match[1].startswith("dart/")
                and "include" in clean[match.start() : match.start(1)]
            ):
                add(
                    "headers",
                    match[1],
                    relative,
                    text.count("\n", 0, match.start()) + 1,
                    source_present=match[1] in api.headers,
                )
        source_macros.update(
            re.findall(r"^\s*#\s*define\s+(DART_\w+)", clean, re.MULTILINE)
        )
        tokens = Tokens(clean)
        tokens.source_path = relative
        tokens.macros = api.macros | set(
            re.findall(r"^\s*#\s*define\s+(\w+)", clean, re.MULTILINE)
        )
        line = 0
        newlines = [match.start() for match in re.finditer("\n", clean)]
        for offset in tokens.offsets:
            while line < len(newlines) and newlines[line] < offset:
                line += 1
            tokens.branches.append(branches[line])
        classes, functions, source_aliases, declared_fields = scopes(tokens)
        for field in declared_fields:
            if field["name"] and field.get("return_tokens"):
                source_fields[field["class"]][field["name"]].append(
                    {
                        **field,
                        "index": next(
                            index
                            for index, value in enumerate(tokens.values)
                            if value == field["name"]
                            and tokens.scopes.get(index, ())
                            == tuple(filter(None, field["class"].split("::")))
                        ),
                        "source": (relative, tokens, [], {}),
                    }
                )
        imports = re.findall(r"\busing\s+namespace\s+([\w:]+)\s*;", clean)
        namespace_aliases = dict(
            re.findall(r"\bnamespace\s+(\w+)\s*=\s*([\w:]+)\s*;", clean)
        )
        for owner in classes:
            for declarations in source_fields[owner["name"]].values():
                for field in declarations:
                    if field["source"][0] == relative:
                        field["source"] = (relative, tokens, imports, namespace_aliases)
        files.append(
            (
                relative,
                tokens,
                classes,
                functions,
                source_aliases,
                imports,
                namespace_aliases,
            )
        )
    for path in sorted(source_root.rglob("CMakeLists.txt")):
        for definitions in re.findall(
            r"\btarget_compile_definitions\s*\(([^)]*)\)",
            path.read_text(encoding="utf-8"),
            re.DOTALL,
        ):
            source_macros.update(re.findall(r"\bDART_\w+", definitions))

    # A file sees the declarations of the scanned headers it includes, transitively.
    suffixes = defaultdict(list)
    for relative in includes:
        parts = relative.split("/")
        for start in range(len(parts)):
            suffixes["/".join(parts[start:])].append(relative)
    closure = {}
    for relative in includes:
        seen, pending = set(), [relative]
        while pending:
            current = pending.pop()
            for name in includes[current]:
                local = posixpath.normpath(
                    posixpath.join(posixpath.dirname(current), name)
                )
                for header in [local] if local in includes else suffixes[name]:
                    if header not in seen:
                        seen.add(header)
                        pending.append(header)
        closure[relative] = sorted(seen - {relative}) + [relative]
    own = {
        path: (list(imports), dict(namespace_aliases))
        for path, tokens, _, _, _, imports, namespace_aliases in files
    }
    for path, tokens, _, _, _, imports, namespace_aliases in files:
        imports.clear()
        for header in reversed(closure[path]):  # the file's own first
            spaces, renamed = own[header]
            imports += [space for space in spaces if space not in imports]
            for key, value in renamed.items():
                namespace_aliases.setdefault(key, value)
        imports[:] = [expand(space.lstrip(":"), namespace_aliases) for space in imports]
        if "dart" in imports:
            imports += ["dart::" + space for space in imports if space != "dart"]
    # An out-of-line definition `A::B::f` looks names up in the class A::B.
    known = {"::".join(s) for _, tokens, *_ in files for s in tokens.bodies.values()}
    for _, tokens, _, functions, _, imports, namespace_aliases in files:
        for function in functions:
            if "definition" in function:
                outer, qualifier, first, last = function["definition"]
                spelled = expand("::".join(qualifier), namespace_aliases)
                owner = next(
                    (c for c in api.spellings(spelled, outer, imports) if c in known),
                    "::".join(outer + qualifier),
                )
                for index in range(first, last + 1):
                    tokens.scopes[index] = tuple(owner.split("::"))
                function["name"] = owner + "::" + function["name"].rpartition("::")[2]
        tokens.using = using_declarations(tokens)
    declared_using = {path: list(tokens.using) for path, tokens, *_ in files}
    for path, tokens, *_ in files:  # and an included header's namespace-scope ones
        tokens.using += [
            (*entry[:3], -1, len(tokens.values), entry[5])
            for header in closure[path]
            if header != path
            for entry in declared_using[header]
            if entry[5] < BLOCK
        ]
    declared = defaultdict(lambda: defaultdict(set))
    for path, tokens, _, functions, aliases, imports, namespace_aliases in files:
        context = (path, tokens, imports, namespace_aliases)
        for name, values, index in aliases:
            alias_declarations[path][name] = (values, index, context)
        for function in functions:
            function["source"] = context
            scope = function["class"] or function["name"].rpartition("::")[0]
            source_returns[(scope, function["name"].split("::")[-1])].append(function)
            if not function["class"]:
                source_functions[path][function["name"]].append(function)
            declared[path][function["name"].split("::")[-1]].add(
                tuple(scope.split("::")) if scope else ()
            )

    # Base classes declared in the scanned sources, for inherited names.
    source_classes = {cls["name"] for _, _, classes, *_ in files for cls in classes}

    def source_class(name, scope, imports, namespace_aliases, path, depth=0):
        """The scanned class that `name` names in `scope`, through aliases."""
        if path not in closure:
            return None
        for candidate in api.spellings(expand(name, namespace_aliases), scope, imports):
            for header in reversed(closure[path]):
                declaration = alias_declarations[header].get(candidate)
                if declaration:
                    values, index, (_, tokens, spaces, renamed) = declaration
                    target = next(
                        (
                            entry
                            for entry in names_in(values)
                            if entry[2]
                            not in {
                                "const",
                                "volatile",
                                "typename",
                                "class",
                                "struct",
                                "enum",
                            }
                        ),
                        None,
                    )
                    if target and depth < 8:
                        return source_class(
                            target[2],
                            tokens.scopes.get(index, ()),
                            spaces,
                            renamed,
                            header,
                            depth + 1,
                        )
                    return None
            if candidate in source_classes:
                return candidate
        return None

    def source_type(name, tokens, index, imports, namespace_aliases):
        """Whether `name` names a scanned class or alias visible there."""
        return any(
            candidate in source_classes
            or any(
                candidate in alias_declarations[header]
                for header in closure[tokens.source_path]
            )
            for candidate in api.spellings(
                expand(name, namespace_aliases), tokens.scopes.get(index, ()), imports
            )
        )

    def tag_named(tokens, index):
        """Whether a `struct`/`class`/`union`/`enum` tag leads the name at index."""
        values = tokens.values
        tags = (["struct"], ["class"], ["union"], ["enum"])
        start = index
        while values[start - 1 : start] == ["::"]:
            start -= 1
            if IDENTIFIER.match(values[start - 1] if start else "") and (
                values[start - 1 : start] not in tags
            ):
                start -= 1
        return values[start - 1 : start] in tags

    def ordinary_declaration(candidate, closed):
        """Whether a real ordinary non-type declaration of this spelling is visible."""
        if api.ordinary(candidate):
            return True
        scope, _, leaf = candidate.rpartition("::")
        return any(
            item["source"][0] in closed and real_function(item)
            for item in source_returns.get((scope, leaf), ())
        ) or any(
            item["source"][0] in closed and item["return_tokens"][-1:] != ["::"]
            for item in source_fields.get(scope, {}).get(leaf, ())
            if item.get("return_tokens")
        )

    def function_hides(name, tokens, index, imports, namespace_aliases):
        """Whether an ordinary function or variable of this spelling hides its class.

        A leading tag keyword still names the type."""
        if tag_named(tokens, index):
            return False
        closed = closure[tokens.source_path]
        for candidate in api.spellings(
            expand(name, namespace_aliases), tokens.scopes.get(index, ()), imports
        ):
            if ordinary_declaration(candidate, closed) or any(
                real_function(item)
                for header in closed
                for item in source_functions[header].get(candidate, ())
            ):
                return True
            if (
                candidate in api.types
                or candidate in source_classes
                or any(  # a nearer namespace- or class-scope alias declared before
                    candidate in alias_declarations[header]
                    and (
                        header != tokens.source_path
                        or alias_declarations[header][candidate][1] < index
                    )
                    for header in closed
                )
            ):
                return False
            scope, _, leaf = candidate.rpartition("::")
            if scope in source_classes and inherited_ordinary(scope, leaf, closed):
                return True
        return False

    def inherited_ordinary(owner, leaf, closed, seen=()):
        """Whether a base of source class `owner` declares `leaf` as an ordinary
        name before a base, or `owner` itself, declares it as a type."""
        if owner in seen or leaf == owner.rpartition("::")[2]:
            return False
        for parent in parents.get(owner, ()):
            candidate = parent + "::" + leaf
            if ordinary_declaration(candidate, closed):
                return True
            if not (
                candidate in source_classes
                or any(candidate in alias_declarations[header] for header in closed)
            ) and inherited_ordinary(parent, leaf, closed, (*seen, owner)):
                return True
        return any(
            api.ordinary(base + "::" + leaf) for base in api_parents.get(owner, ())
        )

    parents, api_parents = defaultdict(list), defaultdict(list)
    for _, tokens, classes, _, _, imports, namespace_aliases in files:
        for cls in classes:
            for raw in cls["bases"]:
                scope = tokens.scopes.get(cls["index"], ())
                parent = source_class(
                    base_name(raw),
                    scope,
                    imports,
                    namespace_aliases,
                    tokens.source_path,
                )
                if parent and parent != cls["name"]:
                    parents[cls["name"]].append(parent)
    ancestry = {}
    for name in parents:
        ancestry[name], pending = [], list(parents[name])
        while pending:
            parent = pending.pop(0)
            if parent not in ancestry[name] and parent != name:
                ancestry[name].append(parent)
                pending += parents.get(parent, ())

    def publish(tokens, name, target, wrapper, pointer):
        tokens.aliases[name] = target
        (tokens.wrapped.add if wrapper else tokens.wrapped.discard)(name)
        (tokens.raw_pointers.add if pointer else tokens.raw_pointers.discard)(name)

    def visible(relative, tokens):
        tokens.aliases, tokens.wrapped = {}, set()
        tokens.raw_pointers = set()
        for owner in closure[relative]:
            for name, (target, wrapper, pointer) in targets[owner].items():
                publish(tokens, name, target, wrapper, pointer)

    def lookup(name, tokens, index, imports, namespace_aliases):
        """The DART type that `name` names there, and the source alias it uses.

        Lookup follows C++ name lookup lexically: enclosing scopes from the
        innermost, the bases of enclosing classes, then `Outer::Nested` names
        of DART types and of classes derived from them.
        """
        name = expand(re.sub(r"\s+", "", name).lstrip(":"), namespace_aliases)
        scope = tokens.scopes.get(index, ())

        def inherited(size):
            enclosing = "::".join(scope[:size])
            for parent in ancestry.get(enclosing, ()):
                if f"{parent}::{name}" in tokens.aliases:
                    return tokens.aliases[f"{parent}::{name}"], f"{parent}::{name}"
            for base in sorted(local_bases.get(enclosing, ())):
                found = api.find(name, tuple(base.split("::")), imports, tokens.aliases)
                if found[0]:
                    return found
            return None, None

        def constructor_using(target, where, depth):
            if depth != len(where) or "::".join(where) not in source_classes:
                return False
            owner, _, member = expand(target, namespace_aliases).rpartition("::")
            if member == owner.rsplit("::", 1)[-1]:
                return True
            resolved = api.owner(api.resolve(owner, where, imports, tokens.aliases))
            return bool(resolved and member == resolved.rsplit("::", 1)[-1])

        using = [
            (depth, target, where)
            for short, target, where, start, stop, depth in tokens.using
            if short == name
            and start < index < stop
            and scope[: len(where)] == where
            and not constructor_using(target, where, depth)
        ]
        if using:
            depth = max(entry[0] for entry in using)
            local = next(
                (
                    candidate
                    for candidate in api.spellings(name, scope)
                    if candidate in api.types
                    or candidate in tokens.aliases
                    or candidate in source_classes
                    or any(
                        candidate in alias_declarations[header]
                        for header in closure[tokens.source_path]
                    )
                ),
                None,
            )
            local_depth = len(local.split("::")) - 1 if local else 0
            for size in range(len(scope), max(depth, local_depth), -1):
                found = inherited(size)
                if found[0]:
                    return found
            if local is None or depth >= len(local.split("::")) - 1:
                for level, target, where in using:
                    if level == depth:
                        found = api.find(
                            expand(target, namespace_aliases),
                            where,
                            imports,
                            tokens.aliases,
                        )
                        if found[0]:
                            return found
                return None, None
            if local not in api.types and local not in tokens.aliases:
                return None, None
        found = api.find(name, scope, imports, tokens.aliases)
        if found[0]:
            return found
        for size in range(len(scope), 0, -1):
            found = inherited(size)
            if found[0]:
                return found
        head, _, nested = name.rpartition("::")
        if head:
            outer = lookup(head, tokens, index, imports, namespace_aliases)[0]
            owners = (
                [api.owner(outer), *sorted(api.ancestors(outer))]
                if outer
                else sorted(local_bases.get(head, ()))
            )
            for owner in owners:
                if f"{owner}::{nested}" in api.types:
                    return f"{owner}::{nested}", None
        return None, None

    def resolve(name, tokens, index, imports, namespace_aliases):
        return lookup(name, tokens, index, imports, namespace_aliases)[0]

    def standard_name(name, tokens, index, namespace_aliases):
        """Expand a visible standard name, respecting source type/import shadows."""
        name = expand(name.lstrip(":"), namespace_aliases)
        if "::" in name:
            return name
        if tokens.source_path not in closure:
            return name
        if name not in {
            "move",
            "forward",
            "as_const",
            "optional",
            "shared_ptr",
            "unique_ptr",
            "weak_ptr",
            "vector",
            "array",
            "deque",
            "list",
            "forward_list",
            "set",
            "unordered_set",
            "multiset",
            "unordered_multiset",
            "map",
            "multimap",
            "unordered_map",
            "unordered_multimap",
            "function",
            "pair",
            "tuple",
            "variant",
            "get",
        }:
            return name
        scope = tokens.scopes.get(index, ())
        local = next(
            (
                candidate
                for candidate in api.spellings(name, scope)
                if candidate in api.types
                or candidate in source_classes
                or candidate in tokens.aliases
                or any(
                    candidate in alias_declarations[header]
                    for header in closure[tokens.source_path]
                )
            ),
            None,
        )
        local_depth = len(local.split("::")) - 1 if local else -1
        using = [
            (
                0 if short is None else depth,
                expand(target.lstrip(":"), namespace_aliases)
                + ("::" + name if short is None else ""),
                short,
            )
            for short, target, where, start, stop, depth in tokens.using
            if short in {None, name}
            and start < index < stop
            and scope[: len(where)] == where
        ]
        declared_at = {
            len(owner)
            for header in closure[tokens.source_path]
            for owner in declared[header].get(name, ())
            if scope[: len(owner)] == owner
        }
        depth = max(declared_at | {local_depth} | {level for level, _, _ in using})
        if local and local_depth >= depth:
            return local
        return next(
            (
                target
                for level, target, short in using
                if level == depth and (short is not None or target.startswith("std::"))
            ),
            name,
        )

    def wrapped(name, tokens, index, imports, namespace_aliases):
        """Whether `name` resolves through a source alias that wraps its type."""
        alias = lookup(name, tokens, index, imports, namespace_aliases)[1]
        return alias in tokens.wrapped

    def pointer_alias(name, tokens, index, imports, namespace_aliases, depth=0):
        resolved, alias = lookup(name, tokens, index, imports, namespace_aliases)
        if alias or resolved:
            return (
                alias in tokens.raw_pointers
                if alias
                else resolved in api.raw_pointers | api.standard_pointers
            )
        if depth < 8:
            for candidate in api.spellings(
                expand(name, namespace_aliases), tokens.scopes.get(index, ()), imports
            ):
                for header in closure[tokens.source_path]:
                    declaration = alias_declarations[header].get(candidate)
                    if declaration:
                        values, alias_index, (_, context, spaces, renamed) = declaration
                        return raw_pointer(values) or any(
                            not in_template_argument(values, start)
                            and pointer_alias(
                                value, context, alias_index, spaces, renamed, depth + 1
                            )
                            for start, _, value in names_in(values)
                        )
        return False

    def optional_element(name, tokens, index, imports, namespace_aliases, depth=0):
        """Resolve an optional alias's value element in its declaration context."""
        if depth > 8:
            return None
        resolved, alias = lookup(name, tokens, index, imports, namespace_aliases)
        if resolved in api.optional_arguments:
            argument, scope = api.optional_arguments[resolved]
            if raw_pointer(argument) or any(value in {"&", "&&"} for value in argument):
                return None
            return next(
                (
                    element
                    for start, _, value in names_in(argument)
                    if not in_template_argument(argument, start)
                    and (element := api.constructible(api.resolve(value, scope)))
                ),
                None,
            )
        declaration = next(
            (
                alias_declarations[header][alias]
                for header in reversed(closure[tokens.source_path])
                if alias in alias_declarations[header]
            ),
            None,
        )
        if declaration is None:
            return None
        values, index, (_, tokens, imports, namespace_aliases) = declaration
        if raw_pointer(values):
            return None
        optional = next(
            (
                end
                for start, end, value in names_in(values)
                if not in_template_argument(values, start)
                and standard_name(value, tokens, index, namespace_aliases)
                == "std::optional"
            ),
            None,
        )
        if optional is not None:
            argument = first_template_argument(values, optional)
            if raw_pointer(argument) or any(value in {"&", "&&"} for value in argument):
                return None
            return next(
                (
                    element
                    for start, _, value in names_in(argument)
                    if not in_template_argument(argument, start)
                    and not pointer_alias(
                        value, tokens, index, imports, namespace_aliases
                    )
                    and not wrapped(value, tokens, index, imports, namespace_aliases)
                    and (
                        element := api.constructible(
                            resolve(value, tokens, index, imports, namespace_aliases)
                        )
                    )
                ),
                None,
            )
        return next(
            (
                element
                for start, _, value in names_in(values)
                if not in_template_argument(values, start)
                and (
                    element := optional_element(
                        value, tokens, index, imports, namespace_aliases, depth + 1
                    )
                )
            ),
            None,
        )

    # Member fields are shared across headers and implementation files.
    for _ in range(3):
        for (
            path,
            tokens,
            classes,
            _,
            source_aliases,
            imports,
            namespace_aliases,
        ) in files:
            visible(path, tokens)
            for name, values, index in source_aliases:
                for start, _, value in names_in(values):
                    resolved = resolve(value, tokens, index, imports, namespace_aliases)
                    if resolved:
                        wrapper = wraps(
                            values,
                            lambda value: resolve(
                                value, tokens, index, imports, namespace_aliases
                            )
                            and not wrapped(
                                value, tokens, index, imports, namespace_aliases
                            ),
                        ) or bool(
                            function_pointer_declarator(values)
                            or function_type_signature(values)
                        )  # a callable alias names a function type, not its return
                        pointer = (
                            raw_pointer(values)
                            or any(
                                target
                                in {
                                    "std::shared_ptr",
                                    "std::unique_ptr",
                                    "std::weak_ptr",
                                }
                                and not in_template_argument(values, offset)
                                for offset, _, target in names_in(values)
                            )
                            or not in_template_argument(values, start)
                            and pointer_alias(
                                value, tokens, index, imports, namespace_aliases
                            )
                        )
                        targets[path][name] = (resolved, wrapper, pointer)
                        publish(tokens, name, resolved, wrapper, pointer)
                        break
            for cls in classes:
                bases = set()
                for raw in cls["bases"]:
                    raw = base_name(raw)
                    resolved = resolve(
                        raw, tokens, cls["index"], imports, namespace_aliases
                    )
                    if resolved:
                        bases.update(api.ancestors(resolved))
                        owner = api.owner(resolved)
                        if owner and owner not in api_parents[cls["name"]]:
                            api_parents[cls["name"]].append(owner)
                    bases.update(local_bases.get(raw, set()))
                if bases:
                    local_bases[cls["name"]] = bases
                    local_bases[cls["name"].split("::")[-1]] = bases
    for path, tokens, *_ in files:
        visible(path, tokens)

    source_types = {
        name
        for _, _, classes, _, source_aliases, _, _ in files
        for name in [
            *(cls["name"] for cls in classes),
            *(alias[0] for alias in source_aliases),
        ]
    }
    source_types.update(name.split("::")[-1] for name in tuple(source_types))

    def contextual_constructors(
        prefix, context, api_scope=None, depth=0, temporary=True, wrap=None
    ):
        """DART classes a value of `prefix` constructs, as initialized by `wrap`.

        `wrap` is the source tokens that precede and follow the type; without it
        the value is default-initialized.
        """
        if depth > 8:
            return set()
        before, after = wrap or ([], ["__returned_value", "{", "}", ";"])
        path, tokens, index, imports, namespace_aliases = context
        prefix = [
            value
            for offset, value in enumerate(prefix)
            if not temporary
            or value not in {"&", "&&"}
            or in_template_argument(prefix, offset)
        ]
        returned = Tokens(" ".join(before + prefix + after))
        result = set()
        for start, end, spelling in names_in(prefix):
            if not constructs(
                returned, start + len(before), end + len(before), set(), []
            ):
                continue
            name, alias = (
                (api.resolve(spelling, api_scope), None)
                if api_scope is not None
                else lookup(spelling, tokens, index, imports, namespace_aliases)
            )
            declaration = (
                next(
                    (
                        alias_declarations[header][alias]
                        for header in closure[path]
                        if alias in alias_declarations[header]
                    ),
                    None,
                )
                if api_scope is None
                else None
            )
            if declaration:
                values, where, (source, owner, spaces, renamed) = declaration
                result.update(
                    contextual_constructors(
                        values,
                        (source, owner, where, spaces, renamed),
                        depth=depth + 1,
                        temporary=temporary and not in_template_argument(prefix, start),
                        wrap=None if in_template_argument(prefix, start) else wrap,
                    )
                )
            elif name in api.alias_arguments:
                values, scope = api.alias_arguments[name]
                result.update(
                    contextual_constructors(
                        values,
                        context,
                        scope,
                        depth + 1,
                        temporary=temporary and not in_template_argument(prefix, start),
                        wrap=None if in_template_argument(prefix, start) else wrap,
                    )
                )
            elif alias in tokens.wrapped:
                continue  # a source alias of a wrapper or callable, not its element
            elif constructed := api.constructible(name):
                result.add((name, constructed))
        return result

    def layout_prefix(prefix, context, depth=0):
        """Expand source aliases in their defining context before classifying storage."""
        if depth > 8:
            return prefix
        path, tokens, index, imports, namespace_aliases = context
        result, previous = [], 0
        for start, end, spelling in names_in(prefix):
            result.extend(prefix[previous:start])
            name, alias = lookup(spelling, tokens, index, imports, namespace_aliases)
            declaration = next(
                (
                    alias_declarations[header][alias]
                    for header in reversed(closure[path])
                    if alias in alias_declarations[header]
                ),
                None,
            )
            if declaration:
                values, where, (source, owner, spaces, renamed) = declaration
                result.extend(
                    layout_prefix(
                        values, (source, owner, where, spaces, renamed), depth + 1
                    )
                )
            else:
                result.extend(
                    TOKEN.findall(
                        name
                        or standard_name(spelling, tokens, index, namespace_aliases)
                    )
                )
            previous = end
        return result + prefix[previous:]

    def head_hidden(name, tokens, index, imports, namespace_aliases):
        """Whether a live local binding (settled once late) or an ordinary
        function or value declaration hides an unqualified head at index."""
        return any(
            b[0] <= index <= b[1]
            and b[2] <= index
            and b[3] == name
            and compatible(tokens.branches[b[2]], tokens.branches[index])
            for b in tokens.bindings
        ) or function_hides(name, tokens, index, imports, namespace_aliases)

    def shadowed_head(tokens, head, context):
        """Whether a live local binding may hide the unqualified call head: unknown
        until the binding pass has run, so the site is deferred until then."""
        _, file_tokens, index, imports, namespace_aliases = context
        if head[1] - head[0] != 1 or not IDENTIFIER.match(tokens.values[head[0]]):
            return False
        if not file_tokens.late:
            file_tokens.ambiguous = True
            return False
        return head_hidden(
            tokens.values[head[0]], file_tokens, index, imports, namespace_aliases
        )

    def pending_sequence(sequence):
        """Whether the deferred count filter owns a sized sequence's elements:
        its normalized or raw-alternative candidates are nonempty."""
        return bool(sequence and (sequence[0] or sequence[5] and sequence[5][0]))

    def normalized_typed_clause(tokens, first, last, context, defer=True):
        """The clause, with an explicit `Type{...}` or `Type(...)` head normalized
        where it is written rather than in an alias target's scope."""
        values = tokens.values
        head = explicit_typed_prvalue(tokens, first, last)
        if head is None or (defer and shadowed_head(tokens, head, context)):
            return values[first : last + 1]
        return (
            values[first : head[0]]
            + construction_aliases(
                layout_prefix(values[head[0] : head[1]], context), api
            )
            + values[head[1] : last + 1]
        )

    def normalized_initializer(initializer, context):
        """A declarator initializer with its sole typed clause normalized."""
        tokens = Tokens(" ".join(initializer))
        opening = int(initializer[:1] == ["="])
        if initializer[opening : opening + 1] not in (["("], ["{"]):
            return initializer
        arguments = construction_arguments(tokens, opening)
        if len(arguments) != 1:
            return initializer
        first, last = arguments[0]
        return (
            initializer[:first]
            + normalized_typed_clause(tokens, first, last, context)
            + initializer[last + 1 :]
        )

    def sized_sequence(tokens, start, end, context, declarations, heads):
        """Constructor candidates and the count operand for one source use."""
        values = tokens.values
        start, end = construction_type_span(values, start, end)
        variable = variable_after_type(values, end)
        opening = (
            array_end(tokens, variable + 1)
            if variable is not None
            else template_end(values, end)
        )
        if values[opening : opening + 1] == ["="]:
            opening += 1
        closing = tokens.pairs.get(opening)
        if closing is None or values[opening] not in {"(", "{"}:
            return None
        arguments = construction_arguments(tokens, opening)
        lead = start
        while lead and values[lead - 1] in {"const", "volatile", "::"}:
            lead -= 1
        prefix = values[
            lead : variable if variable is not None else template_end(values, end)
        ]
        prefix = construction_aliases(layout_prefix(prefix, context), api)
        factory = next(
            (
                (first, after, name)
                for first, after, name in names_in(prefix)
                if not in_template_argument(prefix, first)
            ),
            None,
        )
        if factory and factory[2] in {
            "std::make_unique",
            "std::make_shared",
            "std::allocate_shared",
        }:
            prefix = first_template_argument(prefix, factory[1])
            if not value_argument(prefix):
                return None
            prefix = construction_aliases(prefix, api)
            if factory[2] == "std::allocate_shared":
                arguments = arguments[1:]
        if not any(
            name in SIZED_SEQUENCES and not in_template_argument(prefix, index)
            for index, _, name in names_in(prefix)
        ):
            return None
        if not 1 <= len(arguments) <= 2:
            return None
        if variable is not None and not constructs(
            tokens, start, end, declarations, heads
        ):
            return None
        count_first, count_last = arguments[0]

        def candidates_for(clause):
            initialized = Tokens(
                " ".join(
                    prefix
                    + ["__sequence_value", values[opening]]
                    + clause
                    + [values[closing], ";"]
                )
            )
            result = set()
            for first, last, name in names_in(prefix):
                resolved = api.resolve(name)
                constructed = api.constructible(resolved)
                if constructed and constructs(initialized, first, last, set(), []):
                    result.add((resolved, constructed))
            return result

        raw = values[count_first : count_last + 1]
        clause, alternative = raw, None
        head = explicit_typed_prvalue(tokens, count_first, count_last)
        if len(arguments) == 1 and head:
            clause = normalized_typed_clause(
                tokens, count_first, count_last, context, defer=False
            )
            if head[1] - head[0] == 1:  # a local binding may still hide the alias
                alternative = candidates_for(raw), head[0]
        candidates = candidates_for(clause)
        return (
            candidates,
            count_first,
            count_last,
            lead,
            arguments[1] if len(arguments) == 2 else None,
            alternative,
        )

    def sequence_allocator(path, tokens, first, last, imports, namespace_aliases):
        """A literal or visible typed variable naming the standard allocator."""
        while (
            tokens.values[first : first + 1] == ["("]
            and tokens.pairs.get(first) == last
        ):
            first, last = first + 1, last - 1
        prefix = tokens.values[first : last + 1]
        contexts = [(prefix, first)]
        if first == last:
            contexts += [
                (typed_variables[path][binding[2]][0], binding[2])
                for binding in tokens.bindings
                if binding[0] <= first <= binding[1]
                and binding[2] <= first
                and binding[3] == tokens.values[first]
                and binding[2] in typed_variables[path]
                and compatible(tokens.branches[binding[2]], tokens.branches[first])
            ]
        for prefix, index in contexts:
            context = path, tokens, index, imports, namespace_aliases
            prefix = construction_aliases(layout_prefix(prefix, context), api)
            if not raw_pointer(prefix) and any(
                name == "std::allocator" and not in_template_argument(prefix, start)
                for start, _, name in names_in(prefix)
            ):
                return True
        return False

    def layout_operand(tokens, index):
        opening = tokens.enclosing[index]
        while opening is not None:
            if tokens.values[opening - 1 : opening] in (["sizeof"], ["alignof"]):
                return opening + 1, tokens.pairs[opening]
            opening = tokens.enclosing[opening]
        for before in range(index - 1, -1, -1):
            if tokens.values[before] in {";", "{", "}"}:
                break
            if tokens.values[before] == "sizeof":
                span = layout_operator_operand(tokens, before)
                if span and span[0] <= index < span[1]:
                    return span
        return None

    def layout_type_operand(prefix):
        return not any(
            value in {"(", "{", ".", "->", "?", "=", "+", "-", "/", "%", "!"}
            and not in_template_argument(prefix, index)
            for index, value in enumerate(prefix)
        )

    def unevaluated_operand(tokens, index):
        if layout_operand(tokens, index):
            return True
        opening = tokens.enclosing[index]
        while opening is not None:
            if tokens.values[opening - 1 : opening] in (
                ["sizeof"],
                ["alignof"],
                ["decltype"],
                ["noexcept"],
            ):
                return True
            opening = tokens.enclosing[opening]
        return False

    def value_type_prefix(tokens, start, end):
        """Retain outer wrappers and declarator indirection around a named type."""
        values = tokens.values
        start, end = construction_type_span(values, start, end)
        variable = variable_after_type(values, end)
        if variable is None:
            return None
        lead = start
        while lead and values[lead - 1] in {"const", "volatile", "::"}:
            lead -= 1
        if values[lead - 1 : lead] in (["using"], ["typedef"]):
            return None
        # A using declaration defines a type; it does not instantiate its storage.
        first = lead
        while first and values[first - 1] not in {";", "{", "}"}:
            first -= 1
        if values[first : first + 1] in (["using"], ["typedef"]):
            return None
        prefixes = [values[lead:variable]]
        for part, _ in declarators(values[lead : statement_end(tokens, lead)], None):
            item = data_member(part, None)
            if item:
                prefixes.append(item["return_tokens"])
        return prefixes

    def array_type(type_tokens, context):
        """A type spelling with source and API aliases expanded."""
        return construction_aliases(layout_prefix(type_tokens, context), api)

    def nearest_binding(tokens, name, index):
        """The innermost live declaration of `name` visible at `index`."""
        found = sorted(
            (
                binding
                for binding in tokens.bindings
                if binding[0] <= index <= binding[1]
                and binding[2] <= index
                and binding[3] == name
                and compatible(tokens.branches[binding[2]], tokens.branches[index])
            ),
            key=lambda binding: (binding[1] - binding[0], -binding[2]),
        )
        return found[0] if found else None

    def declared_array_type(tokens, first, last, context):
        """Read array shape from the established declaration/expression inference."""
        _, _, _, imports, namespace_aliases = context
        values = tokens.values
        if first > last:
            return None, 0
        binding = (
            nearest_binding(tokens, values[first], first)
            if first == last and IDENTIFIER.match(values[first])
            else None
        )
        if binding is not None:
            types = binding[4]
        elif (
            last > first
            and values[last - 1] == "::"
            and all(IDENTIFIER.match(v) or v == "::" for v in values[first : last + 1])
        ):
            owner = expand(
                "::".join(v for v in values[first : last - 1] if v != "::"),
                namespace_aliases,
            )
            known = next(
                (
                    entry
                    for entry in tokens.bindings
                    if entry[3] == values[last]
                    and "::".join(tokens.scopes.get(entry[2], ())) == owner
                ),
                None,
            )
            types = (
                known[4]
                if known is not None
                else expression_receiver(
                    tokens, first, last, imports, namespace_aliases
                )
            )
        else:
            types = expression_receiver(tokens, first, last, imports, namespace_aliases)
        # Raw declarator dimensions are already nested element markers. A bare
        # remaining rank is not the contained std::array value.
        rank = 0
        while RAW_ARRAY in types:
            rank += 1
            types = elements(types)
        marks = {
            parse_array_marker_key(t) for t in types if t.startswith(ARRAY_IDENTITY)
        }
        if len(marks) != 1:
            return None, 0
        spelling, pointers = next(iter(marks))
        return TOKEN.findall(spelling), pointers + rank

    def whole_array_clause(tokens, first, last, context, target):
        """Whether the sole clause is a known object of the `target` array type.

        Without inferred types yet the decision is deferred (`tokens.ambiguous`).
        """
        clause = tokens.values[first : last + 1]
        if (
            clause[0] == "{"
            or clause[-1] == "}"
            or re.fullmatch(r"[0-9'\"].*", clause[0])
        ):
            return False
        if not tokens.late:
            tokens.ambiguous = True
            return False
        declared, pointers = declared_array_type(tokens, first, last, context)
        wanted = array_identity(array_type(target, context), api)
        return bool(declared and wanted and not pointers and declared == wanted[0])

    def mark_array_copy(tokens, initializer, base, context, target):
        """Spell a sole whole-array clause as one `__array_value` token."""
        brace = next((k for k, v in enumerate(initializer) if v == "{"), None)
        if brace is None or any(v in {"(", "["} for v in initializer[:brace]):
            return initializer
        inner = Tokens(" ".join(initializer))
        clauses = construction_arguments(inner, brace)
        if (
            len(clauses) == 1
            and initializer[clauses[0][0]] != "{"
            and whole_array_clause(
                tokens, base + clauses[0][0], base + clauses[0][1], context, target
            )
        ):
            first, last = clauses[0]
            return initializer[:first] + ["__array_value"] + initializer[last + 1 :]
        return initializer

    def default_variant_constructions(
        tokens, start, end, context, declarations, heads, direct
    ):
        """Default-owned variant elements for each grouped source declarator."""
        values = tokens.values
        start, end = construction_type_span(values, start, end)
        lead = start
        while lead and values[lead - 1] in {
            "const",
            "volatile",
            "::",
            "static",
            "thread_local",
            "inline",
            "constexpr",
        }:
            lead -= 1
        grouped = not lead or values[lead - 1] in {";", "{", "}"}
        if lead and values[lead - 1] == "{":
            grouped = statement_end(tokens, lead) < tokens.pairs.get(lead - 1, lead)
        variable = variable_after_type(values, end, grouped=grouped)
        prefix = values[
            lead : variable if variable is not None else template_end(values, end)
        ]
        while variable is not None and prefix and prefix[-1] == "(":
            prefix = prefix[:-1]
        prefix = layout_prefix(prefix, context)
        template_alias = not direct and any(  # an explicit alias-template-id
            prefix[end : end + 1] == ["<"]
            and api.alias_parameters.get(api.resolve(name, ()))
            for _, end, name in names_in(prefix)
        )
        prefix = construction_aliases(prefix, api)
        if not template_alias and not any(
            name == "std::variant" for _, _, name in names_in(prefix)
        ):
            return None
        if variable is None:
            if direct:
                return None
            if not constructs(tokens, start, end, declarations, heads):
                return []
            # The expression's own bounds and arguments follow the type.
            after = template_end(values, end)
            bounds, opening = array_bounds(tokens, after)
            if opening in tokens.pairs and values[opening] in {"(", "{"}:
                opening = tokens.pairs[opening] + 1
            wrap = (["new"] if values[lead - 1 : lead] == ["new"] else []), [
                *normalized_initializer(
                    mark_array_copy(
                        tokens, values[after:opening], after, context, prefix
                    ),
                    context,
                ),
                ";",
            ]
            return [
                (name, dependency, start)
                for name, dependency in sorted(
                    contextual_constructors(prefix, context, temporary=False, wrap=wrap)
                )
            ]
        result = []
        for part, offset in declarators(
            values[lead : statement_end(tokens, lead)], None
        ):
            declared = Tokens(" ".join(part + [";"]))
            local = variable_after_type(declared.values, end - lead, grouped=grouped)
            if local is None:
                continue
            site = lead + offset + local
            opening = local
            while part[opening - 1 : opening] == ["("]:
                opening -= 1  # every redundant `(` of the grouped name
            prefix = part[:opening]
            after = local + 1
            inner_bounds = []
            if opening != local:
                _, after, bounds, _ = grouped_object(declared, opening)
                inner_bounds = [
                    value
                    for bound in bounds
                    for value in part[bound : declared.pairs[bound] + 1]
                ]
            initializer = inner_bounds + mark_array_copy(
                tokens,
                part[after:],
                lead + offset + after,
                context,
                prefix,
            )
            if not constructs(
                tokens,
                start,
                end,
                declarations,
                heads,
                declarator={"name_index": site, "return_tokens": prefix},
            ):
                continue
            prefix = construction_aliases(layout_prefix(prefix, context), api)
            if function_type_signature(prefix):
                continue
            result.extend(
                (name, dependency, site)
                for name, dependency in sorted(
                    contextual_constructors(
                        prefix,
                        context,
                        temporary=False,
                        wrap=(
                            [],
                            [
                                "__returned_value",
                                *normalized_initializer(initializer, context),
                                ";",
                            ],
                        ),
                    )
                )
            )
        return result

    def retain_layout(row, owners):
        declarations = []
        for owner in owners:
            for item in api.layout_declarations(owner):
                declaration = used_declaration(item, layout=True)
                aliases, enums, constants = api.layout_type_declarations(
                    api.field_template_mask(item, item["return_tokens"]),
                    tuple(item["class"].split("::")),
                )
                if aliases:
                    declaration["type_alias_declarations"] = aliases
                if enums:
                    declaration["enum_declarations"] = enums
                if constants:
                    declaration["type_constant_declarations"] = constants
                unions = sorted(
                    {
                        header
                        for child in api.layout_owners(
                            item["return_tokens"], tuple(item["class"].split("::"))
                        )
                        for header in api.type_unions.get(child, ())
                    }
                )
                if unions:
                    declaration["union_declarations"] = unions
                declared_types = api.decltype_declarations(
                    item["return_tokens"], tuple(item["class"].split("::"))
                )
                if declared_types:
                    declaration["declared_type_declarations"] = [
                        used_declaration(callee) for callee in declared_types
                    ]
                declarations.append(declaration)
        if declarations:
            row["layout_declarations"] = declarations

    def record_type(resolved, path, tokens, index):
        owners = api.ancestors(resolved) | {resolved}
        templates = sorted(
            {
                declaration
                for owner in owners
                for declaration in api.type_templates.get(owner, ())
            }
        )
        final_classes = sorted(
            owner for owner in owners if api.classes.get(owner, {}).get("final")
        )
        enums = sorted(
            {
                declaration
                for owner in owners
                for declaration in api.type_enums.get(owner, ())
            }
        )
        unions = sorted(
            {
                declaration
                for owner in owners
                for declaration in api.type_unions.get(owner, ())
            }
        )
        alignments = api.alignment_declarations(resolved)
        annotations = [
            {"class": owner, "signature": signature}
            for owner in sorted(owners)
            for signature in sorted(api.type_annotations.get(owner, ()))
        ]
        return add(
            "types",
            resolved,
            path,
            tokens.line(index),
            **({"template_declarations": templates} if templates else {}),
            **({"final_classes": final_classes} if final_classes else {}),
            **({"enum_declarations": enums} if enums else {}),
            **({"union_declarations": unions} if unions else {}),
            **({"alignment_declarations": alignments} if alignments else {}),
            **({"annotation_declarations": annotations} if annotations else {}),
        )

    def construct_site(
        path,
        tokens,
        start,
        type_end,
        name,
        resolved,
        row,
        context,
        sequence,
        declaration_indices,
        heads,
        function_alias,
        imports,
        namespace_aliases,
    ):
        """Record the constructions of one named type; False when deferred."""
        values = tokens.values
        tokens.ambiguous = False
        optional = (
            optional_element(name, tokens, start, imports, namespace_aliases)
            if in_place_initializer(tokens, type_end)
            else None
        )
        constructed = optional or api.constructible(resolved)
        direct_construction = (
            constructed
            and not sequence
            and (
                optional or not wrapped(name, tokens, start, imports, namespace_aliases)
            )
            and constructs(tokens, start, type_end, declaration_indices, heads)
        )
        variant = (
            []
            if function_alias
            # The deferred count filter owns a sized sequence's elements.
            else (
                None
                if pending_sequence(sequence)
                else default_variant_constructions(
                    tokens,
                    start,
                    type_end,
                    context,
                    declaration_indices,
                    heads,
                    direct_construction,
                )
            )
        )
        if tokens.ambiguous and not tokens.late:
            return False  # a whole-array copy needs inferred types; decide later
        if variant is not None:
            for constructed_name, dependency, site in variant:
                if (
                    in_template_argument(values, start)
                    and api.owner(resolved) != dependency
                ):
                    continue
                constructor_row = tables["types"].get(constructed_name) or record_type(
                    constructed_name, path, tokens, site
                )
                if not unevaluated_operand(tokens, start):
                    retain_layout(constructor_row, [dependency])
                record_constructor(constructed_name, dependency, path, tokens, site)
        elif direct_construction:
            if not unevaluated_operand(tokens, start):
                retain_layout(row, [constructed])
            after = template_end(values, type_end)
            variable = variable_after_type(values, type_end)
            if variable is not None:
                after = array_end(tokens, variable + 1)
            record_constructor(
                resolved,
                constructed,
                path,
                tokens,
                start,
                braced=not any(head < start < body for head, body in heads)
                and (
                    values[after : after + 1] == ["{"]
                    or values[after : after + 2] == ["=", "{"]
                ),
            )
        return True

    deferred_sites = []

    sequence_pending = {}
    for (
        path,
        tokens,
        classes,
        functions,
        source_aliases,
        imports,
        namespace_aliases,
    ) in files:
        values = tokens.values
        tokens.source_relevant = path.startswith("dartsim/")
        tokens.array_copy = lambda first, last, target, tokens=tokens, context=(
            path,
            tokens,
            0,
            imports,
            namespace_aliases,
        ): whole_array_clause(tokens, first, last, context, target)
        declaration_indices = {function["name_index"] for function in functions}
        heads = [(cls["index"], cls["body"]) for cls in classes]
        function_alias_spans = [
            (index, statement_end(tokens, index))
            for _, prefix, index in source_aliases
            if function_type_signature(prefix)
        ]
        for start, end, name in names_in(values):
            resolved = resolve(name, tokens, start, imports, namespace_aliases)
            type_end = end
            while not resolved and "::" in name:
                name = name.rsplit("::", 1)[0]
                type_end -= 2
                resolved = resolve(name, tokens, start, imports, namespace_aliases)
            if not resolved:
                continue
            if values[type_end : type_end + 1] != ["::"] and function_hides(
                name, tokens, start, imports, namespace_aliases
            ):
                continue  # an ordinary call of the hiding function, not the type
            row = record_type(resolved, path, tokens, start)
            context = path, tokens, start, imports, namespace_aliases
            sequence = sized_sequence(
                tokens, start, type_end, context, declaration_indices, heads
            )
            if pending_sequence(sequence):
                sequence_classes, first, last, lead, allocator, alternative = sequence
                sequence_pending[path, lead] = (
                    tokens,
                    sequence_classes,
                    first,
                    last,
                    allocator,
                    alternative,
                    imports,
                    namespace_aliases,
                )
            operand = layout_operand(tokens, start)
            if operand:
                prefix = values[slice(*operand)]
                prefixes = [prefix] if layout_type_operand(prefix) else []
            else:
                prefixes = value_type_prefix(tokens, start, type_end) or []
            owners = [
                owner
                for prefix in prefixes
                for owner in api.layout_owners(
                    layout_prefix(prefix, context), references=bool(operand)
                )
            ]
            owner = api.owner(resolved)
            if owner in owners:
                retain_layout(row, [owner])
            tokens.source_relevant = True
            referenced.update(api.ancestors(resolved))
            function_alias = any(
                first <= start < last
                and tokens.enclosing[start] == tokens.enclosing[first]
                for first, last in function_alias_spans
            )
            site = (
                path,
                tokens,
                start,
                type_end,
                name,
                resolved,
                row,
                context,
                sequence,
                declaration_indices,
                heads,
                function_alias,
                imports,
                namespace_aliases,
            )
            if not construct_site(*site):
                deferred_sites.append(site)
            j = (
                None
                if in_template_argument(values, start)
                else bound_variable_after_type(
                    tokens,
                    start,
                    type_end,
                    not function_hides(name, tokens, start, imports, namespace_aliases),
                )
            )
            if j is not None and j not in declaration_indices:
                owner = api.owner(resolved)
                if owner or resolved in api.alias_arguments:
                    types = {resolved} if owner else set()
                    if "*" in values[
                        template_end(values, type_end) : j
                    ] or pointer_alias(name, tokens, start, imports, namespace_aliases):
                        types.add(RAW_POINTER)
                    types = array_types(tokens, j, types)
                    bind_variable(tokens, j, types)
                    typed_variables[path].setdefault(
                        j, (type_prefix(values, start, j), is_field(tokens, j, classes))
                    )
                    for later, later_prefix in later_declarators(tokens, start):
                        types = {resolved} if owner else set()
                        if "*" in later_prefix[
                            template_end(values, type_end) - start :
                        ] or pointer_alias(
                            name, tokens, start, imports, namespace_aliases
                        ):
                            types.add(RAW_POINTER)
                        bind_variable(tokens, later, array_types(tokens, later, types))
                        typed_variables[path].setdefault(
                            later, (later_prefix, is_field(tokens, later, classes))
                        )
        for start, end, name in names_in(values):
            if resolve(name, tokens, start, imports, namespace_aliases):
                continue
            if (
                ("::" in name and not name.startswith("dart::"))
                or THIRD_PARTY.match(name)
                or name in {"optional", "shared_ptr", "unique_ptr", "weak_ptr"}
                and standard_name(name, tokens, start, namespace_aliases)
                in {"std::optional", *SMART_POINTERS}
                or name.split("::")[-1] in source_types
                or name in {"int", "double", "float", "bool", "char", "size_t"}
            ):
                known_type = (
                    THIRD_PARTY.match(name)
                    or name in {"int", "double", "float", "bool", "char", "size_t"}
                    or standard_name(name, tokens, start, namespace_aliases)
                    in {
                        "std::optional",
                        "std::variant",
                        *SMART_POINTERS,
                        *ELEMENT_CONTAINERS,
                        *MAP_CONTAINERS,
                        *PRODUCTS,
                    }
                    or source_type(name, tokens, start, imports, namespace_aliases)
                )
                j = bound_variable_after_type(
                    tokens,
                    start,
                    end,
                    bool(known_type)
                    and not function_hides(
                        name, tokens, start, imports, namespace_aliases
                    ),
                )
                if j is None or j in declaration_indices:
                    continue
                contained = set(local_bases.get(name, ()))
                source_owner = source_class(
                    standard_name(name, tokens, start, namespace_aliases),
                    tokens.scopes.get(start, ()),
                    imports,
                    namespace_aliases,
                    tokens.source_path,
                )
                if source_owner:
                    contained.update(local_bases.get(source_owner, ()))
                if name in {"std::shared_ptr", "std::unique_ptr", "std::weak_ptr"}:
                    for offset, _, value in names_in(values[end:j]):
                        resolved = resolve(
                            value, tokens, end + offset, imports, namespace_aliases
                        )
                        if api.owner(resolved):
                            contained.add(resolved)
                    if contained:
                        contained.add(RAW_POINTER)
                if not contained:
                    contained.update(
                        container_elements(
                            first_template_argument(values, end),
                            api,
                            lambda value: resolve(
                                value, tokens, start, imports, namespace_aliases
                            ),
                            lambda value: pointer_alias(
                                value, tokens, start, imports, namespace_aliases
                            ),
                        )
                    )
                contained = contained or {"__non_dart__"}
                if source_owner:
                    contained.add(SOURCE_CLASS + source_owner)
                    if raw_pointer(values[end:j]) or pointer_alias(
                        name, tokens, start, imports, namespace_aliases
                    ):
                        contained.add(RAW_POINTER)
                    contained = array_types(tokens, j, contained)
                bind_variable(tokens, j, contained)
                typed_variables[path].setdefault(
                    j, (type_prefix(values, start, j), is_field(tokens, j, classes))
                )
                for later, later_prefix in later_declarators(tokens, start):
                    kept = contained - {RAW_POINTER}
                    if RAW_POINTER in contained and (
                        name in {"std::shared_ptr", "std::unique_ptr", "std::weak_ptr"}
                        or raw_pointer(later_prefix[end - start :])
                    ):
                        kept.add(RAW_POINTER)
                    bind_variable(tokens, later, array_types(tokens, later, kept))
                    typed_variables[path].setdefault(
                        later, (later_prefix, is_field(tokens, later, classes))
                    )

        # Init-capture initializers see the enclosing scope; their names exist
        # only in the lambda body, including bodies of nested lambdas.
        tokens.lambda_captures = []
        tokens.lambda_returns = []
        for opening, closing in sorted(tokens.pairs.items()):
            if opening >= closing or values[opening] != "[":
                continue
            body = closing + 1
            if values[body : body + 1] == ["("] and body in tokens.pairs:
                body = tokens.pairs[body] + 1
            elif values[body : body + 1] != ["{"]:
                continue
            arrow = None
            while body < len(values) and values[body] not in {"{", ";", "="}:
                if values[body] in {"(", "["} and body in tokens.pairs:
                    body = tokens.pairs[body] + 1
                else:
                    if values[body] == "->" and arrow is None:
                        arrow = body
                    body += 1
            if values[body : body + 1] != ["{"] or body not in tokens.pairs:
                continue
            if arrow is not None:
                tokens.lambda_returns.append((opening, values[arrow + 1 : body], body))
            span = (body, tokens.pairs[body])
            start = index = opening + 1
            angle = 0
            while index <= closing:
                if index == closing or values[index] == "," and angle == 0:
                    name = start + (values[start : start + 1] == ["&"])
                    initializer = name + 1
                    if name < index and IDENTIFIER.match(values[name]):
                        if values[initializer : initializer + 1] == ["="]:
                            first, last = initializer + 1, index - 1
                        elif (
                            values[initializer : initializer + 1] in (["("], ["{"])
                            and initializer in tokens.pairs
                        ):
                            first, last = initializer + 1, tokens.pairs[initializer] - 1
                        else:
                            first, last = name, name
                        if values[name] != "this":
                            tokens.lambda_captures.append((name, first, last, span))
                            bind_variable(tokens, name, set(), span)
                    start = index + 1
                elif values[index] in {"(", "[", "{"} and index in tokens.pairs:
                    index = tokens.pairs[index]
                elif values[index] == "<":
                    end = template_end(values, index) - 1
                    if (
                        IDENTIFIER.match(values[index - 1])
                        and end < closing
                        and values[end] == ">"
                        and "=" not in values[index + 1 : end]
                    ):
                        angle += 1
                elif values[index] == ">" and angle:
                    angle -= 1
                index += 1

        # Unknown parameter types still hide a same-named namespace function.
        parameters = []
        for function in functions:
            body = function.get("body")
            if body is None:
                continue
            opening = function["name_index"] + len(
                TOKEN.findall(function["name"].split("::")[-1])
            )
            parameters.append((opening, (opening, tokens.pairs[body])))
        parameters += [
            (opening, None)
            for opening, closing in tokens.pairs.items()
            if opening < closing
            and values[opening] == "("
            and values[opening - 1 : opening] == ["]"]
            and opening - 1 in tokens.pairs
        ]
        for opening, span in parameters:
            closing = tokens.pairs.get(opening)
            if closing is None:
                continue
            start = i = opening + 1
            angle = 0
            while i <= closing:
                if i == closing or values[i] == "," and angle == 0:
                    parameter = data_member(values[start:i], None)
                    if parameter and parameter["return_tokens"][-1:] != ["::"]:
                        index = start + parameter["name_index"]
                        if not any(binding[2] == index for binding in tokens.bindings):
                            bind_variable(tokens, index, set(), span)
                    start = i + 1
                elif values[i] in {"(", "[", "{"} and i in tokens.pairs:
                    i = tokens.pairs[i]
                else:
                    angle += (values[i] == "<") - (values[i] == ">")
                i += 1

        # Function-pointer names hide functions; only known foreign results
        # are classified here, without inferring DART callback return types.
        parameter_heads = {opening for opening, _ in parameters}
        for opening, closing in tokens.pairs.items():
            if (
                opening >= closing
                or values[opening] != "("
                or values[opening + 1] not in {"*", "&", "&&"}
            ):
                continue
            name = opening + 2
            while name < closing and values[name] in {"const", "volatile"}:
                name += 1
            if (
                name + 1 != closing
                or not IDENTIFIER.match(values[name])
                or values[closing + 1 : closing + 2] != ["("]
            ):
                continue
            outer = tokens.enclosing[opening]
            if (
                outer is not None
                and values[outer] == "("
                and outer not in parameter_heads
                and values[outer - 1] not in {"if", "for", "while", "switch"}
            ):
                continue
            if values[opening - 1] in {";", "{", "}", "(", ",", "=", ":"}:
                continue
            first = opening - 1
            while first > 0 and values[first - 1] not in {";", "{", "}", "(", ",", "="}:
                first -= 1
            prefix = values[first:opening]
            if not data_member(prefix + [values[name]], None):
                continue
            names = [value for _, _, value in names_in(prefix)]
            foreign = not any(
                api.owner(resolve(value, tokens, name, imports, namespace_aliases))
                for value in names
            ) and any(
                source_class(
                    value, tokens.scopes.get(name, ()), imports, namespace_aliases, path
                )
                or value in {"void", "int", "double", "float", "bool", "char", "size_t"}
                for value in names
            )
            bind_variable(tokens, name, {NON_DART_CALLABLE} if foreign else set())
            owner = "::".join(tokens.scopes.get(name, ()))
            if (
                any(
                    tokens.bindings[-1][0] == cls["body"] and cls["name"] == owner
                    for cls in classes
                )
                and values[name] not in source_fields[owner]
            ):
                source_fields[owner][values[name]].append({"foreign_callable": foreign})

    relevant_files = {path for path, tokens, *_ in files if tokens.source_relevant}
    for path, tokens, *_ in files:
        tokens.source_relevant = any(
            header in relevant_files for header in closure[path]
        )

    def candidates(name, receiver_types, operator=None, table=api.members):
        # shortcut: lexical matching retains overload candidates, use compiler analysis for exact selection.
        if name in {"operator->", "operator[]", "operator()"}:
            receiver_types = receiver_types - api.standard_pointers
            if not receiver_types or RAW_POINTER in receiver_types:
                return []
        if operator == ".":
            receiver_types = receiver_types - api.standard_pointers
            if not receiver_types:
                return []
        owners = (
            set().union(*(api.ancestors(t) for t in receiver_types))
            if receiver_types
            else referenced
        )
        if operator == "." and name in {"get", "lock"}:
            owners = {api.owner(t) for t in receiver_types}
        return [d for d in table.get(name, []) if d["class"] in owners]

    def enclosing_bases(tokens, index):
        """The DART bases of the classes around `index`, which `this` reaches."""
        scope = tokens.scopes.get(index, ())
        return set().union(
            *(
                local_bases.get("::".join(scope[:size]), ())
                for size in range(1, len(scope) + 1)
            )
        )

    def source_member_bases(
        owner, name, tokens, index, imports, namespace_aliases, depth=0
    ):
        """DART bases visible after source members and class using-declarations."""
        if depth > 8:
            return set()
        for cls in [owner, *ancestry.get(owner, ())]:
            brought = set()
            for short, target, where, *_ in tokens.using:
                if short == name and where == tuple(cls.split("::")):
                    spelling = target.rpartition("::")[0]
                    base = api.resolve(
                        expand(spelling, namespace_aliases),
                        where,
                        imports,
                        tokens.aliases,
                    )
                    brought.update(api.ancestors(base))
                    parent = source_class(
                        spelling, where, imports, namespace_aliases, tokens.source_path
                    )
                    if parent:
                        brought.update(
                            source_member_bases(
                                parent,
                                name,
                                tokens,
                                index,
                                imports,
                                namespace_aliases,
                                depth + 1,
                            )
                        )
            if (
                (cls, name) in source_returns
                or name in source_fields[cls]
                or f"{cls}::{name}" in source_types
                or brought
            ):
                return brought
        return set(local_bases.get(owner, ()))

    def source_member_types(types, name, tokens, index, imports, namespace_aliases):
        result = set(types)
        for marker in types:
            if marker.startswith(SOURCE_CLASS):
                owner = marker.removeprefix(SOURCE_CLASS)
                result.difference_update(local_bases.get(owner, ()))
                result.update(
                    source_member_bases(
                        owner, name, tokens, index, imports, namespace_aliases
                    )
                )
        return result

    def record(section, name, declarations, inferred, path, index, tokens):
        if not declarations:
            return
        row = add(
            section,
            name,
            path,
            tokens.line(index),
            declarations=[],
            receiver_types=set(),
            unresolved_count=0,
        )
        row["declarations"].extend(used_declaration(d) for d in declarations)
        dart_receivers = {t for t in inferred if t.startswith("dart::")}
        row["receiver_types"].update(dart_receivers)
        row["unresolved_count"] += not bool(dart_receivers)

    def free_function(name, tokens, index, path, imports, namespace_aliases, depth=0):
        """The DART functions that an unqualified call can reach.

        Lookup stops at the innermost scope that declares the name: a function
        of an enclosing namespace or class, or a using-declaration, counts in
        its own scope, and a using-directive of a DART namespace at the global
        scope.
        """
        scope = tokens.scopes.get(index, ())
        found = defaultdict(list)  # depth -> the DART functions declared there
        declared_at = set()
        for size in range(len(scope), 0, -1):
            if "::".join(scope[:size] + (name,)) in api.free_functions:
                found[size].append("::".join(scope[:size] + (name,)))
        for short, target, where, start, stop, depth in tokens.using:
            if start < index < stop and scope[: len(where)] == where:
                if short is None:
                    target = qualified_function(
                        target + "::" + name, where, tokens, index, namespace_aliases
                    )
                    found[0] += [target] if target else []
                    continue
                if short != name:
                    continue
                declared_at.add(depth)
                target = qualified_function(
                    target, where, tokens, index, namespace_aliases
                )
                found[depth] += [target] if target else []
        for header in closure.get(path, ()):
            for owner in declared[header].get(name, ()):
                if scope[: len(owner)] == owner:
                    declared_at.add(len(owner))
        depths = declared_at | {depth for depth, items in found.items() if items}
        result = set(found[max(depths, default=0)])
        if any("::".join(scope[:size]) in source_classes for size in declared_at):
            return sorted(result)  # member lookup suppresses ADL
        opening = template_end(tokens.values, index + 1)
        closing = tokens.pairs.get(opening)
        if closing is not None:
            start = i = opening + 1
            while i <= closing:
                if i == closing or tokens.values[i] == ",":
                    types = receiver(
                        tokens, i - 1, imports, namespace_aliases, depth + 1
                    )
                    for offset, _, argument in names_in(tokens.values[start:i]):
                        resolved = resolve(
                            argument, tokens, start + offset, imports, namespace_aliases
                        )
                        if resolved:
                            types.add(resolved)
                    associated = set()
                    for value in types:
                        while prefix := next(
                            (
                                prefix
                                for prefix in (
                                    OPTIONAL,
                                    "__element__:",
                                    CALLABLE,
                                    ASSOCIATED,
                                    *SMART_POINTERS.values(),
                                )
                                if value.startswith(prefix)
                            ),
                            None,
                        ):
                            value = value.removeprefix(prefix)
                        associated.update(api.ancestors(value))
                    for owner in associated:
                        namespace = owner.rpartition("::")[0]
                        while namespace in api.classes:
                            namespace = namespace.rpartition("::")[0]
                        candidate = namespace + "::" + name
                        if candidate in api.free_functions:
                            result.add(candidate)
                    start = i + 1
                elif tokens.values[i] in {"(", "[", "{"} and i in tokens.pairs:
                    i = tokens.pairs[i]
                i += 1
        return sorted(result)

    def scoped_imports(tokens, index, namespace_aliases):
        here = tokens.scopes.get(index, ())
        imports = [
            expand(target.lstrip(":"), namespace_aliases)
            for short, target, where, start, stop, _ in tokens.using
            if short is None and start < index < stop and here[: len(where)] == where
        ]
        if "dart" in imports:
            imports += ["dart::" + space for space in imports if space != "dart"]
        return imports

    def qualified_function(name, scope, tokens, index, namespace_aliases):
        imports = scoped_imports(tokens, index, namespace_aliases)
        for candidate in api.spellings(expand(name, namespace_aliases), scope, imports):
            if candidate in api.free_functions:
                return candidate
        return None

    def export_callable(tokens, index, types):
        opening = tokens.enclosing[index]
        if (
            opening is None
            or opening in tokens.bodies
            and "::".join(tokens.bodies[opening]) not in source_classes
        ) and any(CALLABLE in value for value in types):
            name = "::".join(tokens.scopes.get(index, ()) + (tokens.values[index],))
            namespace_callables[tokens.source_path][name][index] = types

    def source_callable(name, tokens, index, namespace_aliases):
        """Namespace-scope inferred callables visible through scanned headers."""
        path = tokens.source_path
        if path not in closure:
            return None
        scope = tokens.scopes.get(index, ())
        if "::" not in name and any(
            b[3] == name
            and b[0] <= index <= b[1]
            and b[2] <= index
            and set(tokens.branches[b[2]]) <= set(tokens.branches[index])
            for b in tokens.bindings
        ):
            return None
        available = defaultdict(set)
        for header in closure[path]:
            for full_name, declarations in namespace_callables[header].items():
                for declaration, types in declarations.items():
                    if (
                        header != path
                        or declaration <= index
                        and compatible(
                            tokens.branches[declaration], tokens.branches[index]
                        )
                    ):
                        available[full_name].update(types)
        imports = scoped_imports(tokens, index, namespace_aliases)
        if "::" in name:
            return next(
                (
                    available[candidate]
                    for candidate in api.spellings(
                        expand(name, namespace_aliases), scope, imports
                    )
                    if candidate in available
                ),
                None,
            )
        found = defaultdict(set)
        for size in range(len(scope), -1, -1):
            found[size].update(available.get("::".join(scope[:size] + (name,)), ()))
        for short, target, where, start, stop, depth in tokens.using:
            if (
                short in {None, name}
                and start < index < stop
                and scope[: len(where)] == where
            ):
                spelling = expand(
                    target + "::" + name if short is None else target, namespace_aliases
                )
                for candidate in api.spellings(spelling, where, imports):
                    if candidate in available:
                        found[0 if short is None else depth].update(
                            available[candidate]
                        )
                        break
        return next(
            (found[depth] for depth in sorted(found, reverse=True) if found[depth]),
            None,
        )

    def source_function(name, tokens, index, path, namespace_aliases):
        """Visible scanned free functions, retaining their declaration context."""
        if path not in closure:
            return []
        if any(
            b[3] == name
            and b[0] <= index <= b[1]
            and b[2] <= index
            and set(tokens.branches[b[2]]) <= set(tokens.branches[index])
            for b in tokens.bindings
        ):
            return []
        scope = tokens.scopes.get(index, ())
        if "::" not in name:
            for size in range(len(scope), 0, -1):
                owner = "::".join(scope[:size])
                if owner in source_classes and (owner, name) in source_returns:
                    return source_returns[(owner, name)]
        available = defaultdict(list)
        for header in closure[path]:
            for full_name, declarations in source_functions[header].items():
                if full_name.rpartition("::")[0] not in source_classes:
                    available[full_name] += declarations
        imports = scoped_imports(tokens, index, namespace_aliases)
        if "::" in name:
            for candidate in api.spellings(
                expand(name, namespace_aliases), scope, imports
            ):
                if candidate in available:
                    return available[candidate]
            return []
        found = defaultdict(list)
        declared_at = set()
        for header in closure[path]:
            for owner in declared[header].get(name, ()):
                if scope[: len(owner)] == owner:
                    declared_at.add(len(owner))
                    found[len(owner)] += available["::".join(owner + (name,))]
        for short, target, where, start, stop, depth in tokens.using:
            if not (start < index < stop and scope[: len(where)] == where):
                continue
            if short not in {None, name}:
                continue
            spelling = target + "::" + name if short is None else target
            matches = next(
                (
                    available[c]
                    for c in api.spellings(
                        expand(spelling, namespace_aliases), where, imports
                    )
                    if c in available
                ),
                [],
            )
            if short is not None:
                declared_at.add(depth)
            found[0 if short is None else depth] += matches
        depths = declared_at | {depth for depth, items in found.items() if items}
        return found[max(depths, default=0)]

    def reference_alias(name, depth=0):
        if depth > 8 or name not in api.alias_arguments:
            return False
        values, scope = api.alias_arguments[name]
        return raw_reference(values) or any(
            reference_alias(api.resolve(value, scope), depth + 1)
            for start, _, value in names_in(values)
            if not in_template_argument(values, start)
        )

    def declared_expression(tokens, first, last, imports, namespace_aliases, depth=0):
        inferred = expression_receiver(
            tokens, first, last, imports, namespace_aliases, depth
        )
        if (
            inferred
            and tokens.values[first : first + 1] == ["("]
            and tokens.pairs.get(first) == last
        ):
            while (
                tokens.values[first : first + 1] == ["("]
                and tokens.pairs.get(first) == last
            ):
                first, last = first + 1, last - 1
            inner = tokens.values[first : last + 1]
            if inner and (
                all(IDENTIFIER.match(value) or value == "::" for value in inner)
                or IDENTIFIER.match(inner[-1])
                and inner[-2:-1] in (["."], ["->"])
            ):
                inferred.add(REFERENCE)
        return inferred

    def trailing_function_alias(name):
        """The indexed trailing return, before an alias's outer indirection."""
        if name not in api.alias_arguments:
            return None
        values, scope = api.alias_arguments[name]
        tokens = Tokens(" ".join(values))
        trailing = next(
            (
                index
                for index, value in enumerate(values)
                if value == "->"
                and tokens.enclosing[index] is None
                and not in_template_argument(values, index)
            ),
            None,
        )
        if trailing is None:
            return None
        function = function_type_signature(values[:trailing])
        if function is None or "auto" not in function["return_tokens"]:
            return None
        return values[trailing + 1 :], scope

    def product_key(values, scope, context=None, depth=0):
        """Normalize a known element type spelling without deducing a C++ type."""
        if depth > 8:
            return None
        if context and context[0] in closure:
            values = layout_prefix(values, context)
        result, previous = [], 0
        for start, end, name in names_in(values):
            if start < previous:
                continue  # inside an already substituted alias-id
            result.extend(values[previous:start])
            resolved = api.resolve(name, scope)
            if trailing_function_alias(resolved):
                result.append(resolved)
            elif resolved in api.alias_arguments:

                def normalize_actual(actual):
                    key = product_key(actual, scope, context, depth + 1)
                    return TOKEN.findall(key) if key is not None else actual

                argument, where, shadowed, end = api.alias_target(
                    resolved, values, end, normalize_actual
                )
                argument = [
                    (
                        "__template_parameter"
                        if value in shadowed
                        and (not index or argument[index - 1] != "::")
                        else value
                    )
                    for index, value in enumerate(argument)
                ]
                key = product_key(argument, where, depth=depth + 1)
                if key is None:
                    return None
                result.extend(TOKEN.findall(key))
            else:
                if not resolved and context and context[0] in closure:
                    path, tokens, index, imports, renamed = context
                    resolved = source_class(
                        name, tokens.scopes.get(index, ()), imports, renamed, path
                    )
                result.append(resolved or name)
            previous = end
        result.extend(values[previous:])
        normalized, segment = [], []
        for value in result + [","]:
            if value in {"*", "&", "&&", "<", ">", ",", "(", ")", "[", "]"}:
                normalized += (
                    sorted(set(segment) & {"const", "volatile"})
                    + [
                        v
                        for v in segment
                        if v
                        not in {
                            "const",
                            "volatile",
                            "typename",
                            "class",
                            "struct",
                            "enum",
                        }
                    ]
                    + [value]
                )
                segment = []
            else:
                segment.append(value)
        return " ".join(TOKEN.findall(" ".join(normalized[:-1])))

    def product_values(types, selector, kind=None):
        cells = [
            json.loads(value.removeprefix(prefix))
            for value in types
            for name, prefix in PRODUCTS.items()
            if (kind is None or name == kind) and value.startswith(prefix)
        ]
        if isinstance(selector, str):
            return {value for _, key, value in cells if key == selector and value}
        return {value for index, _, value in cells if index == selector and value}

    def callable_return_tokens(values):
        """The declared return of a known function-pointer or std::function type."""
        if alias := trailing_function_alias(qualified(values)):
            return TOKEN.findall(product_key(*alias) or "")
        paired = Tokens(" ".join(values))
        pointer = function_pointer_declarator(values)
        for opening, closing in sorted(paired.pairs.items(), reverse=True):
            returned = (  # `T (*(*)())()` returns the callable `T (*)()`
                values[opening : opening + 2] == ["(", "*"]
                and paired.enclosing[opening] is None
                and values[closing + 1 : closing + 2] == ["("]
                and any(
                    inner < closing
                    and paired.enclosing[inner] == opening
                    and values[inner] == "("
                    and set(values[inner + 1 : paired.pairs[inner]])
                    <= {"*", "&", "&&", "const", "volatile"}
                    and values[paired.pairs[inner] + 1 : paired.pairs[inner] + 2]
                    == ["("]
                    and paired.pairs.get(paired.pairs[inner] + 1) == closing - 1
                    for inner in paired.pairs
                )
            )
            if returned:
                return (
                    values[:opening]
                    + ["(", values[opening + 1], ")"]
                    + values[closing + 1 :]
                )
            if (
                opening < closing
                and values[opening] == "("
                and paired.enclosing[opening] is None
                and not in_template_argument(values, opening)
                and values[opening + 1 : closing]
                and (
                    pointer
                    and pointer["member_pointer"]
                    and pointer["opening"] == opening
                    or values[opening + 1] in {"*", "&", "&&"}
                    and set(values[opening + 1 : closing])
                    <= {"*", "&", "&&", "const", "volatile"}
                )
                and values[closing + 1 : closing + 2] == ["("]
            ):
                parameters_end = paired.pairs.get(closing + 1, closing + 1)
                if "auto" in values[:opening]:
                    for index in range(parameters_end + 1, len(values)):
                        if values[index] == "->" and paired.enclosing[index] is None:
                            return values[index + 1 :]
                return values[:opening]
        function = next(
            (
                end
                for start, end, name in names_in(values)
                if name == "std::function" and not in_template_argument(values, start)
            ),
            None,
        )
        if function is not None:
            signature = first_template_argument(values, function)
            if alias := trailing_function_alias(qualified(signature)):
                return TOKEN.findall(product_key(*alias) or "")
            paired = Tokens(" ".join(signature))
            trailing = next(
                (
                    index
                    for index, value in enumerate(signature)
                    if value == "->"
                    and paired.enclosing[index] is None
                    and not in_template_argument(signature, index)
                ),
                None,
            )
            if trailing is not None and "auto" in signature[:trailing]:
                return signature[trailing + 1 :]
            opening = next(
                (
                    index
                    for index in range(len(signature) - 1, -1, -1)
                    if signature[index] == "("
                    and paired.enclosing[index] is None
                    and not in_template_argument(signature, index)
                ),
                None,
            )
            return signature[:opening] if opening is not None else None
        return None

    def callable_type_shape(values):
        """A known callable's return and any surrounding array indirection."""
        for start, end, name in names_in(values):
            if in_template_argument(values, start):
                continue
            alias = trailing_function_alias(name)
            if alias is None:
                continue
            suffix = template_end(values, end)
            tokens = Tokens(" ".join(values))
            if values[suffix : suffix + 1] in (["*"], ["&"], ["&&"]):
                suffix += 1
            while values[suffix : suffix + 1] in (["const"], ["volatile"]):
                suffix += 1
            dimensions = 0
            while values[suffix : suffix + 1] == ["["] and suffix in tokens.pairs:
                dimensions += 1
                suffix = tokens.pairs[suffix] + 1
            outer = values[suffix:]
            if set(outer) <= {"*", "&", "&&", "const", "volatile"}:
                return (
                    TOKEN.findall(product_key(*alias) or ""),
                    dimensions,
                    "*" in outer,
                    bool({"&", "&&"}.intersection(outer)),
                )
        pointer = function_pointer_declarator(values)
        if pointer is None and (function := function_type_signature(values)):
            tokens = Tokens(" ".join(values))
            suffix = function["parameters_end"] + 1
            if values[suffix : suffix + 1] == ["noexcept"]:
                suffix += 1
                if values[suffix : suffix + 1] == ["("] and suffix in tokens.pairs:
                    suffix = tokens.pairs[suffix] + 1
            if values[suffix : suffix + 1] in (["*"], ["&"], ["&&"]):
                suffix += 1
                while values[suffix : suffix + 1] in (["const"], ["volatile"]):
                    suffix += 1
                dimensions = 0
                while values[suffix : suffix + 1] == ["["] and suffix in tokens.pairs:
                    dimensions += 1
                    suffix = tokens.pairs[suffix] + 1
                outer = values[suffix:]
                if set(outer) <= {"*", "&", "&&", "const", "volatile"}:
                    declared = (
                        function["return_tokens"]
                        + ["(", "*", ")"]
                        + values[function["opening"] : function["parameters_end"] + 1]
                    )
                    result = callable_return_tokens(declared)
                    if result is not None:
                        return (
                            result,
                            dimensions,
                            "*" in outer,
                            bool({"&", "&&"}.intersection(outer)),
                        )
        declared = pointer["return_tokens"] if pointer else values
        result = callable_return_tokens(declared)
        if result is None:
            return None
        return (
            result,
            pointer["array_dimensions"] if pointer else 0,
            pointer["array_pointer"] if pointer else False,
            pointer["array_reference"] if pointer else False,
        )

    def dependent_product_argument(argument, item, scope):
        """Keep indexed template parameters unknown, rather than known foreign."""
        headers = [item.get("signature", "")]
        for size in range(1, len(scope) + 1):
            headers.extend(api.type_templates.get("::".join(scope[:size]), ()))
        parameters = set()
        for header in headers:
            values = TOKEN.findall(header)
            for index, value in enumerate(values):
                if value != "template" or values[index + 1 : index + 2] != ["<"]:
                    continue
                for parameter in template_arguments(values, index + 1):
                    if parameter[:1] in (["class"], ["typename"]):
                        name = next(
                            (v for v in parameter[1:] if IDENTIFIER.match(v)), None
                        )
                        if name:
                            parameters.add(name)
        return any(
            value.split("::", 1)[0] in parameters for _, _, value in names_in(argument)
        )

    def returns(declarations, depth=0):
        """Receiver types of each declaration, plus its own array identity."""
        result = set()
        for item in declarations:
            found = returns_declared([item], depth)
            if not item.get("array_dimensions") and depth <= 8:
                return_tokens = return_type_tokens(item)
                context = item.get("source")
                spelling, _ = (
                    outer_declaration_type(
                        layout_prefix(
                            return_tokens,
                            (
                                context[0],
                                context[1],
                                item["index"],
                                context[2],
                                context[3],
                            ),
                        ),
                        api,
                    )
                    if context and context[0] in closure
                    else outer_declaration_type(
                        return_tokens,
                        api,
                        item.get("declaration_scope")
                        or (
                            tuple(item["class"].split("::"))
                            if item["class"]
                            else tuple(item["name"].split("::")[:-1])
                        ),
                    )
                )
                inferred_declaration = DECLARED_TYPE in found or any(
                    value in {"auto", "decltype"}
                    and not in_template_argument(spelling, index)
                    for index, value in enumerate(spelling)
                )
                identity = array_identity(spelling, api)
                if identity or not inferred_declaration:
                    # Concrete identity wins; otherwise declaration inference
                    # retains the shape of aliases resolved in their own context.
                    found = {t for t in found if not t.startswith(ARRAY_IDENTITY)}
                    if identity:
                        found.add(array_marker(identity))
            result |= found
        return result

    def returns_declared(declarations, depth=0):
        if depth > 8:
            return set()
        result = set()
        for item in declarations:
            if item.get("array_dimensions"):
                inferred = returns([{**item, "array_dimensions": 0}], depth + 1)
                for _ in range(item["array_dimensions"]):
                    inferred = {"__element__:" + value for value in inferred} | {
                        RAW_ARRAY
                    }
                if item.get("array_pointer"):
                    inferred.add(RAW_POINTER)
                if item.get("array_reference"):
                    inferred.add(REFERENCE)
                result.update(inferred)
                continue
            return_tokens = return_type_tokens(item)
            scope = item.get("declaration_scope") or (
                tuple(item["class"].split("::"))
                if item["class"]
                else tuple(item["name"].split("::")[:-1])
            )
            context = item.get("source")
            if context:
                path, tokens, imports, namespace_aliases = context
                index = item["index"]
                return_tokens = return_type_tokens(item)
            if (
                "static" in item
                or item.get("callable_shape")
                or "signature" in item
                and not context
            ):
                key = product_key(
                    return_tokens,
                    scope,
                    (
                        (path, tokens, index, imports, namespace_aliases)
                        if context
                        else None
                    ),
                )
                callable_shape = callable_type_shape(TOKEN.findall(key or ""))
                if callable_shape is not None:
                    callable_return, dimensions, array_pointer, array_reference = (
                        callable_shape
                    )
                    inferred = returns(
                        [
                            {
                                **item,
                                "return_tokens": callable_return,
                                "callable_shape": True,
                            }
                        ],
                        depth + 1,
                    )
                    unknown = (
                        {""}
                        if dependent_product_argument(callable_return, item, scope)
                        else {"__non_dart__"}
                    )
                    inferred = {CALLABLE + value for value in inferred or unknown}
                    if raw_pointer(return_tokens):
                        inferred.add(RAW_POINTER)
                    if raw_reference(return_tokens):
                        inferred.add(REFERENCE)
                    for _ in range(dimensions):
                        inferred = {"__element__:" + value for value in inferred} | {
                            RAW_ARRAY
                        }
                    if array_pointer:
                        inferred.add(RAW_POINTER)
                    if array_reference:
                        inferred.add(REFERENCE)
                    result.update(inferred)
                    result.add(NO_INLINE_LAYOUT)
                    continue
            if raw_reference(return_tokens) and not item.get("reference_shape"):
                inferred = returns([{**item, "reference_shape": True}], depth)
                result.update(inferred)
                if inferred:
                    result.add(REFERENCE)
                continue
            if context:
                if "auto" in return_tokens:
                    body = item.get("body")
                    opening = item.get("name_index", -1) + len(
                        TOKEN.findall(item["name"].split("::")[-1])
                    )
                    closing = tokens.pairs.get(opening)
                    trailing = False
                    if closing is not None and body is not None:
                        suffix = closing + 1
                        while suffix < body:
                            if (
                                tokens.values[suffix] in {"(", "["}
                                and suffix in tokens.pairs
                            ):
                                suffix = tokens.pairs[suffix] + 1
                                continue
                            trailing |= tokens.values[suffix] == "->"
                            suffix += 1
                    if not trailing:
                        for first, last in return_expressions(tokens, item):
                            inferred = declared_expression(
                                tokens,
                                first,
                                last,
                                imports,
                                namespace_aliases,
                                depth,
                            )
                            if "decltype" not in return_tokens and not raw_reference(
                                return_tokens
                            ):
                                inferred.discard(REFERENCE)
                            result.update(inferred)
                    continue
                decltype = next(
                    (
                        start
                        for start, value in enumerate(return_tokens)
                        if value == "decltype"
                        and not in_template_argument(return_tokens, start)
                    ),
                    None,
                )
                if decltype is not None:
                    declaration_tokens = Tokens(" ".join(return_tokens))
                    closing = declaration_tokens.pairs.get(decltype + 1)
                    if closing is not None:
                        expression = return_tokens[decltype : closing + 1]
                        locations = [
                            start
                            for start, value in enumerate(tokens.values)
                            if value == "decltype"
                            and tokens.values[start : start + len(expression)]
                            == expression
                        ]
                        if locations:
                            first = min(locations, key=lambda start: abs(start - index))
                            last = tokens.pairs[first + 1]
                            inferred = declared_expression(
                                tokens,
                                first + 2,
                                last - 1,
                                imports,
                                namespace_aliases,
                                depth,
                            )
                            if inferred:
                                # Explicit outer declarators augment decltype's
                                # inferred type once, at this declaration step.
                                pointers = sum(
                                    value == "*"
                                    and declaration_tokens.enclosing[offset] is None
                                    and not in_template_argument(return_tokens, offset)
                                    for offset, value in enumerate(return_tokens)
                                )
                                result.update(shift_array_depth(inferred, pointers))
                                result.add(DECLARED_TYPE)
                                if raw_pointer(return_tokens):
                                    result.add(RAW_POINTER)
                    continue
                resolve_return = lambda value: resolve(
                    value, tokens, index, imports, namespace_aliases
                )
                pointer_return = lambda value: pointer_alias(
                    value, tokens, index, imports, namespace_aliases
                )
                alias = None
                for start, end, value in names_in(return_tokens):
                    if in_template_argument(return_tokens, start):
                        continue
                    for candidate in api.spellings(
                        expand(value, namespace_aliases),
                        tokens.scopes.get(index, ()),
                        imports,
                    ):
                        alias = next(
                            (
                                alias_declarations[header][candidate]
                                for header in closure.get(path, ())
                                if candidate in alias_declarations[header]
                            ),
                            None,
                        )
                        if alias:
                            break
                    if alias:
                        break
                if alias:
                    values, alias_index, alias_context = alias
                    values = (
                        return_tokens[:start]
                        + values
                        + return_tokens[template_end(return_tokens, end) :]
                    )
                    inferred = returns(
                        [
                            {
                                **item,
                                "return_tokens": values,
                                "index": alias_index,
                                "source": alias_context,
                            }
                        ],
                        depth + 1,
                    )
                    result.update(inferred)
                    if inferred and raw_pointer(return_tokens):
                        result.add(RAW_POINTER)
                    continue
            else:
                resolve_return = lambda value: api.resolve(value, scope)
                pointer_return = (
                    lambda value: resolve_return(value)
                    in api.raw_pointers | api.standard_pointers
                )
                if any(
                    value == "decltype"
                    and not in_template_argument(return_tokens, start)
                    for start, value in enumerate(return_tokens)
                ):
                    declaration = Tokens(" ".join(return_tokens))
                    declaration.source_path = None
                    declaration.scopes = {
                        index: scope for index in range(len(declaration.values))
                    }
                    declaration.branches = [()] * len(declaration.values)
                    result.update(
                        returns(
                            [
                                {
                                    **item,
                                    "index": 0,
                                    "source": (None, declaration, [], {}),
                                }
                            ],
                            depth + 1,
                        )
                    )
                    continue
            alias = next(
                (
                    resolve_return(value)
                    for start, _, value in names_in(return_tokens)
                    if not in_template_argument(return_tokens, start)
                    and (
                        expression_alias(api, resolve_return(value))
                        or api.alias_parameters.get(resolve_return(value))
                    )
                ),
                None,
            )
            if alias:
                prefix = (
                    layout_prefix(
                        return_tokens, (path, tokens, index, imports, namespace_aliases)
                    )
                    if context and path in closure
                    else return_tokens
                )
                values, where = outer_declaration_type(prefix, api, scope)
                expanded = {**item, "return_tokens": values, "declaration_scope": where}
                expanded.pop("source", None)
                inferred = returns([expanded], depth + 1)
                result.update(inferred)
                if inferred and raw_pointer(return_tokens):
                    result.add(RAW_POINTER)
                continue
            standard_type = lambda value: (
                standard_name(value, tokens, index, namespace_aliases)
                if context
                else value.lstrip(":")
            )
            alias = next(
                (
                    resolve_return(value)
                    for start, _, value in names_in(return_tokens)
                    if not in_template_argument(return_tokens, start)
                    and element_alias(
                        api,
                        resolve_return(value),
                        containers=ELEMENT_CONTAINERS
                        | MAP_CONTAINERS
                        | PRODUCTS.keys(),
                    )
                ),
                None,
            )
            if alias:
                argument, where = api.alias_arguments[alias]
                element = {
                    **item,
                    "return_tokens": argument,
                    "declaration_scope": where,
                    "layout_shape": False,
                    "reference_shape": False,
                }
                element.pop("source", None)
                result.update(returns([element], depth + 1))
                if raw_pointer(return_tokens) or alias in api.raw_pointers:
                    result.add(RAW_POINTER)
                continue

            def inline_wrapper(values, where, depth=0):
                if depth > 8:
                    return False
                for start, _, value in names_in(values):
                    if in_template_argument(values, start):
                        continue
                    if standard_type(value) in {
                        "std::array",
                        "std::tuple",
                        "std::pair",
                        "std::optional",
                        "std::variant",
                    }:
                        return True
                    name = api.resolve(value, where) or resolve_return(value)
                    if name in api.alias_arguments:
                        argument, alias_scope = api.alias_arguments[name]
                        if inline_wrapper(argument, alias_scope, depth + 1):
                            return True
                return False

            if not item.get("layout_shape") and inline_wrapper(return_tokens, scope):
                prefix = (
                    layout_prefix(
                        return_tokens, (path, tokens, index, imports, namespace_aliases)
                    )
                    if context and path in closure
                    else return_tokens
                )
                owners = api.layout_owners(prefix, scope, references=True)
                result.update(returns([{**item, "layout_shape": True}], depth))
                result.update(
                    {INLINE_LAYOUT + owner for owner in owners} or {NO_INLINE_LAYOUT}
                )
                continue
            product = next(
                (
                    (end, standard_type(value))
                    for start, end, value in names_in(return_tokens)
                    if standard_type(value) in PRODUCTS
                    and not in_template_argument(return_tokens, start)
                ),
                None,
            )
            if product:
                end, kind = product
                key_context = (
                    (path, tokens, index, imports, namespace_aliases)
                    if context
                    else None
                )
                for position, argument in enumerate(
                    template_arguments(return_tokens, end)
                ):
                    unknown = (
                        {""}
                        if context or dependent_product_argument(argument, item, scope)
                        else {"__non_dart__"}
                    )
                    key = product_key(argument, scope, key_context)
                    declared = TOKEN.findall(key) if key is not None else argument
                    callable_return = callable_return_tokens(declared)
                    inferred = returns(
                        [
                            {
                                **item,
                                "return_tokens": (
                                    callable_return
                                    if callable_return is not None
                                    else argument
                                ),
                                "layout_shape": False,
                                "reference_shape": False,
                            }
                        ],
                        depth + 1,
                    )
                    if callable_return is not None:
                        inferred = {CALLABLE + value for value in inferred or unknown}
                    result.update(
                        PRODUCTS[kind]
                        + json.dumps([position, key, value], separators=(",", ":"))
                        for value in inferred or unknown
                    )
                    result.update(ASSOCIATED + value for value in inferred)
                if raw_pointer(return_tokens):
                    result.add(RAW_POINTER)
                continue
            mapping = next(
                (
                    (end, standard_type(value))
                    for start, end, value in names_in(return_tokens)
                    if standard_type(value) in MAP_CONTAINERS
                    and not in_template_argument(return_tokens, start)
                ),
                None,
            )
            if mapping is not None:
                arguments = template_arguments(return_tokens, mapping[0])
                if len(arguments) >= 2:
                    pair = (
                        ["std", "::", "pair", "<"]
                        + arguments[0]
                        + ["const", ","]
                        + arguments[1]
                        + [">"]
                    )
                    inferred = returns(
                        [
                            {
                                **item,
                                "return_tokens": pair,
                                "layout_shape": False,
                                "reference_shape": False,
                            }
                        ],
                        depth + 1,
                    )
                    result.update("__element__:" + value for value in inferred)
                    result.add(MAPPING)
                    if mapping[1] in {"std::multimap", "std::unordered_multimap"}:
                        result.add(MULTIMAPPING)
                    result.add(NO_INLINE_LAYOUT)
                    if raw_pointer(return_tokens):
                        result.add(RAW_POINTER)
                continue
            optional = next(
                (
                    end
                    for start, end, value in names_in(return_tokens)
                    if standard_type(value) == "std::optional"
                    and not in_template_argument(return_tokens, start)
                ),
                None,
            )
            alias = next(
                (
                    resolve_return(value)
                    for start, _, value in names_in(return_tokens)
                    if not in_template_argument(return_tokens, start)
                    and resolve_return(value) in api.optional_arguments
                ),
                None,
            )
            if optional is not None or alias:
                argument, where = (
                    (first_template_argument(return_tokens, optional), scope)
                    if optional is not None
                    else api.optional_arguments[alias]
                )
                element = {
                    **item,
                    "return_tokens": argument,
                    "declaration_scope": where,
                    "layout_shape": False,
                    "reference_shape": False,
                }
                if optional is None:
                    element.pop("source", None)
                inferred = returns([element], depth + 1)
                result.update(OPTIONAL + value for value in inferred or {""})
                # The flattened owned names lose a variant's alternative order, so
                # keep the declared element for emplacement analysis.
                result.add(
                    OPTIONAL_ELEMENT
                    + " ".join(
                        construction_aliases(
                            # A source declaration's aliases live in its own file.
                            layout_prefix(
                                argument,
                                (path, tokens, index, imports, namespace_aliases),
                            ),
                            api,
                        )
                        if context and optional is not None
                        else construction_aliases(argument, api, where)
                    )
                )
                if raw_pointer(return_tokens) or alias in api.raw_pointers:
                    result.add(RAW_POINTER)
                continue
            pointer = next(
                (
                    (end, standard_type(value))
                    for start, end, value in names_in(return_tokens)
                    if standard_type(value) in SMART_POINTERS
                    and not in_template_argument(return_tokens, start)
                ),
                None,
            )
            smart_alias = next(
                (
                    resolve_return(value)
                    for start, _, value in names_in(return_tokens)
                    if not in_template_argument(return_tokens, start)
                    and resolve_return(value) in api.smart_arguments
                ),
                None,
            )
            if pointer or smart_alias:
                kind, argument, where = (
                    (
                        pointer[1],
                        first_template_argument(return_tokens, pointer[0]),
                        scope,
                    )
                    if pointer
                    else api.smart_arguments[smart_alias]
                )
                pointee = {
                    **item,
                    "return_tokens": argument,
                    "declaration_scope": where,
                    "layout_shape": False,
                    "reference_shape": False,
                }
                if not pointer:
                    pointee.pop("source", None)
                inferred = returns([pointee], depth + 1)
                if any(
                    value == "[" and not in_template_argument(argument, start)
                    for start, value in enumerate(argument)
                ):
                    inferred.add(RAW_ARRAY)
                result.update(
                    SMART_POINTERS[kind] + value for value in inferred or {""}
                )
                if raw_pointer(return_tokens) or smart_alias in api.raw_pointers:
                    result.add(RAW_POINTER)
                continue
            sequence = next(
                (
                    end
                    for start, end, value in names_in(return_tokens)
                    if standard_type(value) in ELEMENT_CONTAINERS
                    and not in_template_argument(return_tokens, start)
                ),
                None,
            )
            if sequence is not None:
                argument = first_template_argument(return_tokens, sequence)
                inferred = returns(
                    [
                        {
                            **item,
                            "return_tokens": argument,
                            "layout_shape": False,
                            "reference_shape": False,
                        }
                    ],
                    depth + 1,
                )
                if any(
                    OPTIONAL in value
                    or value.startswith("__element__:")
                    or value.startswith(SOURCE_CLASS)
                    or any(prefix in value for prefix in PRODUCTS.values())
                    or CALLABLE in value
                    or INLINE_LAYOUT in value
                    or NO_INLINE_LAYOUT in value
                    or any(prefix in value for prefix in SMART_POINTERS.values())
                    for value in inferred
                ):
                    result.update("__element__:" + value for value in inferred)
                    continue
                contained = container_elements(
                    argument,
                    api,
                    resolve_return,
                    pointer_return,
                )
                if not contained and context:
                    foreign = returns([{**item, "return_tokens": argument}], depth + 1)
                    contained = {"__non_dart__"} if "__non_dart__" in foreign else set()
                result.update(contained if context else contained or {"__non_dart__"})
                continue
            for start, _, value in names_in(return_tokens):
                resolved = resolve_return(value)
                owner = api.owner(resolved)
                if owner:
                    result.add(resolved)
                    if reference_alias(resolved):
                        result.add(REFERENCE)
                    if (
                        raw_pointer(return_tokens)
                        or pointer_return(value)
                        or any(
                            target
                            in {"std::shared_ptr", "std::unique_ptr", "std::weak_ptr"}
                            and not in_template_argument(return_tokens, start)
                            for start, _, target in names_in(return_tokens)
                        )
                    ):
                        result.add(RAW_POINTER)
                elif context and not in_template_argument(return_tokens, start):
                    source_owner = source_class(
                        value,
                        tokens.scopes.get(index, ()),
                        imports,
                        namespace_aliases,
                        tokens.source_path,
                    )
                    if source_owner:
                        result.update(
                            local_bases.get(source_owner, ()) or {"__non_dart__"}
                        )
                        result.add(SOURCE_CLASS + source_owner)
                        if raw_pointer(return_tokens):
                            result.add(RAW_POINTER)
                    elif value in {
                        "void",
                        "int",
                        "double",
                        "float",
                        "bool",
                        "char",
                        "size_t",
                    } or THIRD_PARTY.match(value):
                        result.add("__non_dart__")
                elif value in {
                    "void",
                    "int",
                    "double",
                    "float",
                    "bool",
                    "char",
                    "size_t",
                } or THIRD_PARTY.match(value):
                    result.add("__non_dart__")
        return result

    def namespace_variable(tokens, index, namespace_aliases):
        """A visible DART namespace variable, excluding lexical local shadows."""
        values = tokens.values
        name = values[index]
        if not IDENTIFIER.match(name) or index and values[index - 1] in {".", "->"}:
            return None
        qualifier = (
            "::".join(qualifier_path(values, index))
            if index and values[index - 1] == "::"
            else None
        )
        if qualifier is None and any(
            b[3] == name
            and b[0] <= index <= b[1]
            and b[2] <= index
            and set(tokens.branches[b[2]]) <= set(tokens.branches[index])
            for b in tokens.bindings
        ):
            return None
        scope = tokens.scopes.get(index, ())
        imports = scoped_imports(tokens, index, namespace_aliases)
        if qualifier is not None:
            for candidate in api.spellings(
                expand(qualifier + "::" + name, namespace_aliases), scope, imports
            ):
                if candidate in api.variables:
                    return candidate
            return None
        found = defaultdict(list)
        declared_at = set()
        for size in range(len(scope), -1, -1):
            candidate = "::".join(scope[:size] + (name,))
            if candidate in api.variables:
                found[size].append(candidate)
        for candidate in api.spellings(name, (), imports):
            if candidate in api.variables:
                found[0].append(candidate)
        for short, target, where, start, stop, depth in tokens.using:
            if short == name and start < index < stop and scope[: len(where)] == where:
                declared_at.add(depth)
                found[depth] += [
                    candidate
                    for candidate in api.spellings(
                        expand(target, namespace_aliases), where, imports
                    )
                    if candidate in api.variables
                ][:1]
        depths = declared_at | {depth for depth, items in found.items() if items}
        return next(iter(found[max(depths, default=0)]), None)

    def member_declarations(owner, name, table, seen=frozenset()):
        """Indexed members after nearest-name hiding and class using declarations."""
        spelling = owner
        owner = api.owner(owner)
        if owner is None or owner in seen:
            return []
        cls = api.classes[owner]
        fields = [item for item in cls["fields"] if item["name"] == name]
        targets = cls.get("using", {}).get(name, ())
        if (
            fields
            or any(item["name"] == name for item in cls["methods"])
            or owner + "::" + name in api.types
            or targets
        ):
            # An own declaration hides the inherited name; retain the indexed-data boundary.
            result = [item for item in table.get(name, ()) if item["class"] == owner]
            for target in targets:
                where = target.rpartition("::")[0]
                base = api.resolve(base_name(where), tuple(owner.split("::")))
                result.extend(member_declarations(base, name, table, seen | {owner}))
            return result
        return [
            item
            for base in [
                *cls["bases"],
                *sorted(api.ancestors(spelling) - api.ancestors(owner)),
            ]
            for item in member_declarations(base, name, table, seen | {owner})
        ]

    def qualified_members(tokens, index, imports, namespace_aliases, table):
        if not index or tokens.values[index - 1] != "::":
            return []
        qualifier = "::".join(qualifier_path(tokens.values, index))
        owner = resolve(qualifier, tokens, index, imports, namespace_aliases)
        return member_declarations(owner, tokens.values[index], table)

    def object_members(
        types, name, tokens, index, imports, namespace_aliases, table, operator=None
    ):
        types = source_member_types(
            types, name, tokens, index, imports, namespace_aliases
        )
        if table is api.members and name not in api.data_members:
            return candidates(name, types, operator, table)
        types = types - (api.standard_pointers if operator == "." else set())
        owners = {api.owner(value) for value in types} - {None}
        if operator != "." or name not in {"get", "lock"}:
            for value in types:
                owners.update(api.ancestors(value) - api.ancestors(api.owner(value)))
        if any(value.startswith(SOURCE_CLASS) for value in types):
            owners = {
                owner
                for owner in owners
                if not any(
                    owner != other and owner in api.ancestors(other) for other in owners
                )
            }
        return [
            item for owner in owners for item in member_declarations(owner, name, table)
        ]

    def object_data(
        types, name, tokens, index, imports, namespace_aliases, operator=None
    ):
        return object_members(
            types,
            name,
            tokens,
            index,
            imports,
            namespace_aliases,
            api.data_members,
            operator,
        )

    def field_declarations(
        types, name, tokens, index, imports, namespace_aliases, operator
    ):
        """Field reads respect nearest-name hiding once the receiver is known."""
        if any(api.owner(value) or value.startswith(SOURCE_CLASS) for value in types):
            return object_data(
                types, name, tokens, index, imports, namespace_aliases, operator
            )
        return candidates(name, types, operator if types else None, api.data_members)

    def lexical_members(tokens, index, imports, namespace_aliases, table):
        name = tokens.values[index]
        if any(
            b[3] == name
            and b[0] <= index <= b[1]
            and b[2] <= index
            and set(tokens.branches[b[2]]) <= set(tokens.branches[index])
            for b in tokens.bindings
        ):
            return [], set()
        scope = tokens.scopes.get(index, ())
        owners = enclosing_bases(tokens, index)
        for size in range(len(scope), 0, -1):
            owner = "::".join(scope[:size])
            if owner in source_classes:
                owners = source_member_bases(
                    owner, name, tokens, index, imports, namespace_aliases
                )
                break
            if owner in api.classes:
                owners = {owner}
                break
        types = set(owners)
        if scope and owner in source_classes:
            types.add(SOURCE_CLASS + owner)
        if not types:
            return [], owners
        return (
            object_members(
                types, name, tokens, index, imports, namespace_aliases, table
            ),
            owners,
        )

    def lexical_data(tokens, index, imports, namespace_aliases):
        return lexical_members(
            tokens, index, imports, namespace_aliases, api.data_members
        )

    def callable_field(tokens, index, imports, namespace_aliases, depth=0):
        name = tokens.values[index]
        if name not in api.data_members:
            return [], set()
        access = tokens.values[index - 1] if index else None
        if access in {".", "->"}:
            inferred = receiver(
                tokens, index - 2, imports, namespace_aliases, depth + 1
            )
            if access == "->":
                inferred = arrow_types(inferred)
            return (
                object_data(
                    inferred, name, tokens, index, imports, namespace_aliases, access
                ),
                inferred,
            )
        if access == "::":
            qualifier = "::".join(qualifier_path(tokens.values, index))
            return qualified_data(tokens, index, imports, namespace_aliases), {
                resolve(qualifier, tokens, index, imports, namespace_aliases)
            }
        return lexical_data(tokens, index, imports, namespace_aliases)

    def source_field_result(types, name, depth):
        """Own source fields hide bases without expanding explicit DART callbacks."""
        declarations = []
        for marker in types:
            if not marker.startswith(SOURCE_CLASS):
                continue
            owner = marker.removeprefix(SOURCE_CLASS)
            for candidate in [owner, *ancestry.get(owner, ())]:
                if (candidate, name) in source_returns:
                    break
                if name in source_fields[candidate]:
                    declarations.extend(source_fields[candidate][name])
                    break
        if not declarations:
            return None
        result = set()
        for item in declarations:
            if "foreign_callable" in item:
                if item["foreign_callable"]:
                    result.add("__non_dart__")
                continue
            declared = {key: value for key, value in item.items() if key != "static"}
            context = item["source"]
            key = product_key(
                item["return_tokens"],
                tuple(item["class"].split("::")),
                (context[0], context[1], item["index"], context[2], context[3]),
            )
            callable_return = callable_return_tokens(TOKEN.findall(key or ""))
            if callable_return is not None:
                shape = returns(
                    [{**declared, "return_tokens": callable_return}], depth + 1
                )
                if shape and not any(value.startswith("dart::") for value in shape):
                    result.add("__non_dart__")
            else:
                shape = returns([declared], depth + 1)
                invoked = returns(candidates("operator()", shape), depth + 1)
                result.update(
                    invoked or ({"__non_dart__"} if "__non_dart__" in shape else set())
                )
        return result

    def qualified_data(tokens, index, imports, namespace_aliases):
        return qualified_members(
            tokens, index, imports, namespace_aliases, api.data_members
        )

    def callable_data_result(declarations, depth):
        types = returns(declarations, depth + 1)
        if any(value.startswith(CALLABLE) for value in types):
            return {
                value.removeprefix(CALLABLE)
                for value in types
                if value.startswith(CALLABLE) and value != CALLABLE
            }
        result = returns(candidates("operator()", types), depth + 1) if types else set()
        if result or types:
            return result or {"__non_dart__"}
        return (
            set()
            if any(
                dependent_product_argument(
                    item["return_tokens"], item, tuple(item["class"].split("::"))
                )
                for item in declarations
            )
            else {"__non_dart__"}
        )

    def source_accessor_result(types, name, depth):
        declarations = []
        for marker in types:
            if not marker.startswith(SOURCE_CLASS):
                continue
            owner = marker.removeprefix(SOURCE_CLASS)
            for candidate in [owner, *ancestry.get(owner, ())]:
                found = source_returns.get((candidate, name), ())
                if found:
                    declarations.extend(found)
                    break
        if not declarations:
            return None
        inferred = returns(declarations, depth + 1)
        if inferred or name not in {"at", "operator[]"}:
            return inferred
        # A generic source accessor keeps its existing element evidence. Same-name
        # fields of unrelated map owners do not turn that accessor into a map.
        inferred = {
            value
            for value in elements(types)
            if value != NO_INLINE_LAYOUT
            and not value.startswith(INLINE_LAYOUT)
            and not any(value.startswith(prefix) for prefix in PRODUCTS.values())
        }
        return inferred | {REFERENCE} if inferred else inferred

    def arrow_types(types):
        if ITERATOR in types:
            values = elements(types)
            # Iterator arrow addresses the element, not a pointer element's pointee.
            return {"__non_dart__"} if RAW_POINTER in values else values | {RAW_POINTER}
        if RAW_ARRAY in types:
            return elements(types) | {RAW_POINTER}
        if smart_kind(types):
            if RAW_POINTER in types:
                return types - {RAW_POINTER}
            other = {
                value
                for value in types
                if not any(
                    value.startswith(prefix) for prefix in SMART_POINTERS.values()
                )
            }
            if other:
                return arrow_types(other) | arrow_types(types - other)
            if not smart_kind(types, ("std::shared_ptr", "std::unique_ptr")):
                return {"__non_dart__"}
            values = smart_values(types, ("std::shared_ptr", "std::unique_ptr"))
            if RAW_ARRAY in values:
                return {"__non_dart__"}
            return values | {RAW_POINTER} if values else set()
        if (
            any(value.startswith(OPTIONAL) for value in types)
            and RAW_POINTER not in types
        ):
            values = optional_values(types)
            return values | {RAW_POINTER} if values else set()
        return returns(candidates("operator->", types)) or types

    def optional_values(types):
        return {
            value.removeprefix(OPTIONAL)
            for value in types
            if value.startswith(OPTIONAL) and value != OPTIONAL
        }

    def smart_kind(types, kinds=SMART_POINTERS):
        return any(
            value.startswith(SMART_POINTERS[kind]) for value in types for kind in kinds
        )

    def smart_values(types, kinds=SMART_POINTERS):
        return {
            value.removeprefix(SMART_POINTERS[kind])
            for value in types
            for kind in kinds
            if value.startswith(SMART_POINTERS[kind]) and value != SMART_POINTERS[kind]
        }

    def unary_address(types):
        return [
            item
            for item in candidates("operator&", types)
            if (
                signature := member_signature(
                    item,
                    lambda value: api.resolve(value, tuple(item["class"].split("::"))),
                )
            )
            is not None
            and not signature[0]
        ]

    def expression_receiver(tokens, start, end, imports, namespace_aliases, depth=0):
        if start > end or depth > 8:
            return set()
        question, nesting = None, 0
        index = start
        while index <= end:
            value = tokens.values[index]
            if value in {"(", "[", "{"} and index in tokens.pairs:
                index = tokens.pairs[index] + 1
                continue
            if value == "?":
                if question is None:
                    question = index
                nesting += 1
            elif value == ":" and question is not None:
                nesting -= 1
                if nesting == 0:
                    # Keep both candidates without attempting common-type conversions.
                    arms = [
                        expression_receiver(
                            tokens, first, last, imports, namespace_aliases, depth + 1
                        )
                        for first, last in ((question + 1, index - 1), (index + 1, end))
                    ]
                    identities = [
                        {t for t in arm if t.startswith(ARRAY_IDENTITY)} for arm in arms
                    ]
                    union = arms[0] | arms[1]
                    if identities[0] != identities[1]:
                        # One arm proves no whole-array identity for the result.
                        union = {t for t in union if not t.startswith(ARRAY_IDENTITY)}
                    return union
            index += 1
        types = receiver(tokens, end, imports, namespace_aliases, depth + 1)
        if tokens.values[start : start + 1] == ["&"] and types:
            overloaded = returns(unary_address(types), depth + 1)
            return overloaded or (
                shift_array_depth(types - {REFERENCE}, 1) | {RAW_POINTER}
            )
        while tokens.values[start : start + 1] == ["*"]:
            if ITERATOR in types or RAW_ARRAY in types:
                types = elements(types)
            elif any(
                t.startswith(ARRAY_IDENTITY) and parse_array_marker_key(t)[1] > 0
                for t in types
            ):
                types = shift_array_depth(types - {RAW_POINTER}, -1)
            elif RAW_POINTER in types:
                types = types - {RAW_POINTER}
            elif smart_kind(types):
                types = (
                    smart_values(types, ("std::shared_ptr", "std::unique_ptr"))
                    if smart_kind(types, ("std::shared_ptr", "std::unique_ptr"))
                    else {"__non_dart__"}
                )
                if RAW_ARRAY in types:
                    types = {"__non_dart__"}
            elif any(value.startswith(OPTIONAL) for value in types):
                types = optional_values(types)
            if types and "__non_dart__" not in types:
                types.add(REFERENCE)
            start += 1
        return types

    def standard_forwarder(name, tokens, index, namespace_aliases):
        if "::" not in name and any(
            binding[3] == name
            and binding[0] <= index <= binding[1]
            and binding[2] <= index
            and set(tokens.branches[binding[2]]) <= set(tokens.branches[index])
            for binding in tokens.bindings
        ):
            return False
        return standard_name(name, tokens, index, namespace_aliases) in {
            "std::move",
            "std::forward",
            "std::as_const",
        }

    def receiver(tokens, before, imports, namespace_aliases, depth=0):
        if before < 0 or depth > 8:
            return set()
        values = tokens.values
        value = values[before]
        if value == "this":
            scope = tokens.scopes.get(before, ())
            for size in range(len(scope), 0, -1):
                owner = "::".join(scope[:size])
                if owner in source_classes:
                    return set(local_bases.get(owner, ())) | {
                        SOURCE_CLASS + owner,
                        RAW_POINTER,
                    }
                if owner in api.classes:
                    return {owner, RAW_POINTER}
        if value == ")" and before in tokens.pairs:
            opening = tokens.pairs[before]
            if (
                opening == before - 1
                and values[opening - 1 : opening] in (["->"], ["*"])
                and values[opening - 2 : opening - 1] == ["operator"]
                and values[opening - 3 : opening - 2] in (["."], ["->"])
            ):
                # Explicit iterator operator->() / operator*() project like the
                # built-in spellings; any other receiver keeps the generic path.
                types = receiver(
                    tokens, opening - 4, imports, namespace_aliases, depth + 1
                )
                if ITERATOR in types:
                    if values[opening - 1] == "->":
                        return arrow_types(types)
                    return elements(types) | {REFERENCE}
            function = opening - 1
            if function >= 0 and values[function] == ">":
                angle = 1
                function -= 1
                while function >= 0 and angle:
                    if values[function] in {")", "]"} and function in tokens.pairs:
                        function = tokens.pairs[function] - 1
                        continue
                    angle += (values[function] == ">") - (values[function] == "<")
                    function -= 1
            if function < 0 or not (
                IDENTIFIER.match(values[function])
                and values[function]
                not in {
                    "return",
                    "co_return",
                    "throw",
                    "if",
                    "while",
                    "for",
                    "switch",
                    "sizeof",
                    "alignof",
                    "decltype",
                    "noexcept",
                }
                or values[function] in {")", "]", "}"}
            ):
                cast = opening + 1
                if values[cast : cast + 1] == ["("] and cast in tokens.pairs:
                    closing = tokens.pairs[cast]
                    target = values[cast + 1 : closing]
                    expression = (
                        all(
                            IDENTIFIER.match(token) or token == "::" for token in target
                        )
                        and {
                            "const",
                            "volatile",
                            "struct",
                            "class",
                            "typename",
                        }.isdisjoint(target)
                        and (
                            variable_types(tokens, closing - 1, fields)
                            or any(
                                b[3] == values[closing - 1]
                                and b[0] <= cast <= b[1]
                                and b[2] <= cast
                                and compatible(
                                    tokens.branches[b[2]], tokens.branches[cast]
                                )
                                for b in tokens.bindings
                            )
                        )
                    )
                    if (
                        closing < before - 1
                        and values[closing + 1] not in {"->", ".", "["}
                        and target
                        and not expression
                        and not any(
                            token in {"(", ")", ".", "->", "=", "+", "-", "/", "%", "!"}
                            for token in target
                        )
                    ):
                        return returns(
                            [
                                {
                                    "class": None,
                                    "name": "",
                                    "return_tokens": target,
                                    "index": cast,
                                    "source": (
                                        tokens.source_path,
                                        tokens,
                                        imports,
                                        namespace_aliases,
                                    ),
                                }
                            ]
                        )
                return expression_receiver(
                    tokens, opening + 1, before - 1, imports, namespace_aliases, depth
                )
            if function >= 0:
                method = values[function]
                data, _ = callable_field(
                    tokens, function, imports, namespace_aliases, depth
                )
                if data:
                    return callable_data_result(data, depth)
                if function > 0 and values[function - 1] in {"->", "."}:
                    types = receiver(
                        tokens, function - 2, imports, namespace_aliases, depth + 1
                    )
                    if values[function - 1] == "->":
                        types = arrow_types(types)
                    source_result = source_field_result(types, method, depth)
                    if source_result is not None and not object_members(
                        types,
                        method,
                        tokens,
                        function,
                        imports,
                        namespace_aliases,
                        api.members,
                        values[function - 1],
                    ):
                        return source_result
                    if method in PAIR_MEMBERS and any(
                        marker.startswith(PRODUCTS["std::pair"]) for marker in types
                    ):
                        projected = product_values(
                            types, int(method == "second"), "std::pair"
                        )
                        if any(value.startswith(CALLABLE) for value in projected):
                            return {
                                value.removeprefix(CALLABLE)
                                for value in projected
                                if value.startswith(CALLABLE) and value != CALLABLE
                            }
                        return returns(candidates("operator()", projected), depth + 1)
                    if method in {
                        "at",
                        "find",
                        "lower_bound",
                        "upper_bound",
                        "equal_range",
                    }:
                        source_result = source_accessor_result(types, method, depth)
                        if source_result is not None:
                            return source_result
                    if method == "get" and smart_kind(types):
                        if not smart_kind(
                            types, ("std::shared_ptr", "std::unique_ptr")
                        ):
                            return {"__non_dart__"}
                        pointees = smart_values(
                            types, ("std::shared_ptr", "std::unique_ptr")
                        ) - {RAW_ARRAY}
                        return pointees | {RAW_POINTER} if pointees else set()
                    if method == "lock" and smart_kind(types, ("std::weak_ptr",)):
                        return {
                            SMART_POINTERS["std::shared_ptr"] + value
                            for value in smart_values(types, ("std::weak_ptr",)) or {""}
                        }
                    if method == "get" and types & api.standard_pointers:
                        return {api.owner(t) for t in types if api.owner(t)} | {
                            RAW_POINTER
                        }
                    if method in {"value", "value_or"} and any(
                        value.startswith(OPTIONAL) for value in types
                    ):
                        result = optional_values(types)
                        return (
                            result | {REFERENCE}
                            if method == "value" and result
                            else result
                        )
                    if method == "at" and MAPPING in types:
                        inferred = product_values(elements(types), 1, "std::pair")
                        return inferred | {REFERENCE} if inferred else inferred
                    if method in {"at", "back", "front"} and elements(types):
                        return elements(types) | {REFERENCE}
                    erase_end = tokens.pairs.get(function + 1, function + 1)
                    if (
                        MAPPING in types
                        and method == "erase"
                        and erase_end > function + 2
                        and (
                            any(
                                values[index] == ","
                                and tokens.enclosing[index] == function + 1
                                and not in_template_argument(values, index)
                                for index in range(function + 2, erase_end)
                            )
                            or ITERATOR
                            in expression_receiver(
                                tokens,
                                function + 2,
                                erase_end - 1,
                                imports,
                                namespace_aliases,
                                depth + 1,
                            )
                        )
                    ):
                        # Only the iterator overloads of erase return an iterator.
                        return {ITERATOR} | {
                            value for value in types if value.startswith("__element__:")
                        }
                    if MAPPING in types and method in {
                        "insert",
                        "emplace",
                        "emplace_hint",
                        "try_emplace",
                        "insert_or_assign",
                    }:
                        insert_end = tokens.pairs.get(function + 1, function + 1)
                        commas = [
                            index
                            for index in range(function + 2, insert_end)
                            if values[index] == ","
                            and tokens.enclosing[index] == function + 1
                            and not in_template_argument(values, index)
                        ]
                        first_argument = (
                            expression_receiver(
                                tokens,
                                function + 2,
                                commas[0] - 1,
                                imports,
                                namespace_aliases,
                                depth + 1,
                            )
                            if commas
                            else set()
                        )
                        hinted = method == "emplace_hint" or bool(
                            method != "emplace"
                            and ITERATOR in first_argument
                            and elements(first_argument) == elements(types)
                        )
                        iterator = {ITERATOR} | {
                            value for value in types if value.startswith("__element__:")
                        }
                        if hinted or MULTIMAPPING in types:
                            return iterator
                        # Unique-key insertion returns pair<iterator, bool>.
                        return {
                            PRODUCTS["std::pair"]
                            + json.dumps([0, None, value], separators=(",", ":"))
                            for value in iterator
                        } | {NO_INLINE_LAYOUT}
                    if MAPPING in types and method in {
                        "find",
                        "lower_bound",
                        "upper_bound",
                        "equal_range",
                    }:
                        iterator = {ITERATOR} | {
                            value for value in types if value.startswith("__element__:")
                        }
                        if method == "equal_range":
                            return {
                                PRODUCTS["std::pair"]
                                + json.dumps(
                                    [position, None, value], separators=(",", ":")
                                )
                                for position in (0, 1)
                                for value in iterator
                            } | {NO_INLINE_LAYOUT}
                        return iterator
                    if method in {
                        "begin",
                        "cbegin",
                        "rbegin",
                        "crbegin",
                        "end",
                        "cend",
                        "rend",
                        "crend",
                    } and elements(types):
                        return {ITERATOR} | {
                            value for value in types if value.startswith("__element__:")
                        }
                    types = source_member_types(
                        types, method, tokens, function, imports, namespace_aliases
                    )
                    declarations = (
                        object_members(
                            types,
                            method,
                            tokens,
                            function,
                            imports,
                            namespace_aliases,
                            api.members,
                            values[function - 1],
                        )
                        if types
                        else candidates(method, types, values[function - 1])
                    )
                    if not declarations:
                        explicit = values[function + 1 : opening]
                        if "std" in explicit and "vector" in explicit:
                            return {"__non_dart__"}
                        source_declarations = []
                        for marker in types:
                            if not marker.startswith(SOURCE_CLASS):
                                continue
                            owner = marker.removeprefix(SOURCE_CLASS)
                            for owner in [owner, *ancestry.get(owner, ())]:
                                declarations = source_returns.get((owner, method), ())
                                if declarations:
                                    source_declarations.extend(declarations)
                                    break
                        source_types = returns(source_declarations, depth + 1)
                        if source_types:
                            return source_types
                        if "__non_dart__" in types:
                            return {"__non_dart__"}
                    return returns(declarations)
                if function > 0 and values[function - 1] == "::":
                    data = qualified_data(tokens, function, imports, namespace_aliases)
                    variable = namespace_variable(tokens, function, namespace_aliases)
                    if data or variable:
                        return callable_data_result(
                            data or api.variables[variable], depth
                        )
                    qualifier = "::".join(qualifier_path(values, function))
                    resolved = resolve(
                        qualifier,
                        tokens,
                        function,
                        imports,
                        namespace_aliases,
                    )
                    if resolved:
                        return returns(
                            qualified_members(
                                tokens,
                                function,
                                imports,
                                namespace_aliases,
                                api.members,
                            )
                        )
                    free = qualified_function(
                        qualifier + "::" + method,
                        tokens.scopes.get(function, ()),
                        tokens,
                        function,
                        namespace_aliases,
                    )
                    if free:
                        return returns(api.free_functions[free])
                spelling = (
                    "::".join(qualifier_path(values, function)) + "::" + method
                    if function > 0 and values[function - 1] == "::"
                    else method
                )
                if spelling == method:
                    declarations, _ = lexical_members(
                        tokens, function, imports, namespace_aliases, api.members
                    )
                    if declarations:
                        return returns(declarations, depth + 1)
                callable_types = source_callable(
                    spelling, tokens, function, namespace_aliases
                )
                if callable_types is not None and any(
                    value.startswith(CALLABLE) for value in callable_types
                ):
                    return {
                        value.removeprefix(CALLABLE)
                        for value in callable_types
                        if value.startswith(CALLABLE) and value != CALLABLE
                    }
                source_declarations = source_function(
                    spelling, tokens, function, tokens.source_path, namespace_aliases
                )
                if source_declarations:
                    return returns(source_declarations, depth + 1)
                if spelling == method and not any(
                    binding[3] == method
                    and binding[0] <= function <= binding[1]
                    and binding[2] <= function
                    and set(tokens.branches[binding[2]])
                    <= set(tokens.branches[function])
                    for binding in tokens.bindings
                ):
                    free = free_function(
                        method,
                        tokens,
                        function,
                        tokens.source_path,
                        imports,
                        namespace_aliases,
                        depth + 1,
                    )
                    if free:
                        return returns(
                            [item for name in free for item in api.free_functions[name]]
                        )
                if standard_forwarder(spelling, tokens, function, namespace_aliases):
                    target = first_template_argument(values, function + 1)
                    if target and not {"(", "["}.intersection(target):
                        inferred = returns(
                            [
                                {
                                    "class": None,
                                    "name": "",
                                    "return_tokens": target,
                                    "index": function,
                                    "source": (
                                        tokens.source_path,
                                        tokens,
                                        imports,
                                        namespace_aliases,
                                    ),
                                }
                            ]
                        )
                        if inferred:
                            return inferred | {REFERENCE}
                    inferred = expression_receiver(
                        tokens,
                        opening + 1,
                        before - 1,
                        imports,
                        namespace_aliases,
                        depth,
                    )
                    return inferred | {REFERENCE} if inferred else inferred
                if standard_name(
                    spelling, tokens, function, namespace_aliases
                ) == "std::get" and not any(
                    b[3] == spelling and b[0] <= function <= b[1] and b[2] <= function
                    for b in tokens.bindings
                ):
                    target = first_template_argument(values, function + 1)
                    literal = re.fullmatch(
                        r"(0[xX][0-9a-fA-F]+|0[bB][01]+|0[0-7]*|[1-9][0-9]*)(?:[uUlL]*)",
                        "".join(target),
                    )
                    if literal:
                        number = literal[1]
                        selector = int(
                            number,
                            (
                                16
                                if number.lower().startswith("0x")
                                else (
                                    2
                                    if number.lower().startswith("0b")
                                    else 8 if number.startswith("0") else 10
                                )
                            ),
                        )
                    else:
                        selector = product_key(
                            target,
                            tokens.scopes.get(function, ()),
                            (
                                tokens.source_path,
                                tokens,
                                function,
                                imports,
                                namespace_aliases,
                            ),
                        )
                    types = expression_receiver(
                        tokens,
                        opening + 1,
                        before - 1,
                        imports,
                        namespace_aliases,
                        depth,
                    )
                    inferred = product_values(types, selector)
                    return inferred | {REFERENCE} if inferred else inferred
                if method in {"dynamic_cast", "static_cast"}:
                    typed = returns(
                        [
                            {
                                "class": None,
                                "name": "",
                                "return_tokens": values[function + 2 : opening - 1],
                                "index": function,
                                "source": (
                                    tokens.source_path,
                                    tokens,
                                    imports,
                                    namespace_aliases,
                                ),
                            }
                        ]
                    )
                    if typed:
                        return typed
                    for _, _, value in names_in(values[function + 1 : opening]):
                        resolved = resolve(
                            value, tokens, function, imports, namespace_aliases
                        )
                        if api.owner(resolved):
                            types = {resolved}
                            if "*" in values[function + 1 : opening]:
                                types.add(RAW_POINTER)
                            if {"&", "&&"}.intersection(values[function + 1 : opening]):
                                types.add(REFERENCE)
                            return types
                        if value in local_bases:
                            return set(local_bases[value])
                types = receiver(
                    tokens, function, imports, namespace_aliases, depth + 1
                )
                if NON_DART_CALLABLE in types or types == {"__non_dart__"}:
                    return {"__non_dart__"}
                if any(value.startswith(CALLABLE) for value in types):
                    return {
                        value.removeprefix(CALLABLE)
                        for value in types
                        if value.startswith(CALLABLE) and value != CALLABLE
                    }
                result = returns(candidates("operator()", types))
                if result:
                    return result
        if value == "]" and before in tokens.pairs:
            types = receiver(
                tokens, tokens.pairs[before] - 1, imports, namespace_aliases, depth + 1
            )
            if RAW_POINTER not in types:
                source_result = source_accessor_result(types, "operator[]", depth)
                if source_result is not None:
                    return source_result
            if MAPPING in types:
                indexed = (
                    types - {RAW_POINTER}
                    if RAW_POINTER in types
                    else product_values(elements(types), 1, "std::pair")
                )
                return indexed | {REFERENCE} if indexed else indexed
            if smart_kind(types):
                if RAW_POINTER in types:
                    return types - {RAW_POINTER}
                if smart_kind(types, ("std::shared_ptr", "std::unique_ptr")):
                    values = smart_values(types, ("std::shared_ptr", "std::unique_ptr"))
                    return (
                        (values - {RAW_ARRAY}) | {REFERENCE}
                        if RAW_ARRAY in values
                        else {"__non_dart__"}
                    )
                return {"__non_dart__"}
            if RAW_POINTER in types and RAW_ARRAY in types:
                return (types - {RAW_POINTER}) | {REFERENCE}
            result = returns(candidates("operator[]", types))
            indexed = elements(types) or (types - {RAW_POINTER})
            return result or (indexed | {REFERENCE} if indexed else indexed)
        if before > 1 and values[before - 1] in {"->", "."}:
            owner = receiver(tokens, before - 2, imports, namespace_aliases, depth + 1)
            if values[before - 1] == "->":
                owner = arrow_types(owner)
            if value in PAIR_MEMBERS and any(
                marker.startswith(PRODUCTS["std::pair"]) for marker in owner
            ):
                return product_values(owner, int(value == "second"), "std::pair")
            declarations = field_declarations(
                owner,
                value,
                tokens,
                before,
                imports,
                namespace_aliases,
                values[before - 1],
            )
            types = returns(declarations)
            if types:
                return types
        data = qualified_data(tokens, before, imports, namespace_aliases)
        if data:
            return returns(data, depth + 1)
        variable = namespace_variable(tokens, before, namespace_aliases)
        if variable and before and values[before - 1] == "::":
            return returns(api.variables[variable])
        spelling = "::".join(qualifier_path(values, before) + (value,))
        if standard_forwarder(spelling, tokens, before, namespace_aliases):
            return {"__non_dart__"}
        data, _ = (
            lexical_data(tokens, before, imports, namespace_aliases)
            if values[before - 1 : before] not in (["."], ["->"], ["::"])
            else ([], set())
        )
        if data:
            return returns(data, depth + 1)
        types = variable_types(tokens, before, fields)
        if variable:
            types |= returns(api.variables[variable])
        if values[before - 1 : before] not in (["."], ["->"]):
            callable_types = source_callable(
                spelling, tokens, before, namespace_aliases
            )
            if callable_types is not None:
                return callable_types
        if (
            IDENTIFIER.match(value)
            and values[before - 1 : before] not in (["."], ["->"])
            and (
                values[before - 1 : before] == ["::"]
                or not any(
                    binding[3] == value
                    and binding[0] <= before <= binding[1]
                    and binding[2] <= before
                    and set(tokens.branches[binding[2]]) <= set(tokens.branches[before])
                    for binding in tokens.bindings
                )
            )
        ):
            declarations = [
                item
                for item in source_function(
                    spelling, tokens, before, tokens.source_path, namespace_aliases
                )
                if item["class"] is None
                and item["name"].rpartition("::")[0] not in source_classes
            ]
            free = (
                [
                    qualified_function(
                        spelling,
                        tokens.scopes.get(before, ()),
                        tokens,
                        before,
                        namespace_aliases,
                    )
                ]
                if "::" in spelling
                else free_function(
                    value,
                    tokens,
                    before,
                    tokens.source_path,
                    imports,
                    namespace_aliases,
                    depth + 1,
                )
            )
            if not declarations:
                declarations += [
                    item for name in free if name for item in api.free_functions[name]
                ]
            if declarations:
                types = {
                    CALLABLE + value
                    for value in returns(declarations, depth + 1) or {""}
                }
                for item in declarations:
                    context = item.get("source")
                    resolve_parameter = lambda value: (
                        resolve(
                            value, context[1], item["index"], context[2], context[3]
                        )
                        if context
                        else api.resolve(
                            value,
                            item.get(
                                "declaration_scope",
                                tuple(item["name"].split("::")[:-1]),
                            ),
                        )
                    )
                    signature_item = item
                    if "static" in item["return_tokens"]:
                        signature_values = TOKEN.findall(item["signature"])
                        prefix = len(item["return_tokens"])
                        signature_item = {
                            **item,
                            "return_tokens": [
                                value
                                for value in item["return_tokens"]
                                if value != "static"
                            ],
                            "signature": " ".join(
                                [
                                    value
                                    for value in signature_values[:prefix]
                                    if value != "static"
                                ]
                                + signature_values[prefix:]
                            ),
                        }
                    signature = member_signature(signature_item, resolve_parameter)
                    if signature:
                        for parameter in signature[0]:
                            parameter_types = returns(
                                [
                                    {
                                        **item,
                                        "return_tokens": TOKEN.findall(
                                            " ".join(parameter)
                                        ),
                                    }
                                ],
                                depth + 1,
                            )
                            types.update(
                                ASSOCIATED + value for value in parameter_types
                            )
                return types
        if not types and before > 1 and values[before - 1] in {"->", "."}:
            if "__non_dart__" in owner:  # an unknown field of a non-DART object
                return {"__non_dart__"}
        return types

    # Wrapper aliases use the same declaration-context inference as returns.
    field_counts = defaultdict(int)
    for path, tokens, *_ in files:
        for index, (_, field) in typed_variables[path].items():
            if field:
                field_counts[tokens.values[index]] += 1
    for path, tokens, _, _, _, imports, namespace_aliases in files:
        for index, (prefix, field) in typed_variables[path].items():
            types = returns(
                [
                    {
                        "class": None,
                        "name": "",
                        "return_tokens": prefix,
                        "index": index,
                        "source": (path, tokens, imports, namespace_aliases),
                    }
                ]
            )
            if (
                DECLARED_TYPE in types
                or REFERENCE in types
                or any(
                    OPTIONAL in value
                    or value.startswith("__element__:")
                    or any(prefix in value for prefix in PRODUCTS.values())
                    or CALLABLE in value
                    or any(prefix in value for prefix in SMART_POINTERS.values())
                    for value in types
                )
            ):
                types = array_types(tokens, index, types)
                tokens.bindings = [
                    (*binding[:4], types) if binding[2] == index else binding
                    for binding in tokens.bindings
                ]
                export_callable(tokens, index, types)
            if field:
                name = tokens.values[index]
                if field_counts[name] == 1 and (
                    DECLARED_TYPE in types
                    or any(
                        prefix in value
                        for value in types
                        for prefix in SMART_POINTERS.values()
                    )
                ):
                    fields[name] = types
                else:
                    for binding in tokens.bindings:
                        if binding[2] == index:
                            fields[name].update(binding[4])

    # Propagate auto aliases and range elements from explicit fields and returns.
    # Nested captures and aliases can depend on each preceding declaration.
    passes = (
        max(
            (
                tokens.values.count("auto")
                + tokens.values.count("decltype")
                + len(tokens.lambda_captures)
                for _, tokens, *_ in files
            ),
            default=0,
        )
        + 1
    )
    for _ in range(passes):
        changed = False
        for _, tokens, classes, functions, _, imports, namespace_aliases in files:
            previous = tokens.bindings.copy()
            values = tokens.values
            function_names = {function["name_index"] for function in functions}
            for i, value in enumerate(values):
                if (
                    value == "decltype"
                    and values[i + 1 : i + 2] == ["("]
                    and i + 1 in tokens.pairs
                ):
                    closing = tokens.pairs[i + 1]
                    if values[i + 2 : closing] == ["auto"]:
                        continue
                    declared_types = declared_expression(
                        tokens, i + 2, closing - 1, imports, namespace_aliases
                    )
                    start = closing + 1
                    stop = statement_end(tokens, i)
                    for part, offset in declarators(
                        ["__decltype_type__", *values[start:stop]], None
                    ):
                        name = 1
                        while name < len(part) and part[name] in {
                            "const",
                            "volatile",
                            "*",
                            "&",
                            "&&",
                        }:
                            name += 1
                        if name >= len(part) or not IDENTIFIER.match(part[name]):
                            continue
                        j = start + offset + name - 1
                        if j in function_names or values[j + 1 : j + 2] not in (
                            [";"],
                            ["="],
                            [","],
                            [")"],
                            ["("],
                            ["{"],
                            ["["],
                            [":"],
                        ):
                            continue
                        # This slice is only the already-parsed outer
                        # cv/pointer/reference declarator, not decltype's operand.
                        inferred = shift_array_depth(
                            set(declared_types), part[1:name].count("*")
                        )
                        if "*" in part[1:name]:
                            inferred.add(RAW_POINTER)
                        if inferred and {"&", "&&"}.intersection(part[1:name]):
                            inferred.add(REFERENCE)
                        inferred = array_types(tokens, j, inferred)
                        tokens.bindings = [
                            binding for binding in tokens.bindings if binding[2] != j
                        ]
                        bind_variable(tokens, j, inferred)
                        export_callable(tokens, j, inferred)
                        if is_field(tokens, j, classes):
                            fields[values[j]].update(inferred)
                    continue
                if value != "auto":
                    continue
                start = i
                j = i + 1
                if values[max(0, i - 2) : i + 2] == ["decltype", "(", "auto", ")"]:
                    start, j = i - 2, i + 2
                while j < len(values) and values[j] in {"const", "&", "&&", "*"}:
                    j += 1
                if values[j : j + 1] == ["["]:
                    # shortcut: structured bindings are omitted; add ordered decomposition when downstream uses require it.
                    continue
                if j + 1 >= len(values) or not IDENTIFIER.match(values[j]):
                    continue
                if values[j + 1] == ":":
                    opening = tokens.enclosing[start]
                    if (
                        opening is None
                        or values[opening - 1 : opening] != ["for"]
                        or opening not in tokens.pairs
                    ):
                        continue
                    closing = tokens.pairs[opening]
                    range_types = receiver(
                        tokens, closing - 1, imports, namespace_aliases
                    )
                    inferred = elements(range_types)
                    if not inferred and "__non_dart__" in range_types:
                        inferred = {"__non_dart__"}
                    tokens.bindings = [b for b in tokens.bindings if b[2] != j]
                    bind_variable(
                        tokens,
                        j,
                        inferred,
                        (opening, statement_end(tokens, closing + 1)),
                    )
                    continue
                stop = statement_end(tokens, start)
                for part, offset in declarators(values[start:stop], None):
                    name = 4 if part[:4] == ["decltype", "(", "auto", ")"] else 1
                    while name < len(part) and part[name] in {"const", "&", "&&", "*"}:
                        name += 1
                    if name + 1 >= len(part) or not IDENTIFIER.match(part[name]):
                        continue
                    j = start + offset + name
                    if j in function_names:
                        continue
                    if values[j + 1] in {"(", "{"} and j + 1 in tokens.pairs:
                        end = tokens.pairs[j + 1]
                    elif values[j + 1] == "=":
                        end = start + offset + len(part)
                    else:
                        continue
                    if end < len(values):
                        infer = (
                            declared_expression
                            if part[:4] == ["decltype", "(", "auto", ")"]
                            else expression_receiver
                        )
                        inferred = infer(
                            tokens, j + 2, end - 1, imports, namespace_aliases
                        )
                        if inferred and {"&", "&&"}.intersection(part[:name]):
                            inferred.add(REFERENCE)
                        elif part[:4] != ["decltype", "(", "auto", ")"]:
                            inferred.discard(REFERENCE)
                        tokens.bindings = [b for b in tokens.bindings if b[2] != j]
                        bind_variable(tokens, j, inferred)
                        export_callable(tokens, j, inferred)

            for name, first, last, span in tokens.lambda_captures:
                inferred = expression_receiver(
                    tokens, first, last, imports, namespace_aliases
                )
                if inferred and values[name - 1 : name] == ["&"]:
                    inferred.add(REFERENCE)
                else:
                    inferred.discard(REFERENCE)
                tokens.bindings = [
                    binding for binding in tokens.bindings if binding[2] != name
                ]
                bind_variable(tokens, name, inferred, span)
            changed |= tokens.bindings != previous
        if not changed:
            break

    def record_constructed_value(resolved, constructed, path, tokens, index):
        row = tables["types"].get(resolved) or record_type(
            resolved, path, tokens, index
        )
        if not unevaluated_operand(tokens, index):
            retain_layout(row, [constructed])
        record_constructor(resolved, constructed, path, tokens, index)

    def optional_constructions(
        path, tokens, before, inferred, imports, namespace_aliases, suffix
    ):
        owned = optional_values(inferred)
        if RAW_POINTER in owned or smart_kind(owned) or NO_INLINE_LAYOUT in owned:
            return set()
        if (
            tokens.values[before] == ")"
            and before in tokens.pairs
            and tokens.pairs[before] + 2 == before
        ):
            before -= 1
        bindings = sorted(
            (
                binding
                for binding in tokens.bindings
                if binding[0] <= before <= binding[1]
                and binding[2] <= before
                and binding[3] == tokens.values[before]
                and binding[2] in typed_variables[path]
                and compatible(tokens.branches[binding[2]], tokens.branches[before])
            ),
            key=lambda binding: (binding[1] - binding[0], -binding[2]),
        )
        for binding in bindings:
            prefix = typed_variables[path][binding[2]][0]
            context = path, tokens, binding[2], imports, namespace_aliases
            prefix = construction_aliases(layout_prefix(prefix, context), api)
            optional = next(
                (
                    end
                    for start, end, name in names_in(prefix)
                    if name == "std::optional"
                    and not in_template_argument(prefix, start)
                ),
                None,
            )
            if optional is not None:
                element = first_template_argument(prefix, optional)
                if function_pointer_declarator(element) or function_type_signature(
                    element
                ):
                    return set()  # a null callable, not an object of its return type
                return contextual_constructors(
                    element, context, temporary=False, wrap=([], suffix)
                )
        declared = sorted(
            value.removeprefix(OPTIONAL_ELEMENT)
            for value in inferred
            if value.startswith(OPTIONAL_ELEMENT)
        )
        if declared:
            context = path, tokens, before, imports, namespace_aliases
            result = set()
            for element in declared:
                element = TOKEN.findall(element)
                if not (
                    function_pointer_declarator(element)
                    or function_type_signature(element)
                    or not value_argument(element)
                ):
                    result |= contextual_constructors(
                        element, context, (), temporary=False, wrap=([], suffix)
                    )
            return result
        return {
            (name, constructed)
            for name in owned
            if (constructed := api.constructible(name))
        }

    for path, tokens, _, _, _, imports, namespace_aliases in files:
        values = tokens.values
        for index, value in enumerate(values):
            if (
                value == "emplace"
                and index > 1
                and values[index - 1] in {".", "->"}
                and values[
                    template_end(values, index + 1) : template_end(values, index + 1)
                    + 1
                ]
                == ["("]
            ):
                inferred = receiver(tokens, index - 2, imports, namespace_aliases)
                if values[index - 1] == "->":
                    inferred = arrow_types(inferred)
                call = template_end(values, index + 1)
                suffix = [*values[call : tokens.pairs[call] + 1], ";"]
                for resolved, constructed in sorted(
                    optional_constructions(
                        path,
                        tokens,
                        index - 2,
                        inferred,
                        imports,
                        namespace_aliases,
                        suffix,
                    )
                ):
                    record_constructed_value(resolved, constructed, path, tokens, index)

    for (path, index), (
        tokens,
        sequence_classes,
        first,
        last,
        allocator,
        alternative,
        imports,
        namespace_aliases,
    ) in sequence_pending.items():
        if allocator and not sequence_allocator(
            path, tokens, *allocator, imports, namespace_aliases
        ):
            continue
        if sequence_allocator(path, tokens, first, last, imports, namespace_aliases):
            continue
        argument = expression_receiver(tokens, first, last, imports, namespace_aliases)
        if any(
            api.owner(name)
            or name.startswith("__element__:")
            or OPTIONAL in name
            or CALLABLE in name
            or any(prefix in name for prefix in SMART_POINTERS.values())
            for name in argument
        ):
            continue
        if alternative and head_hidden(  # the type alias is hidden: a real count
            tokens.values[alternative[1]],
            tokens,
            alternative[1],
            imports,
            namespace_aliases,
        ):
            sequence_classes = alternative[0]
        for resolved, constructed in sorted(sequence_classes):
            record_constructed_value(resolved, constructed, path, tokens, index)

    def retain_inferred_layout(inferred, path, tokens, index):
        if RAW_POINTER in inferred or ITERATOR in inferred or smart_kind(inferred):
            return
        while RAW_ARRAY in inferred:
            inferred = elements(inferred)
        inferred = optional_values(inferred) or inferred
        if RAW_POINTER in inferred:
            return
        owners = {
            name.removeprefix(INLINE_LAYOUT)
            for name in inferred
            if name.startswith(INLINE_LAYOUT)
        }
        if not owners and NO_INLINE_LAYOUT not in inferred:
            owners = {
                owner
                for name in inferred
                if not name.startswith("__")
                for owner in api.layout_owners(TOKEN.findall(name), references=True)
            }
        for owner in sorted(owners):
            rows = [
                row
                for name, row in tables["types"].items()
                if owner in api.layout_owners(TOKEN.findall(name))
            ]
            if not rows:
                rows = [record_type(owner, path, tokens, index)]
            for row in rows:
                retain_layout(row, [owner])

    # Layout operands can name auto results or dereferenced pointers, so use the
    # existing receiver evidence only after declaration propagation stabilizes.
    for path, tokens, _, _, _, imports, namespace_aliases in files:
        values = tokens.values
        inferred_declarations = set()
        for index, value in enumerate(values):
            if value not in {"auto", "decltype"} or in_template_argument(values, index):
                continue
            stop = statement_end(tokens, index)
            for part, offset in declarators(values[index:stop], None):
                prefix = 1
                if part[:2] == ["decltype", "("]:
                    prefix = Tokens(" ".join(part)).pairs.get(1, 0) + 1
                name = prefix
                while name < len(part) and part[name] in {
                    "const",
                    "volatile",
                    "*",
                    "&",
                    "&&",
                }:
                    name += 1
                if (
                    name < len(part)
                    and IDENTIFIER.match(part[name])
                    and value_argument(part[prefix:name])
                ):
                    inferred_declarations.add(index + offset + name)
        for _, _, index, _, inferred in tokens.bindings:
            if index in inferred_declarations and REFERENCE not in inferred:
                retain_inferred_layout(inferred, path, tokens, index)
        for index, first, last, _ in tokens.lambda_captures:
            if values[index - 1 : index] != ["&"]:
                inferred = expression_receiver(
                    tokens, first, last, imports, namespace_aliases
                )
                retain_inferred_layout(inferred, path, tokens, index)
        for index, value in enumerate(values):
            if value not in {"sizeof", "alignof"}:
                continue
            operand = layout_operator_operand(tokens, index)
            if operand is None:
                continue
            first, end = operand
            inferred = expression_receiver(
                tokens, first, end - 1, imports, namespace_aliases
            )
            retain_inferred_layout(inferred, path, tokens, index)

    for _, tokens, *_ in files:
        tokens.late = True
    for site in deferred_sites:
        construct_site(*site)

    for path, tokens, classes, functions, _, imports, namespace_aliases in files:
        values = tokens.values
        if not tokens.source_relevant:
            tokens.source_relevant = any(
                qualified_function(
                    name, tokens.scopes.get(start, ()), tokens, start, namespace_aliases
                )
                for start, _, name in names_in(values)
            )
        declaration_indices = {function["name_index"] for function in functions}
        class_bodies = {cls["body"] for cls in classes}
        for index, returned, function in [
            (
                # An explicit trailing return resolves in the body's class scope.
                (
                    f["body"]
                    if f.get("body") is not None
                    and return_type_tokens(f, trailing=True) != return_type_tokens(f)
                    else f["index"]
                ),
                return_type_tokens(f, trailing=True),
                f,
            )
            for f in functions
        ] + [
            (opening, returned, {"body": body})
            for opening, returned, body in tokens.lambda_returns
            # A named operator[]'s brackets are not lambda captures.
            if body not in {f.get("body") for f in functions}
        ]:
            context = (path, tokens, index, imports, namespace_aliases)
            for first, last in return_expressions(tokens, function):
                if values[first] != "{" or tokens.pairs.get(first) != last:
                    continue
                # Each braced return supplies its own initializer.
                for name, constructed in contextual_constructors(
                    construction_aliases(layout_prefix(returned, context), api),
                    context,
                    wrap=(
                        [],
                        [
                            *mark_array_copy(
                                tokens,
                                values[first : last + 1],
                                first,
                                context,
                                returned,
                            ),
                            ";",
                        ],
                    ),
                ):
                    record_constructor(
                        name, constructed, path, tokens, first, braced=True
                    )
        for cls in classes:
            bases = local_bases.get(cls["name"], set())
            for item in cls["members"]:
                signature = member_signature(
                    item,
                    lambda name: api.owner(
                        resolve(name, tokens, item["index"], imports, namespace_aliases)
                    )
                    or resolve(name, tokens, item["index"], imports, namespace_aliases),
                )
                # shortcut: explicit virtuals retain candidates, use compiler analysis to resolve full signatures.
                declarations = [
                    d
                    for d in api.members.get(item["name"], [])
                    if d["class"] in bases
                    and d["virtual"]
                    and (
                        item["override"]
                        or item["virtual"]
                        or signature is not None
                        and signature
                        == member_signature(
                            d,
                            lambda name: api.owner(
                                api.resolve(name, tuple(d["class"].split("::")))
                            )
                            or api.resolve(name, tuple(d["class"].split("::"))),
                        )
                    )
                ]
                if declarations:
                    row = add(
                        "overrides",
                        cls["name"] + "::" + item["name"],
                        path,
                        tokens.line(item["index"]),
                        base_classes=sorted(bases),
                        signatures=set(),
                        declarations=[],
                    )
                    row["signatures"].add(item["signature"])
                    row["declarations"].extend(
                        used_declaration(d) for d in declarations
                    )
        for i, name in enumerate(values):
            if name == "&" and (
                i == 0
                or values[i - 1]
                in {
                    "(",
                    "[",
                    "{",
                    "=",
                    ",",
                    ";",
                    ":",
                    "?",
                    "return",
                    "*",
                    "&",
                    "+",
                    "-",
                    "!",
                    "~",
                }
            ):
                span = layout_operator_operand(tokens, i)
                if span and not any(
                    binding[2] == span[1] - 1 for binding in tokens.bindings
                ):
                    inferred = expression_receiver(
                        tokens, span[0], span[1] - 1, imports, namespace_aliases
                    )
                    record(
                        "members",
                        "operator&",
                        unary_address(inferred) if inferred else [],
                        inferred,
                        path,
                        i,
                        tokens,
                    )
            syntax_operator = {
                "->": "operator->",
                "[": "operator[]",
                "(": "operator()",
            }.get(name)
            if syntax_operator and not any(
                b[2] == i - 1 for b in tokens.bindings
            ):  # declaration initializers are constructions, not operator calls
                inferred = receiver(tokens, i - 1, imports, namespace_aliases)
                record(
                    "members",
                    syntax_operator,
                    candidates(syntax_operator, inferred),
                    inferred,
                    path,
                    i,
                    tokens,
                )
            if name.startswith("DART_"):
                start = tokens.text.rfind("\n", 0, tokens.offsets[i]) + 1
                prefix = tokens.text[start : tokens.offsets[i]]
                if not re.fullmatch(r"\s*#\s*define\s+", prefix):
                    add(
                        "macros",
                        name,
                        path,
                        tokens.line(i),
                        declared_in_dart=name in api.macros,
                        defined_in_source=name in source_macros,
                    )
            if i in declaration_indices or not IDENTIFIER.match(name):
                continue
            j = template_end(values, i + 1)
            call = j < len(values) and values[j] == "("
            access = values[i - 1] if i and values[i - 1] in {".", "->"} else None
            if access is None and tag_named(tokens, i):
                continue  # an elaborated type name, never a value use
            qualifier = None
            if i and values[i - 1] == "::":
                qualifier = "::".join(qualifier_path(values, i))
                resolved = resolve(qualifier, tokens, i, imports, namespace_aliases)
            if call:
                data, inferred = callable_field(tokens, i, imports, namespace_aliases)
                if data:
                    record("data_members", name, data, inferred, path, i, tokens)
                    continue
                variable = (
                    namespace_variable(tokens, i, namespace_aliases)
                    if access is None
                    else None
                )
                if variable:
                    add(
                        "variables",
                        variable,
                        path,
                        tokens.line(i),
                        declarations=[
                            used_declaration(d) for d in api.variables[variable]
                        ],
                    )
                    continue
                data = qualified_data(tokens, i, imports, namespace_aliases)
                if data:
                    record("data_members", name, data, {resolved}, path, i, tokens)
                    continue
            if not call:
                if qualifier is not None:
                    begin = i - len(TOKEN.findall(qualifier)) - 1
                    free = (
                        None
                        if "using" in values[max(0, begin - 2) : begin]
                        else qualified_function(
                            qualifier + "::" + name,
                            tokens.scopes.get(i, ()),
                            tokens,
                            i,
                            namespace_aliases,
                        )
                    )
                    if free:
                        add("free_functions", free, path, tokens.line(i))
                variable = namespace_variable(tokens, i, namespace_aliases)
                if variable:
                    add(
                        "variables",
                        variable,
                        path,
                        tokens.line(i),
                        declarations=[
                            used_declaration(d) for d in api.variables[variable]
                        ],
                    )
                if access and tokens.source_relevant:
                    inferred = receiver(tokens, i - 2, imports, namespace_aliases)
                    if access == "->":
                        inferred = arrow_types(inferred)
                    inferred = source_member_types(
                        inferred, name, tokens, i, imports, namespace_aliases
                    )
                    declarations = field_declarations(
                        inferred, name, tokens, i, imports, namespace_aliases, access
                    )
                    record(
                        "data_members", name, declarations, inferred, path, i, tokens
                    )
                elif qualifier is not None and resolved:
                    declarations = qualified_data(tokens, i, imports, namespace_aliases)
                    record(
                        "data_members", name, declarations, {resolved}, path, i, tokens
                    )
                elif (
                    access is None
                    and qualifier is None
                    and name in api.data_members
                    and tokens.source_relevant
                    and tokens.enclosing[i] not in class_bodies
                    and not any(  # a local declaration that every build sees here
                        b[3] == name
                        and b[0] <= i <= b[1]
                        and b[2] <= i
                        and set(tokens.branches[b[2]]) <= set(tokens.branches[i])
                        for b in tokens.bindings
                    )
                ):
                    declarations, inferred = lexical_data(
                        tokens, i, imports, namespace_aliases
                    )
                    if inferred:
                        record(
                            "data_members",
                            name,
                            declarations,
                            inferred,
                            path,
                            i,
                            tokens,
                        )
                continue
            declarations = []
            inferred = set()
            if access:
                if not tokens.source_relevant:
                    continue
                inferred = receiver(tokens, i - 2, imports, namespace_aliases)
                if access == "->":
                    inferred = arrow_types(inferred)
                inferred = source_member_types(
                    inferred, name, tokens, i, imports, namespace_aliases
                )
                declarations = (
                    object_members(
                        inferred,
                        name,
                        tokens,
                        i,
                        imports,
                        namespace_aliases,
                        api.members,
                        access,
                    )
                    if inferred
                    else candidates(name, inferred)
                )
            elif qualifier is not None:
                if resolved:
                    inferred = {resolved}
                    declarations = qualified_members(
                        tokens, i, imports, namespace_aliases, api.members
                    )
                else:
                    owner = source_class(
                        qualifier,
                        tokens.scopes.get(i, ()),
                        imports,
                        namespace_aliases,
                        tokens.source_path,
                    )
                    bases = (
                        source_member_bases(
                            owner, name, tokens, i, imports, namespace_aliases
                        )
                        if owner
                        else set()
                    )
                    if bases:
                        inferred = bases
                        declarations = candidates(name, inferred)
                    free = qualified_function(
                        qualifier + "::" + name,
                        tokens.scopes.get(i, ()),
                        tokens,
                        i,
                        namespace_aliases,
                    )
                    if free and not tag_named(tokens, i):
                        add("free_functions", free, path, tokens.line(i))
            else:
                declarations, inferred = lexical_members(
                    tokens, i, imports, namespace_aliases, api.members
                )
                if not declarations and not tag_named(tokens, i):
                    for free in free_function(
                        name, tokens, i, path, imports, namespace_aliases
                    ):
                        add("free_functions", free, path, tokens.line(i))
            if j == i + 1:
                declarations = [
                    d
                    for d in declarations
                    if not (name == "get" and d["signature"].startswith("template"))
                ]
            record("members", name, declarations, inferred, path, i, tokens)

    result = {}
    for section, table in tables.items():
        result[section] = []
        for name in sorted(table):
            row = table[name]
            row["examples"] = sorted(row["examples"])[:3]
            for key in ("receiver_types", "signatures"):
                if key in row:
                    row[key] = sorted(row[key])
            for key in (
                "declarations",
                "pure_virtual_declarations",
                "default_member_initializer_declarations",
            ):
                if key not in row:
                    continue
                row[key] = sorted(
                    {json.dumps(d, sort_keys=True): d for d in row[key]}.values(),
                    key=lambda d: (d["class"], d["signature"]),
                )
            if section == "members":
                row["classification"] = classify_member(name, row["declarations"])
            result[section].append(row)
    return result


def revision(checkout):
    checkout = Path(checkout)
    sha = subprocess.check_output(
        ["git", "-C", str(checkout), "rev-parse", "HEAD"], text=True
    ).strip()
    status = subprocess.check_output(
        ["git", "-C", str(checkout), "status", "--porcelain", "--untracked-files=all"],
        text=True,
    )
    if status:
        raise ValueError("source checkout has local changes; scan a clean revision")
    return sha


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "checkout", type=Path, nargs="?", help="clean gz-physics checkout"
    )
    parser.add_argument("--gz-sim", type=Path, help="clean gz-sim checkout")
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    parser.add_argument("--check", action="store_true", help="compare without writing")
    args = parser.parse_args(argv)
    if args.checkout is None:
        print("SKIPPED: no gz-physics checkout supplied; inventory was not checked.")
        return 0
    try:
        recorded = json.loads(args.output.read_text()) if args.output.exists() else None
        if args.check and recorded is None:
            raise ValueError("no recorded inventory to check")
        api = index_api(ROOT / "dart")
        sources = {}
        for name, checkout in (("gz-physics", args.checkout), ("gz-sim", args.gz_sim)):
            if checkout is not None:
                sources[name] = {
                    "sha": revision(checkout),
                    **scan_sources(api, checkout),
                }
            elif recorded and name in recorded["sources"]:
                sources[name] = recorded["sources"][name]
                print(
                    f"SKIPPED: {name} was not rescanned; retaining its recorded inventory."
                )
            else:
                raise ValueError(
                    "initial generation requires --gz-sim to record its revision and direct DART use"
                )
        generated = {"schema_version": 1, "sources": sources}
        output = json.dumps(generated, indent=2, sort_keys=True) + "\n"
        if args.check:
            expected = args.output.read_text()
            if output != expected:
                print(
                    "FAILED: DART API inventory differs from the recorded declarations, uses or revisions."
                )
                print(
                    "".join(
                        difflib.unified_diff(
                            expected.splitlines(True),
                            output.splitlines(True),
                            fromfile="recorded",
                            tofile="regenerated",
                        )
                    ),
                    end="",
                )
                return 1
            print(
                "PASS: DART API inventory matches the recorded revision and declarations."
            )
        else:
            args.output.parent.mkdir(parents=True, exist_ok=True)
            args.output.write_text(output)
            print("Wrote DART API inventory.")
        return 0
    except (OSError, ValueError, subprocess.CalledProcessError) as error:
        print(f"FAILED: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
